def _hub_category_def(bucket, key):
    for item in _hub_category_defs(bucket):
        if item.get('key') == key:
            return item
    return {}


def _hub_category_score(provider, catalog, bucket, key):
    cat = _hub_category_def(bucket, key)
    if not cat:
        return 0
    if cat.get('special'):
        return 0
    # Sort-only virtual categories (A-Z / Z-A) should be available for any
    # catalogue inside the bucket, then the result rows are sorted after fetch.
    if cat.get('sort') in ('az', 'za'):
        return 1
    blob = _hub_words((provider or {}).get('name'), ((provider or {}).get('manifest') or {}).get('name'), (catalog or {}).get('name'), (catalog or {}).get('id'), (catalog or {}).get('description'), (catalog or {}).get('genres'), (catalog or {}).get('extra'))
    score = 0
    for kw in cat.get('kw') or []:
        nkw = _hub_words(kw)
        if not nkw:
            continue
        if nkw in blob:
            score += 10 + min(8, len(nkw.split()))
    # Helpful fallbacks for common catalog ids/names.
    if key == 'latest' and any(x in blob for x in ('latest', 'new', 'recent', 'release', 'now playing', 'airing')):
        score += 5
    if key == 'added' and any(x in blob for x in ('added', 'library', 'recent')):
        score += 6
    if key == 'newepisodes' and any(x in blob for x in ('episode', 'airing', 'new')):
        score += 6
    if key == 'popular' and 'popular' in blob:
        score += 8
    if key == 'trending' and ('trend' in blob or 'trending' in blob):
        score += 8
    if key == 'top' and any(x in blob for x in ('top', 'rated', 'imdb', 'best')):
        score += 8
    if key == 'arabic' and any(x in blob for x in ('arabic', 'arab', 'Arabic', 'Arabic')):
        score += 8
    if key == 'fourk' and any(x in blob for x in ('4k', '2160', 'uhd', 'hdr')):
        score += 8
    if bucket == 'turkish' and any(x in blob for x in ('turkish', 'turkey', 'turk', 'türkiye', 'turkiye', 'dizi', 'Turkish', "\u062a\u0631\u0643\u064a\u0629")):
        score += 12
    if bucket == 'korean' and any(x in blob for x in ('korean', 'korea', 'k-drama', 'kdrama', 'k drama', 'drakor', 'Korean', "\u0643\u0648\u0631\u064a\u0629")):
        score += 12
    return score


def _hub_category_catalog_entries(bucket, key, limit=6):
    scored = []
    for provider, catalog, b in _hub_catalog_entries(bucket=bucket):
        score = _hub_category_score(provider, catalog, bucket, key)
        if score > 0:
            scored.append((score, provider, catalog, b))
    scored.sort(key=lambda row: (-row[0], _hub_provider_rank(row[1]), str((row[2] or {}).get('name') or '').lower()))
    return [(p, c, b) for _score, p, c, b in scored[:max(1, int(limit or 6))]]


def _hub_best_search_provider(media_type='', bucket=''):
    candidates = []
    for provider, catalog, b in _hub_catalog_entries(bucket=bucket or None):
        if media_type and (catalog.get('type') or '') != media_type:
            continue
        if _catalog_supports_search(catalog):
            score = 100 - _hub_provider_rank(provider)
            if bucket and b == bucket:
                score += 20
            candidates.append((score, provider))
    candidates.sort(key=lambda row: (-row[0], str((row[1] or {}).get('name') or '').lower()))
    return candidates[0][1] if candidates else None


def _hub_pin_context(provider_id, catalog_id, media_type, bucket):
    return [
        ('Move up', 'RunPlugin(%s)' % build_url(action='catalog_pin_move', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, bucket=bucket, direction='up')),
        ('Move down', 'RunPlugin(%s)' % build_url(action='catalog_pin_move', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, bucket=bucket, direction='down')),
        ('Remove from this section', 'RunPlugin(%s)' % build_url(action='catalog_unpin', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, bucket=bucket)),
    ]


def _hub_render_pinned(bucket):
    pins = [x for x in _load_catalog_pins() if (x.get('bucket') or '') == bucket]
    for pin in pins:
        provider = store.get_provider(pin.get('provider_id') or '')
        if not provider:
            continue
        catalog_def = _catalog_definition(provider, pin.get('catalog_id') or '', pin.get('media_type') or '') or {}
        cname = pin.get('label') or catalog_def.get('name') or pin.get('catalog_id') or 'Catalog'
        media_type = pin.get('media_type') or catalog_def.get('type') or _hub_bucket_media_type(bucket)
        pname = provider.get('name') or pin.get('provider_name') or 'Source'
        label = '📌 %s' % cname
        url = build_url(action='catalog_all', provider_id=provider.get('id'), media_type=media_type, catalog_id=pin.get('catalog_id'), label=cname)
        ctx = _append_folder_tools_context(_hub_pin_context(provider.get('id') or '', pin.get('catalog_id') or '', media_type, bucket) + _hub_catalog_context(provider, catalog_def or {'id': pin.get('catalog_id'), 'name': cname, 'type': media_type}, bucket), bucket)
        add_item(label, url, info={'title': label, 'plot': tr('Section pinned from %s') % pname}, art=catalog_art(cname, media_type, provider.get('manifest') or {}, catalog_def), context_menu=ctx)
    return len(pins)


def _hub_item_context(provider, media_type, meta_id, item_label, source_mode=''):
    provider_id = (provider or {}).get('id') or ''
    return _build_source_picker_menu(media_type=media_type, canonical_id=meta_id, title=item_label, source_provider_id=provider_id)


def hub_category(bucket='movies', key='popular', page='0'):
    bucket = bucket or 'movies'
    key = key or 'popular'
    cat_def = _hub_category_def(bucket, key)
    if cat_def.get('special') == 'continue':
        return continue_watching()
    if cat_def.get('special') == 'nextup':
        try:
            return nextup()
        except Exception:
            return continue_watching()

    entries = _hub_category_catalog_entries(bucket, key, limit=5)
    sort_mode = (cat_def.get('sort') or '').lower()
    if sort_mode in ('az', 'za'):
        # For alphabetical views, read from more catalogues so pinned/secondary
        # sources still appear, then sort/dedupe locally.
        entries = _hub_catalog_entries(bucket=bucket)[:8]
    if not entries:
        add_item(tr('[COLOR yellow]No suitable add-on for this section[/COLOR]'), build_url(action='providers'), art=root_art('providers'), info={'title': 'Sources', 'plot': tr('Add or enable a catalog that supports this section')})
        add_item(tr('Show all %s catalogs') % _hub_bucket_title(bucket), build_url(action='hub_section', bucket=bucket, raw='1'), art=_hub_icon_for_bucket(bucket))
        return end_dir(content='files', cache=False)

    try:
        page_num = max(0, int(page or 0))
    except Exception:
        page_num = 0
    page_size = _listing_page_size()
    seen = set()
    ordered_rows = []

    def _run_catalog(job):
        provider, catalog, _b = job
        extra = {'limit': str(page_size)}
        if any(isinstance(x, dict) and x.get('name') == 'skip' for x in (catalog.get('extra') or [])):
            extra['skip'] = str(page_num * page_size)
        return fetch_catalog(provider, catalog.get('type') or _hub_bucket_media_type(bucket) or 'movie', catalog.get('id'), extra=extra, timeout_override=fast_timeout('catalog'))

    batch_size = max(1, min(parallel_workers(), 4, len(entries)))
    for job, result in iter_parallel(_run_catalog, entries, workers=batch_size):
        provider, catalog, _b = job
        media_type = catalog.get('type') or _hub_bucket_media_type(bucket) or 'movie'
        if isinstance(result, Exception):
            continue
        for meta in (result or {}).get('metas') or []:
            meta_id = str((meta or {}).get('id') or '')
            if not meta_id or meta_id in seen:
                continue
            seen.add(meta_id)
            ordered_rows.append((provider, catalog, media_type, meta_id, meta))
            if len(ordered_rows) >= page_size:
                break
        if len(ordered_rows) >= page_size:
            break

    if not ordered_rows:
        error(tr('Could not load this section from the current add-ons'))
        return end_dir(content='files', cache=False)

    if sort_mode in ('az', 'za'):
        def _title_key(row):
            try:
                return str(((row[4] or {}).get('name') or row[3] or '')).lower().strip()
            except Exception:
                return ''
        ordered_rows.sort(key=_title_key, reverse=(sort_mode == 'za'))

    try:
        favorite_keys = favorites_store.favorite_keys()
    except Exception:
        favorite_keys = set()
    first_fanart = ''
    for provider, catalog, media_type, meta_id, meta in ordered_rows[:page_size]:
        item_label = meta.get('name') or meta_id
        try:
            _meta_mem_put(media_type, meta_id, meta, source_provider_id=provider.get('id') or '')
        except Exception:
            pass
        fallback = _item_fallback_art(provider, media_type, catalog, item_label)
        art = _resolve_meta_art(provider, media_type, meta, fallback_art=fallback)
        if not first_fanart and art.get('fanart'):
            first_fanart = art.get('fanart')
        ids = extract_ids(meta)
        path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=meta_id, title=item_label, tmdb_id=ids.get('tmdb_id') or '', imdb_id=ids.get('imdb_id') or '', tvdb_id=ids.get('tvdb_id') or '', source_provider_id=provider.get('id') or '', ui_seed=art)
        ctx_menu = _append_folder_tools_context(_hub_item_context(provider, media_type, meta_id, item_label), bucket)
        already_fav = (str(media_type or ''), str(meta_id or '')) in favorite_keys
        if already_fav:
            ctx_menu.append(('Remove from favorites', 'RunPlugin(%s)' % build_url(action='fav_remove', media_type=media_type, canonical_id=meta_id)))
        else:
            ctx_menu.append(('Add to favorites', 'RunPlugin(%s)' % build_url(action='fav_add', media_type=media_type, canonical_id=meta_id, title=item_label, poster=art.get('poster') or '', background=art.get('fanart') or '', clearlogo=art.get('clearlogo') or '', year=str((_meta_info(meta).get('year') or 0)))))
        add_item(item_label, path, is_folder=path_is_folder, info=_meta_info(meta), art=art, ids=ids, context_menu=ctx_menu, is_favorite=already_fav)
    if first_fanart:
        try:
            xbmcgui.Window(WINDOW_ID).setProperty('fanart', first_fanart)
        except Exception:
            pass
    if len(ordered_rows) >= page_size:
        if not globals().get('_pagination_hidden', lambda: False)():
            add_item(tr('More'), build_url(action='hub_category', bucket=bucket, key=key, page=str(page_num + 1)), art=root_art('catalogs'), info={'title': tr('More')})
    return end_dir(content=_hub_directory_content(bucket), cache=True)



def _catalog_pins_path():
    return os.path.join(_profile_path(), 'hub_catalog_pins.json')


def _load_catalog_pins():
    try:
        path = _catalog_pins_path()
        if not xbmcvfs.exists(path):
            return []
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh) or []
        return data if isinstance(data, list) else []
    except Exception:
        return []


def _save_catalog_pins(rows):
    try:
        profile = _profile_path()
        if not xbmcvfs.exists(profile):
            xbmcvfs.mkdirs(profile)
        with open(_catalog_pins_path(), 'w', encoding='utf-8') as fh:
            json.dump(rows or [], fh, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _catalog_pin_key(provider_id, catalog_id, media_type):
    return '%s|%s|%s' % (provider_id or '', catalog_id or '', media_type or '')


def _catalog_definition(provider, catalog_id, media_type=''):
    for c in _provider_catalogs(provider or {}):
        if str(c.get('id') or '') == str(catalog_id or '') and (not media_type or str(c.get('type') or '') == str(media_type or '')):
            return c
    for c in _provider_catalogs(provider or {}):
        if str(c.get('id') or '') == str(catalog_id or ''):
            return c
    return {}


def _hub_catalog_context(provider, catalog, bucket=''):
    provider_id = (provider or {}).get('id') or ''
    media_type = (catalog or {}).get('type') or _hub_bucket_media_type(bucket) or ''
    catalog_id = (catalog or {}).get('id') or ''
    label = (catalog or {}).get('name') or catalog_id or 'Catalog'
    items = []
    for row in _home_bucket_defs(include_collection=False):
        b = row.get('bucket') or ''
        title = row.get('title') or _hub_bucket_title(b)
        items.append((tr('Add inside %s') % title, 'RunPlugin(%s)' % build_url(action='catalog_pin', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, label=label, bucket=b)))
        for sub in _home_subfolders(b):
            sb = sub.get('bucket') or ''
            st = sub.get('title') or _hub_bucket_title(sb)
            items.append((tr('Add inside %s / %s') % (title, st), 'RunPlugin(%s)' % build_url(action='catalog_pin', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, label=label, bucket=sb)))
    # Collection is kept for favourites/Trakt/manual sets only. Source catalogues
    # are pinned to Home folders/Sub folders so they do not clutter Collection.
    items.append(('Add a new sub folder', 'RunPlugin(%s)' % build_url(action='home_subfolder_add', parent=bucket or 'movies')))
    items.append(('Add new home folder', 'RunPlugin(%s)' % build_url(action='home_folder_add')))
    return items




def _catalog_pin_targets():
    targets = []
    for row in _home_bucket_defs(include_collection=False):
        b = row.get('bucket') or ''
        title = row.get('title') or _hub_bucket_title(b)
        targets.append((title, b))
        for sub in _home_subfolders(b):
            sb = sub.get('bucket') or ''
            st = sub.get('title') or _hub_bucket_title(sb)
            targets.append(('%s / %s' % (title, st), sb))
    return [(t, b) for t, b in targets if b and b != 'collection']


def catalog_pin_target_menu(provider_id='', catalog_id='', media_type='', label=''):
    targets = _catalog_pin_targets()
    if not targets:
        notify(tr('Add a home folder or sub folder first'))
        return end_dir()
    idx = xbmcgui.Dialog().select(tr('Add catalog inside'), [tr(t[0]) for t in targets])
    if idx < 0:
        return end_dir()
    title, bucket = targets[idx]
    return catalog_pin(provider_id=provider_id, catalog_id=catalog_id, media_type=media_type, label=label, bucket=bucket)




def _catalog_filter_context(provider_id='', media_type='', catalog_id='', catalog_def=None, force_remote='', return_action='', return_bucket=''):
    """Context-menu access to catalog filters everywhere.

    Keep Sources and catalog listings clean: no visible filter rows. The same
    per-catalog filters are available from long-press / options on catalog
    rows and on media items inside catalog listings.
    """
    items = []
    provider_id = str(provider_id or '')
    media_type = str(media_type or '')
    catalog_id = str(catalog_id or '')
    if not provider_id or not catalog_id:
        return items
    try:
        if catalog_def is None:
            provider = store.get_provider(provider_id) or {}
            catalog_def = _catalog_definition(provider, catalog_id, media_type) or {}
        extras = [e for e in _available_filter_extras(catalog_def or {})
                  if _extra_mode((e.get('name') or ''), catalog_def or {}) == 'filter']
        if not extras:
            return items
        state = _filter_state(provider_id, catalog_id)
        active = []
        for e in extras:
            name = e.get('name') or ''
            if not name:
                continue
            value = (state or {}).get(name)
            if value not in (None, ''):
                active.append('%s: %s' % (_filter_label(name), value))
        label = 'Catalog filter'
        if active:
            label += '  •  %s' % ' | '.join(active[:3])
        items.append((label, 'Container.Update(%s)' % build_url(
            action='filters_menu', provider_id=provider_id, media_type=media_type,
            catalog_id=catalog_id, force_remote=force_remote or '',
            return_action=return_action or '', return_bucket=return_bucket or ''
        )))
    except Exception:
        pass
    return items

def _catalog_has_filter_extras(catalog_def):
    try:
        return bool([e for e in _available_filter_extras(catalog_def or {}) if _extra_mode((e.get('name') or ''), catalog_def or {}) == 'filter'])
    except Exception:
        return False


def _catalog_add_toolbar(provider, provider_id, media_type, catalog_id, catalog_def, label=''):
    """Render the "+ Add to home" inline button at the top of a catalog page.

    v3.9.82: gated behind the clean_catalog_view setting (default True =
    hidden). The action stays accessible via long-press on any catalog
    item (the same context menu we attach via _hub_catalog_context),
    so power users keep one-tap access without cluttering the visual
    layout for first-time viewers. Reddit launch needs catalog pages
    that look like content browsers, not toolboxes.
    """
    try:
        _clean = (ADDON.getSetting('clean_catalog_view') or 'false').strip().lower() in ('true', '1', 'yes', 'on')
    except Exception:
        _clean = False
    if _clean:
        return
    cname = label or (catalog_def or {}).get('name') or catalog_id or 'Catalog'
    ctx = _hub_catalog_context(provider, catalog_def or {'id': catalog_id, 'name': cname, 'type': media_type}, _hub_catalog_bucket(provider, catalog_def or {}))
    add_item(
        '[COLOR yellow]+ Add this catalog to home[/COLOR]',
        build_url(action='catalog_pin_target_menu', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, label=cname),
        is_folder=False,
        info={'title': 'Add to home', 'plot': 'Pin this catalog inside Movies/Series/Anime/Arabic or any sub folder. It is not added to a collection.'},
        art=root_art('add'),
        context_menu=ctx,
        properties={'SpecialSort': 'top'},
    )


def _folder_has_search(entries):
    try:
        return any(_catalog_supports_search(catalog) for _provider, catalog, _b, _pin in (entries or []))
    except Exception:
        return False


def _folder_tools_context(bucket, entries=None):
    """Clean folder actions for Kodi context menu.

    The folder view should stay visually clean: no filter/tool rows at the top.
    These actions are available from Options / long-press on any item inside the
    folder, and also on the home folder itself.
    """
    bucket = bucket or 'movies'
    try:
        entries = list(entries or _hub_pinned_catalog_entries(bucket) or [])
    except Exception:
        entries = []
    title = _hub_bucket_title(bucket)
    items = []
    try:
        if _folder_filter_groups(entries):
            state = _folder_filter_state(bucket)
            active = []
            group_by_key = {g.get('key'): g for g in _folder_filter_groups(entries)}
            for key, value in (state or {}).items():
                if value in (None, ''):
                    continue
                group = group_by_key.get(key) or {'label': _folder_filter_label(key)}
                active.append('%s: %s' % (group.get('label') or _folder_filter_label(key), value))
            label = 'Folder filter'
            if active:
                label += '  •  %s' % ' | '.join(active)
            items.append((label, 'Container.Update(%s)' % build_url(action='folder_filters_menu', bucket=bucket)))
    except Exception:
        pass
    if _folder_has_search(entries):
        items.append((tr('Search inside %s') % title, 'Container.Update(%s)' % build_url(action='hub_search_folder', bucket=bucket)))
    view_label = 'Group by add-on' if _folder_view_mode(bucket) == 'merged' else 'Merge content'
    items.append((view_label, 'RunPlugin(%s)' % build_url(action='folder_toggle_view', bucket=bucket)))
    dedupe_label = 'Show duplicates' if _folder_dedupe_enabled(bucket) else 'Hide duplicates'
    items.append((dedupe_label, 'RunPlugin(%s)' % build_url(action='folder_toggle_dedupe', bucket=bucket)))
    play_label = 'Quick play from the same add-on' if _folder_play_mode(bucket) == 'normal' else 'Normal playback mode'
    items.append((play_label, 'RunPlugin(%s)' % build_url(action='folder_toggle_play_mode', bucket=bucket)))
    items.append(('Refresh this folder', 'RunPlugin(%s)' % build_url(action='folder_refresh', bucket=bucket)))
    if entries:
        items.append(('Order the add-ons in this folder', 'Container.Update(%s)' % build_url(action='hub_section', bucket=bucket, raw='1')))
    return items


def _append_folder_tools_context(ctx, bucket, entries=None):
    out = list(ctx or [])
    try:
        tools = _folder_tools_context(bucket, entries=entries)
        if tools:
            out.extend(tools)
    except Exception:
        pass
    return out


def _hub_folder_tools_toolbar(bucket, entries):
    # Clean UI: folder filters/tools are in the context menu, not as visible rows.
    return None


def _hub_filter_toolbar_for_pins(bucket, entries):
    return _hub_folder_tools_toolbar(bucket, entries)


def _folder_prefs_path():
    return os.path.join(_profile_path(), 'hub_folder_prefs.json')


def _load_folder_prefs():
    try:
        path = _folder_prefs_path()
        if not xbmcvfs.exists(path):
            return {}
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh) or {}
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_folder_prefs(data):
    try:
        profile = _profile_path()
        if not xbmcvfs.exists(profile):
            xbmcvfs.mkdirs(profile)
        with open(_folder_prefs_path(), 'w', encoding='utf-8') as fh:
            json.dump(data or {}, fh, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _folder_pref(bucket, key, default=None):
    prefs = _load_folder_prefs().get(str(bucket or ''), {})
    if not isinstance(prefs, dict):
        return default
    return prefs.get(key, default)


def _set_folder_pref(bucket, key, value):
    data = _load_folder_prefs()
    bucket = str(bucket or '')
    current = dict(data.get(bucket, {}) if isinstance(data.get(bucket, {}), dict) else {})
    if value in (None, '', '__clear__'):
        current.pop(key, None)
    else:
        current[key] = value
    if current:
        data[bucket] = current
    else:
        data.pop(bucket, None)
    _save_folder_prefs(data)
    return current


def _folder_view_mode(bucket):
    value = str(_folder_pref(bucket, 'view_mode', 'merged') or 'merged').strip().lower()
    return 'sources' if value in ('sources', 'source', 'by_source', 'by-source') else 'merged'


def _folder_dedupe_enabled(bucket):
    value = str(_folder_pref(bucket, 'dedupe', '1') or '1').strip().lower()
    return value not in ('0', 'false', 'no', 'off')


def _folder_play_mode(bucket):
    value = str(_folder_pref(bucket, 'play_mode', 'normal') or 'normal').strip().lower()
    return 'same_source_auto' if value in ('same_source_auto', 'same-source-auto', 'same', 'only') else 'normal'


def _notify_and_refresh(message=''):
    if message:
        notify(message)
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir()


def folder_toggle_view(bucket='movies'):
    current = _folder_view_mode(bucket)
    new_value = 'sources' if current == 'merged' else 'merged'
    _set_folder_pref(bucket, 'view_mode', new_value)
    label = 'Group by add-on' if new_value == 'sources' else 'Merge content'
    return _notify_and_refresh(tr('Folder view changed: %s') % label)


def folder_toggle_dedupe(bucket='movies'):
    enabled = _folder_dedupe_enabled(bucket)
    _set_folder_pref(bucket, 'dedupe', '0' if enabled else '1')
    return _notify_and_refresh(tr('Hide duplicates: %s') % (tr('Stopped') if enabled else tr('Enabled')))


def folder_toggle_play_mode(bucket='movies'):
    current = _folder_play_mode(bucket)
    new_value = 'same_source_auto' if current == 'normal' else 'normal'
    _set_folder_pref(bucket, 'play_mode', new_value)
    label = 'Quick play from the same add-on' if new_value == 'same_source_auto' else 'Normal mode'
    return _notify_and_refresh(tr('Playback mode: %s') % label)


def folder_refresh(bucket='movies'):
    removed = 0
    try:
        from .nuviohub import client as _client_mod
        removed += int(_client_mod.clear_http_cache() or 0)
    except Exception:
        pass
    try:
        _SEARCH_RESULT_CACHE.clear()
        _SEARCH_RESULT_CACHE_ORDER[:] = []
    except Exception:
        pass
    try:
        _clear_folder_filters(bucket)
    except Exception:
        pass
    return _notify_and_refresh('Folder refreshed and catalog cache cleared')


def _clean_title_for_key(value):
    text = str(value or '').strip().lower()
    try:
        text = unicodedata.normalize('NFKD', text)
    except Exception:
        pass
    text = re.sub(r'\[[^\]]+\]|\([^\)]*\b(?:\d{4}|1080p|720p|4k|uhd|hdr|dubbed|subbed)\b[^\)]*\)', ' ', text, flags=re.I)
    text = re.sub(r'\b(?:the|a|an)\b', ' ', text, flags=re.I)
    # --- nuviohub-405-patch --- fold Arabic spelling variants before stripping
    text = _ar_fold(text)
    text = re.sub(r'[^0-9a-z\u0600-\u06FF]+', ' ', text, flags=re.I)
    return re.sub(r'\s+', ' ', text).strip()


def _year_for_key(meta):
    meta = meta or {}
    for key in ('year', 'releaseInfo', 'released', 'premiered'):
        value = meta.get(key)
        if value in (None, ''):
            continue
        m = re.search(r'(19|20)\d{2}', str(value))
        if m:
            return m.group(0)
    return ''


# --- nuviohub-405-patch ---
_AR_DIACRITICS = re.compile("[\u064b-\u065f\u0670\u0640]")
_AR_DIGITS = {}
for _i in range(10):
    _AR_DIGITS[chr(0x0660 + _i)] = str(_i)   # Arabic-Indic
    _AR_DIGITS[chr(0x06F0 + _i)] = str(_i)   # Extended Arabic-Indic


def _ar_fold(text):
    """Normalise Arabic so spelling variants collapse to one form.

    Catalogs disagree constantly on hamza, ta marbuta, final ya and
    diacritics; without folding, every variant becomes its own dedupe key.
    """
    if not text:
        return text
    text = _AR_DIACRITICS.sub('', text)
    out = []
    for ch in text:
        if ch in _AR_DIGITS:
            out.append(_AR_DIGITS[ch])
        elif ch in "\u0622\u0623\u0625\u0671":      # آ أ إ ٱ
            out.append("\u0627")                      # ا
        elif ch == "\u0649":                          # ى
            out.append("\u064a")                      # ي
        elif ch == "\u0629":                          # ة
            out.append("\u0647")                      # ه
        elif ch == "\u0624":                          # ؤ
            out.append("\u0648")                      # و
        elif ch == "\u0626":                          # ئ
            out.append("\u064a")
        else:
            out.append(ch)
    text = ''.join(out)
    # a leading definite article is optional in most catalog titles
    text = re.sub("^\u0627\u0644", '', text)
    text = re.sub("\\s\u0627\u0644", ' ', text)
    return text


def _meta_dedupe_alias_keys(media_type, meta_id, meta):
    """Every identity this item can be recognised by, strongest first."""
    meta = meta or {}
    mt = str(media_type or '').lower()
    ids = extract_ids(meta) or {}
    strong = []
    for key, prefix in (('imdb_id', 'imdb'), ('tmdb_id', 'tmdb'), ('tvdb_id', 'tvdb')):
        value = str(ids.get(key) or '').strip().lower()
        if value:
            strong.append('%s:%s:%s' % (mt, prefix, value))
    raw = str(meta_id or meta.get('id') or '').strip().lower()
    m = re.search(r'\btt\d{5,10}\b', raw)
    if m:
        key = '%s:imdb:%s' % (mt, m.group(0))
        if key not in strong:
            strong.append(key)
    title = _clean_title_for_key(meta.get('name') or meta.get('title') or meta_id)
    year = _year_for_key(meta)
    if title and year:
        strong.append('%s:title:%s:%s' % (mt, title, year))
    weak = '%s:title:%s' % (mt, title) if title and not year else None
    if not strong and not weak:
        strong.append('%s:id:%s' % (mt, raw))
    return strong, weak


def _dedupe_rows(rows, rank_of, keys_of):
    """Union-find merge so one item linking two ids collapses both groups.

    rank_of(row)  -> comparable; the smallest wins and represents the group.
    keys_of(row)  -> (strong_keys, weak_key_or_None)
    """
    parent = {}

    def find(k):
        root = k
        while parent.get(root, root) != root:
            root = parent[root]
        while parent.get(k, k) != root:
            parent[k], k = root, parent[k]
        return root

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    deferred = []
    owner = {}
    for row in rows:
        strong, weak = keys_of(row)
        if not strong:
            deferred.append((row, weak))
            continue
        for key in strong:
            parent.setdefault(key, key)
        for key in strong[1:]:
            union(strong[0], key)
        owner.setdefault(find(strong[0]), []).append(row)

    # rebuild after all unions: a later row may have joined two earlier groups
    groups = {}
    for row in rows:
        strong, weak = keys_of(row)
        if not strong:
            continue
        groups.setdefault(find(strong[0]), []).append(row)

    # title-only rows attach to a title group only when it is unambiguous
    title_index = {}
    for root, members in groups.items():
        for row in members:
            strong, _weak = keys_of(row)
            for key in strong:
                if ':title:' in key:
                    bare = key.rsplit(':', 1)[0]
                    title_index.setdefault(bare, set()).add(root)
    for row, weak in deferred:
        candidates = title_index.get(weak) if weak else None
        if candidates and len(candidates) == 1:
            groups[next(iter(candidates))].append(row)
        else:
            groups[weak or id(row)] = [row]

    best = []
    for members in groups.values():
        best.append(min(members, key=rank_of))
    return best


def _meta_dedupe_key(media_type, meta_id, meta):
    meta = meta or {}
    ids = extract_ids(meta) or {}
    for key, prefix in (('imdb_id', 'imdb'), ('tmdb_id', 'tmdb'), ('tvdb_id', 'tvdb')):
        value = str(ids.get(key) or '').strip().lower()
        if value:
            return '%s:%s:%s' % (str(media_type or '').lower(), prefix, value)
    raw = str(meta_id or meta.get('id') or '').strip().lower()
    m = re.search(r'\btt\d{5,10}\b', raw)
    if m:
        return '%s:imdb:%s' % (str(media_type or '').lower(), m.group(0))
    if raw.startswith(('tmdb:', 'tvdb:', 'imdb:')):
        return '%s:%s' % (str(media_type or '').lower(), raw)
    title = _clean_title_for_key(meta.get('name') or meta.get('title') or meta_id)
    year = _year_for_key(meta)
    if title:
        return '%s:title:%s:%s' % (str(media_type or '').lower(), title, year)
    return '%s:id:%s' % (str(media_type or '').lower(), raw)


def _parse_meta_timestamp(value, prefer_day_first=True):
    """Best-effort timestamp parser for folder-wide global sorting.

    Stremio catalogues are inconsistent: some expose ISO `released`, some use
    `releaseInfo` (year only), and some custom catalogues expose dd/mm values
    such as 21/4. Missing values intentionally sort last.
    """
    if value in (None, ''):
        return 0.0
    if isinstance(value, (int, float)):
        try:
            val = float(value)
            # Treat large values as unix timestamps, tiny values as unknown.
            return val if val > 100000 else 0.0
        except Exception:
            return 0.0
    text = str(value or '').strip()
    if not text:
        return 0.0
    # ISO / YYYY-MM-DD / YYYY.MM.DD / YYYY/MM/DD
    m = re.search(r'((?:19|20)\d{2})[-/.](\d{1,2})[-/.](\d{1,2})', text)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return time.mktime((y, mo, d, 0, 0, 0, 0, 0, -1))
        except Exception:
            pass
    # DD/MM/YYYY or MM/DD/YYYY. For Arabic/Turkish/Korean custom sources we
    # default to day-first because users commonly write 21/4.
    m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.]((?:19|20)\d{2})\b', text)
    if m:
        a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        d, mo = (a, b) if prefer_day_first or a > 12 else (b, a)
        try:
            return time.mktime((y, mo, d, 0, 0, 0, 0, 0, -1))
        except Exception:
            pass
    # DD/MM or MM/DD without year — assume current year so 21/4 can still be
    # merged against all catalogues instead of keeping each source grouped.
    m = re.search(r'\b(\d{1,2})[-/.](\d{1,2})\b', text)
    if m:
        a, b = int(m.group(1)), int(m.group(2))
        d, mo = (a, b) if prefer_day_first or a > 12 else (b, a)
        try:
            y = int(time.localtime().tm_year)
            return time.mktime((y, mo, d, 0, 0, 0, 0, 0, -1))
        except Exception:
            pass
    m = re.search(r'\b((?:19|20)\d{2})\b', text)
    if m:
        try:
            return time.mktime((int(m.group(1)), 1, 1, 0, 0, 0, 0, 0, -1))
        except Exception:
            return float(int(m.group(1)))
    return 0.0


def _meta_release_timestamp(meta):
    meta = meta or {}
    candidates = [
        meta.get('released'), meta.get('releaseDate'), meta.get('release_date'),
        meta.get('premiered'), meta.get('firstAired'), meta.get('aired'),
        meta.get('date'), meta.get('releaseInfo'), meta.get('year'),
    ]
    bh = meta.get('behaviorHints') or {}
    if isinstance(bh, dict):
        candidates.extend([bh.get('released'), bh.get('releaseDate'), bh.get('release_date'), bh.get('date')])
    for value in candidates:
        ts = _parse_meta_timestamp(value)
        if ts:
            return ts
    return 0.0


def _meta_added_timestamp(meta):
    meta = meta or {}
    candidates = [
        meta.get('added'), meta.get('dateAdded'), meta.get('date_added'),
        meta.get('createdAt'), meta.get('created_at'), meta.get('updatedAt'), meta.get('updated_at'),
        meta.get('modifiedAt'), meta.get('modified_at'), meta.get('lastAdded'), meta.get('last_added'),
    ]
    bh = meta.get('behaviorHints') or {}
    if isinstance(bh, dict):
        candidates.extend([bh.get('dateAdded'), bh.get('added'), bh.get('createdAt'), bh.get('updatedAt')])
    for value in candidates:
        ts = _parse_meta_timestamp(value)
        if ts:
            return ts
    return 0.0


def _meta_rating_value(meta):
    meta = meta or {}
    for key in ('imdbRating', 'rating', 'voteAverage', 'score'):
        value = meta.get(key)
        try:
            if value not in (None, ''):
                return float(str(value).replace(',', '.'))
        except Exception:
            continue
    return 0.0


def _folder_sort_mode(bucket):
    state = _folder_filter_state(bucket)
    tokens = []
    for key, value in (state or {}).items():
        tokens.append(_norm_filter_token(key))
        tokens.append(_norm_filter_token(value))
    text = ' '.join([t for t in tokens if t])
    compact = text.replace(' ', '').replace('-', '').replace('_', '')
    if any(x in compact for x in ('lastrelease', 'latestrelease', 'releasedate', 'released', 'release')):
        return 'release_desc'
    if any(x in compact for x in ('lastadded', 'recentlyadded', 'dateadded', 'added')):
        return 'added_desc'
    if any(x in compact for x in ('atoz', 'az', 'titleasc', 'alphabetical')):
        return 'title_asc'
    if any(x in compact for x in ('ztoa', 'za', 'titledesc')):
        return 'title_desc'
    if any(x in compact for x in ('toprated', 'rating', 'imdb', 'score')):
        return 'rating_desc'
    return 'rank_mix'


def _folder_global_sort_rows(rows, bucket):
    """Sort merged pinned-catalog rows as one list, not source-by-source.

    Row format: (provider, catalog, media_type, meta_id, meta, source_index,
    item_index). The final renderer accepts the first five fields only.
    """
    mode = _folder_sort_mode(bucket)

    def title_value(meta, meta_id=''):
        return _clean_title_for_key((meta or {}).get('name') or (meta or {}).get('title') or meta_id)

    def key(row):
        provider, catalog, media_type, meta_id, meta, source_index, item_index = row
        source_index = int(source_index or 0)
        item_index = int(item_index or 0)
        title = title_value(meta, meta_id)
        if mode == 'release_desc':
            ts = _meta_release_timestamp(meta)
            return (0 if ts else 1, -float(ts or 0.0), source_index, item_index, title)
        if mode == 'added_desc':
            ts = _meta_added_timestamp(meta)
            return (0 if ts else 1, -float(ts or 0.0), source_index, item_index, title)
        if mode == 'title_asc':
            return (title, source_index, item_index)
        if mode == 'title_desc':
            inv = ''.join(chr(0x10FFFF - ord(ch)) for ch in title[:80])
            return (inv, source_index, item_index)
        if mode == 'rating_desc':
            rating = _meta_rating_value(meta)
            return (0 if rating else 1, -float(rating or 0.0), source_index, item_index, title)
        # Default merged view: interleave by item rank first so multiple pinned
        # catalogues feel like one mixed folder instead of source A then source B.
        return (item_index, source_index, title)

    try:
        return sorted(rows or [], key=key)
    except Exception:
        return list(rows or [])


def _folder_filters_path():
    return os.path.join(_profile_path(), 'hub_folder_filters.json')


def _load_folder_filters():
    try:
        path = _folder_filters_path()
        if not xbmcvfs.exists(path):
            return {}
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh) or {}
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_folder_filters(data):
    try:
        profile = _profile_path()
        if not xbmcvfs.exists(profile):
            xbmcvfs.mkdirs(profile)
        with open(_folder_filters_path(), 'w', encoding='utf-8') as fh:
            json.dump(data or {}, fh, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _folder_filter_state(bucket):
    state = _load_folder_filters().get(str(bucket or ''), {})
    return dict(state) if isinstance(state, dict) else {}


def _set_folder_filter(bucket, filter_key, value):
    data = _load_folder_filters()
    bucket = str(bucket or '')
    current = dict(data.get(bucket, {}) if isinstance(data.get(bucket, {}), dict) else {})
    if value in (None, '', '__clear__'):
        current.pop(filter_key, None)
    else:
        current[filter_key] = value
    if current:
        data[bucket] = current
    else:
        data.pop(bucket, None)
    _save_folder_filters(data)
    return current


def _clear_folder_filters(bucket):
    data = _load_folder_filters()
    data.pop(str(bucket or ''), None)
    _save_folder_filters(data)


def _norm_filter_token(value):
    text = str(value or '').strip().lower()
    text = text.replace('_', ' ').replace('-', ' ')
    text = re.sub(r'\s+', ' ', text).strip()
    return text


def _folder_filter_key(name):
    raw = _norm_filter_token(name)
    compact = raw.replace(' ', '')
    if compact in ('sortby', 'orderby'):
        return 'sort'
    if compact in ('lastrelease', 'latestrelease', 'releasedate', 'released', 'release'):
        return 'lastrelease'
    if compact in ('lastadded', 'recentlyadded', 'added', 'dateadded'):
        return 'lastadded'
    if compact in ('contentrating', 'rating'):
        return 'contentrating'
    return compact or raw


def _folder_filter_label(filter_key, sample_name=''):
    labels = {
        'sort': 'Sort', 'order': 'Order', 'lastrelease': 'Last Release', 'lastadded': 'Last Added',
        'genre': 'Genre', 'year': 'Year', 'language': 'Language', 'country': 'Country',
        'network': 'Network', 'studio': 'Studio', 'collection': 'Collection',
        'availability': 'Availability', 'contentrating': 'Rating', 'unwatched': 'Unwatched',
        'category': 'Category', 'type': 'Type',
    }
    if filter_key in labels:
        return labels[filter_key]
    return _filter_label(sample_name or filter_key)


def _folder_filter_ignore(name):
    return _folder_filter_key(name) in ('skip', 'search', 'limit')


def _option_norm(value):
    text = _norm_filter_token(value)
    text = text.replace('_', ' ')
    return re.sub(r'\s+', ' ', text).strip()


def _folder_filter_groups(entries):
    groups = {}
    for provider, catalog, _b, pin in entries or []:
        provider_id = (provider or {}).get('id') or ''
        catalog_id = (catalog or {}).get('id') or (pin or {}).get('catalog_id') or ''
        media_type = (catalog or {}).get('type') or (pin or {}).get('media_type') or ''
        if not provider_id or not catalog_id:
            continue
        for extra in _available_filter_extras(catalog or {}):
            if not isinstance(extra, dict):
                continue
            name = extra.get('name') or ''
            if not name or _folder_filter_ignore(name):
                continue
            # Folder-level filters intentionally include folder-like manifest
            # extras too (Genre/Year/Language/etc.) so one button can control
            # everything the pinned sources expose.
            key = _folder_filter_key(name)
            group = groups.setdefault(key, {
                'key': key, 'label': _folder_filter_label(key, name), 'sample_name': name,
                'options': [], 'option_map': {}, 'targets': [],
            })
            opts = [str(x) for x in (extra.get('options') or []) if x not in (None, '')]
            for opt in opts:
                on = _option_norm(opt)
                if not on:
                    continue
                if on not in group['option_map']:
                    group['option_map'][on] = opt
                    group['options'].append(opt)
            group['targets'].append({
                'provider_id': provider_id, 'catalog_id': catalog_id, 'media_type': media_type,
                'name': name, 'options': opts,
            })
    order = {'sort': 0, 'order': 1, 'lastrelease': 2, 'lastadded': 3, 'genre': 4, 'year': 5, 'language': 6, 'country': 7}
    return sorted(groups.values(), key=lambda g: (order.get(g.get('key'), 50), str(g.get('label') or '').lower()))


def _folder_filter_group_map(entries):
    return {g.get('key'): g for g in _folder_filter_groups(entries)}


def _folder_filtered_extra_for_catalog(bucket, provider_id, catalog_id, catalog_def):
    state = _folder_filter_state(bucket)
    if not state:
        return {}
    extra_out = {}
    for extra in _available_filter_extras(catalog_def or {}):
        if not isinstance(extra, dict):
            continue
        name = extra.get('name') or ''
        if not name or _folder_filter_ignore(name):
            continue
        key = _folder_filter_key(name)
        value = state.get(key)
        if value in (None, ''):
            continue
        opts = [str(x) for x in (extra.get('options') or []) if x not in (None, '')]
        if opts:
            want = _option_norm(value)
            match = None
            for opt in opts:
                if _option_norm(opt) == want:
                    match = opt
                    break
            if match is None:
                # Source does not support this exact option; leave this source
                # unfiltered instead of hiding it or causing an error.
                continue
            extra_out[name] = match
        else:
            extra_out[name] = value
    return extra_out


def _hub_folder_filter_toolbar(bucket, entries):
    groups = _folder_filter_groups(entries)
    if not groups:
        return
    state = _folder_filter_state(bucket)
    active = []
    group_by_key = {g.get('key'): g for g in groups}
    for key, value in (state or {}).items():
        if value in (None, ''):
            continue
        group = group_by_key.get(key) or {'label': _folder_filter_label(key)}
        active.append('%s: %s' % (group.get('label') or _folder_filter_label(key), value))
    title = '[COLOR orange]≡ Folder filter[/COLOR]'
    if active:
        title += ' • [COLOR yellow]%s[/COLOR]' % ' | '.join(active)
    add_item(
        title,
        build_url(action='folder_filters_menu', bucket=bucket),
        is_folder=True,
        info={'title': 'Folder filter', 'plot': tr('One filter for every catalog pinned inside %s. If a add-on does not support the chosen filter, it is skipped for that add-on only.') % _hub_bucket_title(bucket)},
        art=root_art('catalogs'),
        properties={'SpecialSort': 'top'},
    )


def folder_filters_menu(bucket='movies'):
    bucket = bucket or 'movies'
    entries = _hub_pinned_catalog_entries(bucket)
    groups = _folder_filter_groups(entries)
    if not groups:
        notify(tr('No filters available in this folder'))
        return hub_section(bucket)
    state = _folder_filter_state(bucket)
    labels = []
    actions = []
    for group in groups:
        key = group.get('key') or ''
        if not key:
            continue
        current = state.get(key)
        suffix = ('  •  %s' % current) if current not in (None, '') else ''
        labels.append('%s%s' % (group.get('label') or _folder_filter_label(key), suffix))
        actions.append(('set', key))
    if state:
        labels.append('Clear all folder filters')
        actions.append(('clear', ''))
    idx = xbmcgui.Dialog().select(tr('Folder filter: %s') % tr(_hub_bucket_title(bucket)), [tr(x) for x in labels])
    if idx < 0:
        return hub_section(bucket)
    action, key = actions[idx]
    if action == 'clear':
        _clear_folder_filters(bucket)
        return hub_section(bucket)
    return folder_select_filter(bucket=bucket, filter_key=key)


def folder_select_filter(bucket='movies', filter_key=''):
    bucket = bucket or 'movies'
    filter_key = str(filter_key or '')
    entries = _hub_pinned_catalog_entries(bucket)
    group = _folder_filter_group_map(entries).get(filter_key)
    if not group:
        return hub_section(bucket)
    options = list(group.get('options') or [])
    title = group.get('label') or _folder_filter_label(filter_key)
    if options:
        labels = ['Clear filter'] + options
        idx = xbmcgui.Dialog().select(tr('Choose %s') % tr(title), [tr(x) for x in labels])
        if idx < 0:
            return hub_section(bucket)
        if idx == 0:
            _set_folder_filter(bucket, filter_key, '__clear__')
        else:
            _set_folder_filter(bucket, filter_key, labels[idx])
    else:
        default = _folder_filter_state(bucket).get(filter_key, '')
        kb = xbmc.Keyboard(default, tr('Type %s') % tr(title))
        kb.doModal()
        if not kb.isConfirmed():
            return hub_section(bucket)
        value = kb.getText().strip()
        _set_folder_filter(bucket, filter_key, value or '__clear__')
    return hub_section(bucket)

def catalog_pin(provider_id='', catalog_id='', media_type='', label='', bucket=''):
    if not provider_id or not catalog_id or not bucket:
        return end_dir()
    if str(bucket or '').strip().lower() == 'collection':
        notify(tr('Collection is for Favorites and lists only. Pick a home folder or sub folder.'))
        return end_dir()
    rows = _load_catalog_pins()
    key = _catalog_pin_key(provider_id, catalog_id, media_type)
    for row in rows:
        if _catalog_pin_key(row.get('provider_id'), row.get('catalog_id'), row.get('media_type')) == key and (row.get('bucket') or '') == bucket:
            notify(tr('Section already exists'))
            return end_dir()
    provider = store.get_provider(provider_id) or {}
    rows.append({
        'provider_id': provider_id,
        'provider_name': provider.get('name') or '',
        'catalog_id': catalog_id,
        'media_type': media_type,
        'label': label or catalog_id,
        'bucket': bucket,
        'created': int(time.time()),
    })
    _save_catalog_pins(rows)
    notify(tr('Section added'))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir()


def _catalog_pin_matches(row, provider_id='', catalog_id='', media_type='', bucket=''):
    if _catalog_pin_key(row.get('provider_id'), row.get('catalog_id'), row.get('media_type')) != _catalog_pin_key(provider_id, catalog_id, media_type):
        return False
    if bucket and (row.get('bucket') or '') != bucket:
        return False
    return True


def catalog_unpin(provider_id='', catalog_id='', media_type='', bucket=''):
    rows = _load_catalog_pins()
    new_rows = [r for r in rows if not _catalog_pin_matches(r, provider_id, catalog_id, media_type, bucket)]
    _save_catalog_pins(new_rows)
    # v3.9.45: also purge the index data for this catalog so its items
    # disappear from Hybrid renders immediately. If a bucket was given,
    # scope the deletion to that bucket; otherwise drop attribution for
    # this catalog across every bucket it appears in.
    try:
        from . import index_render
        index_render.get_db().purge_catalog(provider_id, catalog_id, bucket=bucket or None)
    except Exception as _exc:
        xbmc.log('[NuvioHub] purge_catalog failed: %s' % _exc, xbmc.LOGWARNING)
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir()



def _hub_bucket_pins(bucket):
    return [x for x in _load_catalog_pins() if (x.get('bucket') or '') == bucket]


def _hub_pinned_catalog_entries(bucket):
    rows = []
    for pin in _hub_bucket_pins(bucket):
        provider = store.get_provider(pin.get('provider_id') or '')
        if not provider:
            continue
        catalog_def = _catalog_definition(provider, pin.get('catalog_id') or '', pin.get('media_type') or '') or {}
        if not catalog_def:
            continue
        rows.append((provider, catalog_def, _hub_catalog_bucket(provider, catalog_def), pin))
    return rows


def _hub_render_media_rows(ordered_rows, bucket='', page_num=0, has_more=False):
    if not ordered_rows:
        return False
    # v3.9.30: publish the current render bucket so _resolve_meta_art()
    # can consult the per-bucket art priority map (configured via
    # meta_source.set_bucket_art_priority). Cleared at the end of this
    # function so other code paths aren't confused by stale context.
    try:
        xbmcgui.Window(WINDOW_ID).setProperty('nuviohub.render_bucket', str(bucket or ''))
    except Exception:
        pass
    try:
        favorite_keys = favorites_store.favorite_keys()
    except Exception:
        favorite_keys = set()
    first_fanart = ''
    # v3.9.31: lazy art enrichment for off-screen items. Most skins show
    # ~12 listitems at once before scroll. Items beyond that don't need
    # the full TMDB/Fanart cross-enrichment immediately — their poster
    # from the catalog response is "good enough" and the user will scroll
    # to them with the same lazy art. Threshold mirrors the typical
    # "above-the-fold" count for grid skins.
    _LAZY_ART_THRESHOLD = 12
    for idx, (provider, catalog, media_type, meta_id, meta) in enumerate(ordered_rows):
        item_label = (meta or {}).get('name') or meta_id
        try:
            _meta_mem_put(media_type, meta_id, meta, source_provider_id=(provider or {}).get('id') or '')
        except Exception:
            pass
        fallback = _item_fallback_art(provider, media_type, catalog, item_label)
        art = _resolve_meta_art(provider, media_type, meta,
                                  fallback_art=fallback,
                                  lazy=(idx >= _LAZY_ART_THRESHOLD))
        if not first_fanart and art.get('fanart'):
            first_fanart = art.get('fanart')
        ids = extract_ids(meta)
        folder_source_mode = 'only' if (_folder_play_mode(bucket) == 'same_source_auto' and not _is_series_media(media_type)) else ''
        path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=meta_id, title=item_label, tmdb_id=ids.get('tmdb_id') or '', imdb_id=ids.get('imdb_id') or '', tvdb_id=ids.get('tvdb_id') or '', source_provider_id=(provider or {}).get('id') or '', source_mode=folder_source_mode, force_nuviohub=bool(folder_source_mode), ui_seed=art)
        ctx_menu = _append_folder_tools_context(_hub_item_context(provider, media_type, meta_id, item_label), bucket)
        already_fav = (str(media_type or ''), str(meta_id or '')) in favorite_keys
        if already_fav:
            ctx_menu.append(('Remove from favorites', 'RunPlugin(%s)' % build_url(action='fav_remove', media_type=media_type, canonical_id=meta_id)))
        else:
            ctx_menu.append(('Add to favorites', 'RunPlugin(%s)' % build_url(action='fav_add', media_type=media_type, canonical_id=meta_id, title=item_label, poster=art.get('poster') or '', background=art.get('fanart') or '', clearlogo=art.get('clearlogo') or '', year=str((_meta_info(meta).get('year') or 0)))))
        add_item(item_label, path, is_folder=path_is_folder, info=_meta_info(meta), art=art, ids=ids, context_menu=ctx_menu, is_favorite=already_fav)
    if first_fanart:
        try:
            xbmcgui.Window(WINDOW_ID).setProperty('fanart', first_fanart)
        except Exception:
            pass
    if has_more:
        if not globals().get('_pagination_hidden', lambda: False)():
            add_item(tr('More'), build_url(action='hub_section', bucket=bucket, page=str(page_num + 1)), art=root_art('catalogs'), info={'title': tr('More')})
    return True


def _hub_section_direct_content(bucket='movies', page='0'):
    bucket = bucket or 'movies'
    title = _hub_bucket_title(bucket)
    entries = _hub_pinned_catalog_entries(bucket)
    subfolders = _home_subfolders(bucket)
    if not entries and not subfolders:
        add_item(tr("[COLOR yellow]Pick this folder's content from Sources[/COLOR]"), build_url(action='providers'), art=root_art('providers'), info={'title': title, 'plot': tr('Open Add-ons, long-press any catalog, then choose "Add into %s". Content will appear here directly without folders.') % title}, context_menu=_folder_tools_context(bucket, entries))
        add_item(tr('All matching add-on catalogs'), build_url(action='hub_section', bucket=bucket, raw='1'), art=root_art('catalogs'), info={'title': tr('All add-on catalogs'), 'plot': tr('Pick the catalogs you want to pin inside this folder from here')})
        if not _is_subfolder_bucket(bucket):
            add_item(tr('+ Add sub folder'), build_url(action='home_subfolder_add', parent=bucket), art=root_art('add'), info={'title': tr('Add sub folder')})
        add_item(tr('+ Add new home folder'), build_url(action='home_folder_add'), art=root_art('add'), info={'title': tr('Add new home folder')})
        return end_dir(content='files', cache=False)
    _hub_filter_toolbar_for_pins(bucket, entries)
    if entries and _folder_view_mode(bucket) == 'sources':
        if subfolders:
            pins = _load_catalog_pins()
            for sub in subfolders:
                sb = sub.get('bucket') or ''
                st = sub.get('title') or _hub_bucket_title(sb)
                cnt = len([p for p in pins if (p.get('bucket') or '') == sb])
                ctx = _append_folder_tools_context([
                    ('Delete sub folder', 'RunPlugin(%s)' % build_url(action='home_subfolder_remove', bucket=sb)),
                    ('Show the add-ons in this sub folder', 'Container.Update(%s)' % build_url(action='hub_section', bucket=sb, raw='1')),
                ], sb)
                add_item(st if not cnt else '%s (%d)' % (st, cnt), build_url(action='hub_section', bucket=sb), art=_hub_icon_for_bucket(sb), info={'title': st, 'plot': tr('Sub folder inside %s') % title}, context_menu=ctx)
        _hub_render_pinned(bucket)
        return end_dir(content='files', cache=False)
    if subfolders:
        pins = _load_catalog_pins()
        for sub in subfolders:
            sb = sub.get('bucket') or ''
            st = sub.get('title') or _hub_bucket_title(sb)
            cnt = len([p for p in pins if (p.get('bucket') or '') == sb])
            ctx = _append_folder_tools_context([
                ('Delete sub folder', 'RunPlugin(%s)' % build_url(action='home_subfolder_remove', bucket=sb)),
                ('Show the add-ons in this sub folder', 'Container.Update(%s)' % build_url(action='hub_section', bucket=sb, raw='1')),
            ], sb)
            add_item(st if not cnt else '%s (%d)' % (st, cnt), build_url(action='hub_section', bucket=sb), art=_hub_icon_for_bucket(sb), info={'title': st, 'plot': tr('Sub folder inside %s') % title}, context_menu=ctx)
        if not entries:
            add_item(tr('All matching add-on catalogs'), build_url(action='hub_section', bucket=bucket, raw='1'), art=root_art('catalogs'), info={'title': tr('All add-on catalogs')})
            return end_dir(content='files', cache=False)
    try:
        page_num = max(0, int(page or 0))
    except Exception:
        page_num = 0
    page_size = _listing_page_size()
    fetch_limit = max(page_size, min(80, page_size * (page_num + 1)))

    # ─── v3.9.27: Fast Index Mode short-circuit ─────────────────────
    # If the user enabled Fast Index Mode AND the bucket has data in the
    # local SQLite index, render from there with a single SQL query and
    # skip the live HTTP aggregator entirely. Folder open drops from
    # 1-4s to ~5-50ms. Falls back to the live aggregator when:
    #   * mode is 'live' (the default — opt-in for safety)
    #   * the index has no data for this bucket yet (first sync pending)
    #   * any exception during index query (DB locked, schema mismatch)
    # so the user never gets a worse experience than before.
    if _index_mode_active():
        try:
            indexed_metas = _try_index_render(bucket, page_num, page_size, fetch_limit, entries)
            if indexed_metas is not None:
                ordered_rows = indexed_metas
                more_possible = len(ordered_rows) >= page_size
                _hub_render_media_rows(ordered_rows[:page_size],
                                         bucket=bucket, page_num=page_num,
                                         has_more=more_possible)
                return end_dir(content=_hub_directory_content(bucket), cache=True)
        except Exception as exc:
            xbmc.log('[NuvioHub] index render failed, falling back to live: %s' % exc,
                     xbmc.LOGWARNING)

    candidates = []
    more_possible = False
    entry_index = {id(job): idx for idx, job in enumerate(entries)}

    def _run_catalog(job):
        provider, catalog, _b, _pin = job
        provider_id = (provider or {}).get('id') or ''
        catalog_id = (catalog or {}).get('id') or ''
        media_type = catalog.get('type') or _hub_bucket_media_type(bucket) or 'movie'
        extra = dict(_folder_filtered_extra_for_catalog(bucket, provider_id, catalog_id, catalog) or {})
        # For merged folders, fetch a small window from every pinned catalog, then
        # sort globally. Do not use per-source skip here; otherwise page 1 from
        # source A is sorted before page 1 from source B and filters feel grouped.
        extra['limit'] = str(fetch_limit)
        return fetch_catalog(provider, media_type, catalog_id, extra=extra, timeout_override=fast_timeout('catalog'))

    batch_size = max(1, min(parallel_workers(), 4, len(entries)))
    # v3.9.34: budget tightened from 5.0s → 3.5s. Reports of folders
    # "hanging" on slow providers turned out to be the 5s wait pegging
    # the UI with no progress. 3.5s + Hybrid index mode (now default)
    # means most opens are instant; live fallback still gets a fair
    # window but doesn't drag too long. Per-provider failures still
    # surface via the toast and the empty-state diagnostic shortcut.
    _FOLDER_OPEN_BUDGET = 3.5
    _folder_deadline = time.time() + _FOLDER_OPEN_BUDGET
    _completed_count = 0
    _failed_providers = []   # for toast + empty-state diagnostics
    _budget_exceeded  = False
    for job, result in iter_parallel(_run_catalog, entries, workers=batch_size,
                                       timeout=_FOLDER_OPEN_BUDGET):
        if time.time() > _folder_deadline:
            _budget_exceeded = True
            xbmc.log('[NuvioHub] hub_section folder budget exceeded — rendering partial set',
                     xbmc.LOGINFO)
            break
        provider, catalog, _b, _pin = job
        source_index = entry_index.get(id(job), len(candidates))
        media_type = catalog.get('type') or _hub_bucket_media_type(bucket) or 'movie'
        _completed_count += 1
        if isinstance(result, Exception):
            # v3.9.17: track silent failures so we can surface them to the user.
            # Previously these were swallowed and the user just saw a smaller
            # listing with no idea why.
            _failed_providers.append((provider, catalog, str(result.__class__.__name__)))
            continue
        metas = (result or {}).get('metas') or []
        if len(metas) >= fetch_limit:
            more_possible = True
        for item_index, meta in enumerate(metas):
            meta_id = str((meta or {}).get('id') or '')
            if not meta_id:
                continue
            candidates.append((provider, catalog, media_type, meta_id, meta, source_index, item_index))

    # Compute "did not complete" providers — those whose entry never came back
    # from iter_parallel because the budget cut us off. Useful for the empty
    # state + toast.
    _incomplete = max(0, len(entries) - _completed_count)

    # v3.9.17: brief toast for failed sources. Throttle to once per provider
    # per session via Window properties so we don't spam the user across
    # back-and-forth navigation.
    try:
        if _failed_providers:
            _win = xbmcgui.Window(WINDOW_ID)
            for provider, _catalog, exc_name in _failed_providers[:1]:  # max 1 toast per render
                pname = (provider or {}).get('name') or 'source'
                seen_key = 'nuviohub.fail_warn.%s' % ((provider or {}).get('id') or pname)
                try:
                    if _win.getProperty(seen_key) != '1':
                        _win.setProperty(seen_key, '1')
                        xbmcgui.Dialog().notification(
                            'Nuvio Hub',
                            tr('Could not reach %s — skipped') % pname,
                            xbmcgui.NOTIFICATION_WARNING, 2200, sound=False
                        )
                except Exception:
                    pass
    except Exception:
        pass

    # Dedupe after collecting all catalogues so source priority wins regardless
    # of which network request returned first. Then sort the full merged set.
    if _folder_dedupe_enabled(bucket):
        # --- nuviohub-405-patch --- alias-aware merge, see _dedupe_rows
        candidates = _dedupe_rows(
            candidates,
            rank_of=lambda row: (row[5], row[6]),
            keys_of=lambda row: _meta_dedupe_alias_keys(row[2], row[3], row[4]),
        )

    sorted_rows = _folder_global_sort_rows(candidates, bucket)
    start = page_num * page_size
    end = start + page_size
    page_rows = sorted_rows[start:end]
    if len(sorted_rows) > end:
        more_possible = True
    ordered_rows = [(provider, catalog, media_type, meta_id, meta) for provider, catalog, media_type, meta_id, meta, _source_index, _item_index in page_rows]

    if not ordered_rows:
        # v3.9.17: smarter empty state — explain WHY the folder is empty so
        # the user can act on it (slow source vs no content). Always offer a
        # quick retry and a path into source diagnostics.
        if _budget_exceeded or _incomplete or _failed_providers:
            empty_label = tr('%d of %d add-ons timed out — press to retry') % (
                max(_incomplete, len(_failed_providers)), len(entries)
            )
            empty_plot  = tr('Some add-ons did not respond within %d seconds. Try again, or open "Add-on diagnostics" to see which one is slow.') % int(_FOLDER_OPEN_BUDGET)
        else:
            empty_label = '[COLOR yellow]%s[/COLOR]' % tr('No content available from the pinned add-ons')
            empty_plot  = tr('The add-on may be empty or may not support this page. Try pinning another catalog from Add-ons.')
        # Retry/refresh row
        add_item('[COLOR cyan]↻ %s[/COLOR]' % empty_label,
                 build_url(action='hub_section', bucket=bucket, page=str(page_num)),
                 art=root_art('catalogs'),
                 info={'title': title, 'plot': empty_plot},
                 context_menu=_folder_tools_context(bucket, entries))
        # Diagnostic shortcut — surfaced only when something actually failed.
        if _budget_exceeded or _failed_providers:
            add_item('[COLOR cyan]🩺 %s[/COLOR]' % tr('Add-on diagnostics'),
                     build_url(action='diagnose_sources'),
                     art=root_art('catalogs'),
                     info={'title': tr('Add-on diagnostics'),
                           'plot': tr('Test the response time of every pinned add-on to find the slow one')})
        # Original "browse all catalogs" fallback
        add_item(tr('All matching add-on catalogs'),
                 build_url(action='hub_section', bucket=bucket, raw='1'),
                 art=root_art('catalogs'),
                 info={'title': 'All add-on catalogs'})
        if not _is_subfolder_bucket(bucket):
            add_item(tr('+ Add sub folder'), build_url(action='home_subfolder_add', parent=bucket), art=root_art('add'), info={'title': tr('Add sub folder')})
        return end_dir(content='files', cache=False)

    _hub_render_media_rows(ordered_rows[:page_size], bucket=bucket, page_num=page_num, has_more=more_possible)
    return end_dir(content=_hub_directory_content(bucket), cache=True)


def hub_section(bucket='movies', raw='', page='0'):
    bucket = bucket or 'movies'
    # v3.9.48: set the active-bucket context so meta_source.get_meta_source_for
    # consults the per-bucket override before falling back to provider/global.
    _set_active_bucket(bucket)
    if raw == '1':
        source_bucket = _catalog_source_bucket_for(bucket)
        rows = _hub_catalog_entries(bucket=source_bucket)
        if not rows and (str(bucket or '').startswith('custom:') or _is_subfolder_bucket(bucket)):
            rows = _hub_catalog_entries(bucket=None)
        if not rows:
            add_item(tr('[COLOR yellow]No catalogs in this section[/COLOR]'), build_url(action='providers'), art=root_art('providers'), info={'title': 'Sources'})
            return end_dir(content='files', cache=False)
        for provider, catalog, _b in rows:
            media_type = catalog.get('type') or _hub_bucket_media_type(bucket) or ''
            cname = catalog.get('name') or catalog.get('id') or 'Catalog'
            pname = provider.get('name') or 'Source'
            url = build_url(action='catalog_all', provider_id=provider.get('id'), media_type=media_type, catalog_id=catalog.get('id'), label=cname)
            ctx = _hub_catalog_context(provider, catalog, bucket) + _catalog_filter_context(
                provider_id=provider.get('id') or '', media_type=media_type, catalog_id=catalog.get('id') or '', catalog_def=catalog
            )
            add_item('%s  •  %s' % (cname, pname), url, art=catalog_art(cname, media_type, provider.get('manifest') or {}, catalog), info={'title': cname, 'plot': pname}, context_menu=ctx)
        return end_dir(content='files', cache=True)

    return _hub_section_direct_content(bucket=bucket, page=page)

def catalog_pin_move(provider_id='', catalog_id='', media_type='', bucket='', direction='up'):
    rows = _load_catalog_pins()
    idx = None
    for i, row in enumerate(rows):
        if _catalog_pin_matches(row, provider_id, catalog_id, media_type, bucket):
            idx = i
            break
    if idx is None:
        return end_dir()
    bucket = bucket or rows[idx].get('bucket') or ''
    swap_idx = None
    if direction == 'up':
        for j in range(idx - 1, -1, -1):
            if (rows[j].get('bucket') or '') == bucket:
                swap_idx = j
                break
    else:
        for j in range(idx + 1, len(rows)):
            if (rows[j].get('bucket') or '') == bucket:
                swap_idx = j
                break
    if swap_idx is not None:
        rows[swap_idx], rows[idx] = rows[idx], rows[swap_idx]
        _save_catalog_pins(rows)
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir()

def hub_search_menu(query=''):
    _set_render_section('search')
    """Search TMDb, installed Stremio addons and media servers together."""
    _clear_source_transient_props(clear_global=True)

    win = xbmcgui.Window(WINDOW_ID)
    last_query = win.getProperty('nuviohub.last_search.unified') or ''
    query = str(query or '').strip()
    if not query:
        keyboard = xbmc.Keyboard(last_query, tr('Search TMDb'))
        keyboard.doModal()
        if not keyboard.isConfirmed():
            return end_dir(content='files', cache=False)
        query = keyboard.getText().strip()
    if not query:
        return end_dir(content='files', cache=False)
    win.setProperty('nuviohub.last_search.unified', query)
    try:
        from . import search_history as _sh
        _sh.add(query, media_type='all')
    except Exception:
        pass

    # v4.9.0: TMDb used to short-circuit this route. As soon as it returned
    # one row IPTV, Plex and Emby were never searched at all. TMDb is now
    # one bounded parallel job in the same coordinator as every other source.
    rows = store.list_providers()
    return _hub_search_unified_render(query, rows, include_tmdb=True)



def _plex_servers_budgeted(budget_seconds=6.0, down_memo_seconds=90.0):
    """plex_client.servers() under a hard wall-clock budget, with a down-memo.

    v3.9.241 (kodi.log 2026-07-14): with the Plex box unreachable,
    servers() + servers(force=True) burned ~60s EACH against dead endpoints —
    121s ON THE DISPATCH THREAD before the source picker could appear. The
    user kept pressing resume while waiting, and every press paid the same
    121s and then opened ITS OWN picker: the stacked-dialogs symptom.

    The fetch now runs in a worker joined for `budget_seconds`; on timeout or
    error the server is memoised as down for `down_memo_seconds`, so the NEXT
    press skips Plex instantly instead of re-paying. The worker communicates
    through a private dict — it never touches shared lists after the join, so
    a late finisher cannot race the picker build. Success clears the memo.
    """
    try:
        down_until = float(xbmcgui.Window(10000).getProperty('nuviohub.plex.down_until') or 0.0)
    except Exception:
        down_until = 0.0
    now = time.time()
    if now < down_until:
        xbmc.log('[NuvioHub] Plex Native targets skipped: marked down for %.0fs more'
                 % (down_until - now), xbmc.LOGINFO)
        return []

    out = {}

    def _worker():
        try:
            srv = plex_client.servers()
            if not srv:
                srv = plex_client.servers(force=True)
            out['servers'] = srv or []
        except Exception as exc:
            out['exc'] = exc

    try:
        t = threading.Thread(
            target=_worker, name='NuvioHubPlexServers', daemon=True)
        t.start()
    except RuntimeError as exc:
        xbmc.log('[NuvioHub] Plex discovery worker unavailable: %s' % exc,
                 xbmc.LOGWARNING)
        try:
            xbmcgui.Window(10000).setProperty(
                'nuviohub.plex.down_until',
                str(time.time() + down_memo_seconds),
            )
        except Exception:
            pass
        return []
    t.join(budget_seconds)
    if t.is_alive() or out.get('exc'):
        reason = out.get('exc') or ('no reply within %.0fs' % budget_seconds)
        xbmc.log('[NuvioHub] Plex Native target discovery failed: %s' % reason,
                 xbmc.LOGWARNING)
        try:
            xbmcgui.Window(10000).setProperty(
                'nuviohub.plex.down_until', str(time.time() + down_memo_seconds))
        except Exception:
            pass
        return []
    try:
        xbmcgui.Window(10000).setProperty('nuviohub.plex.down_until', '')
    except Exception:
        pass
    return out.get('servers') or []


def _emit_server_search_rows(query, ui_rows=None):
    # One log line that answers "why are there no Plex results?" outright.
    try:
        _p = plex_client.is_signed_in()
        _e = emby_client.is_signed_in()
        xbmc.log('[NuvioHub] server search: plex_signed_in=%s emby_signed_in=%s query=%r'
                 % (_p, _e, query), xbmc.LOGINFO)
        if _p:
            xbmc.log('[NuvioHub] server search: plex servers=%d'
                     % len(plex_client.servers() or []), xbmc.LOGINFO)
    except Exception as _exc:
        xbmc.log('[NuvioHub] server search: gate failed: %s' % _exc, xbmc.LOGWARNING)
    """Search every connected Plex/Emby server and render the hits.

    Reuses the provider machinery built for the unified search, so the rows are
    identical: brand line, size, poster, clear logo, and the correct play route.
    """
    providers = _server_providers()
    if not providers or not str(query or '').strip():
        return 0
    jobs = [(provider, media_type)
            for provider in providers for media_type in ('movie', 'series')]

    def _run(job):
        provider, media_type = job
        try:
            return _server_catalog(provider, media_type, extra={'search': query})
        except Exception as exc:
            return exc

    rows = []
    for job, result in iter_parallel(_run, jobs):
        if isinstance(result, Exception) or not result:
            continue
        rows.extend((result or {}).get('metas') or [])
    if not rows:
        return 0

    add_item(tr('[B][COLOR gold]⭐ From your servers[/COLOR][/B]   [COLOR lightgrey]%d[/COLOR]') % len(rows),
             build_url(action='hub_search_menu'), is_folder=False,
             art=root_art('plex'), info={'title': 'From your servers'})
    for meta in rows:
        path, is_folder = _server_row_path(meta)
        art = native_meta_art(meta, media_type=(meta.get('type') or 'movie'),
                              fallback_art=catalog_art('search', meta.get('type') or 'movie'))
        info = {'title': meta.get('name') or '', 'plot': meta.get('description') or '',
                'mediatype': 'tvshow' if meta.get('type') == 'series' else 'movie'}
        if meta.get('releaseInfo'):
            try:
                info['year'] = int(str(meta['releaseInfo'])[:4])
            except (TypeError, ValueError):
                pass
        add_item(meta.get('name') or '?', path, is_folder=is_folder,
                 info=info, art=art, label2=meta.get('_label2') or '',
                 properties=None if is_folder else {'IsPlayable': 'true'})
        if isinstance(ui_rows, list):
            media_type = meta.get('type') or 'movie'
            ui_rows.append({
                'title': meta.get('name') or '?',
                'year': info.get('year') or '',
                'media_type': media_type,
                'plot': info.get('plot') or '',
                'rating': meta.get('imdbRating') or meta.get('rating') or '',
                'genre': meta.get('genres') or meta.get('genre') or [],
                'runtime': meta.get('runtime') or '',
                'poster': art.get('poster') or art.get('thumb') or '',
                'fanart': art.get('fanart') or art.get('landscape') or '',
                'landscape': art.get('landscape') or art.get('fanart') or '',
                'clearlogo': art.get('clearlogo') or art.get('logo') or '',
                'path': path,
                'is_folder': '1' if is_folder else '',
                'source_label': meta.get('_label2') or meta.get('_server_name') or '',
                'is_anime': False,
            })
    xbmc.log('[NuvioHub] server search rows: %d' % len(rows), xbmc.LOGINFO)
    return len(rows)


def _render_tmdb_search_results(query, rows):
    """Compatibility shim for callers from pre-4.9 reused interpreters."""
    return _hub_search_unified_render(query, store.list_providers(), include_tmdb=True)


# ─────────────────────────────────────────────────────────────────────────────
# v3.9.196 — Plex / Emby as VIRTUAL STREMIO PROVIDERS
#
# The servers used to travel through the search on their own private rails
# ('__plex__' / '__emby__' job markers, a second results dict, a second dedup
# set, a second renderer). Anything the main pipeline gained — the per-job
# cache, stable ordering, failure reporting, the required-extra rule — had to
# be re-implemented for them, and in practice simply was not.
#
# They are now ordinary providers carrying a synthetic manifest, so every job
# in the search is the same shape and the ENTIRE pipeline applies to them for
# free. The only server-specific code left is one routing hook in the row
# builder (a Plex row must open plex_play, not item_open).
# ─────────────────────────────────────────────────────────────────────────────
SERVER_BACKENDS = ('plex', 'emby')


def _server_provider(backend, server):
    name = '%s • %s' % ('Plex' if backend == 'plex' else 'Emby',
                        server.get('name') or 'Server')
    catalogs = [{
        'id': '%s_search' % backend,
        'type': media_type,
        'name': name,
        'extra': [{'name': 'search', 'isRequired': True}],
    } for media_type in ('movie', 'series')]
    return {
        'id': '%s:%s' % (backend, server.get('id') or ''),
        'name': name,
        'backend': backend,
        'server': server,
        'manifest': {
            'id': 'nuviohub.%s.%s' % (backend, server.get('id') or ''),
            'name': name,
            'types': ['movie', 'series'],
            'catalogs': catalogs,
        },
    }


def _server_providers():
    """Every connected media server, shaped like an installed Stremio addon."""
    providers = []
    try:
        if plex_client.is_signed_in():
            for server in plex_client.servers():
                providers.append(_server_provider('plex', server))
    except Exception:
        pass
    try:
        if emby_client.is_signed_in():
            for server in emby_client.servers():
                providers.append(_server_provider('emby', server))
    except Exception:
        pass
    return providers


def _server_meta(item, provider):
    """One server item in Stremio meta shape, so the generic row builder works."""
    backend = provider.get('backend')
    server = provider.get('server') or {}
    kind = item.get('media_type') or 'movie'
    if backend == 'plex':
        poster = plex_client.artwork_url(item, item.get('thumb') or '')
        fanart = plex_client.artwork_url(item, item.get('art') or '')
        logo = plex_client.logo_url(item)
    else:
        poster = emby_client.artwork_url(server, item.get('thumb') or '')
        fanart = emby_client.artwork_url(server, item.get('art') or '', kind='Backdrop')
        logo = emby_client.logo_url(server, item.get('rating_key') or '')
    ids = item.get('ids') or {}
    facts = item.get('info_line') or ''
    plot = item.get('summary') or ''
    if facts:
        plot = ('%s\n\n%s' % (facts, plot)) if plot else facts
    brand = 'PLEX' if backend == 'plex' else 'EMBY'
    colour = PLEX_COLOR if backend == 'plex' else EMBY_COLOR
    label2 = '[COLOR %s]%s[/COLOR] • %s' % (colour, brand, server.get('name') or '')
    if facts:
        label2 = '%s • %s' % (facts, label2)
    meta = {
        # Namespaced so a server copy never collides with — or is deduped
        # away by — an addon result for the same title.
        'id': '%s:%s:%s' % (backend, server.get('id') or '', item.get('rating_key') or ''),
        'type': 'movie' if kind == 'movie' else 'series',
        'name': item.get('title') or 'Untitled',
        'poster': poster,
        'background': fanart,
        'logo': logo,
        'clearlogo': logo,
        'description': plot,
        'releaseInfo': str(item.get('year') or ''),
        'imdb_id': ids.get('imdb_id') or '',
        'moviedb_id': ids.get('tmdb_id') or '',
        # server-only fields, consumed by the routing hook in the row builder
        '_backend': backend,
        '_server_item': item,
        '_provider_name': provider.get('name') or '',
        '_label2': label2,
        '_size_label': item.get('size_label') or '',
    }
    if item.get('rating'):
        meta['imdbRating'] = str(item.get('rating'))
    if item.get('genres'):
        meta['genres'] = list(item.get('genres') or [])
    return meta


def _server_catalog(provider, media_type, extra=None):
    """The servers' `fetch_catalog`: same contract, same {'metas': [...]}."""
    query = str((extra or {}).get('search') or '').strip()
    if not query:
        return {'metas': []}
    backend = provider.get('backend')
    server = provider.get('server') or {}
    client = plex_client if backend == 'plex' else emby_client
    rows = client.search_server(server, query, media_type=media_type, limit=40)
    metas = []
    for item in rows or []:
        kind = item.get('media_type') or 'movie'
        want_movie = (media_type == 'movie')
        if want_movie != (kind == 'movie'):
            continue          # the movie job renders movies, the series job shows/episodes
        if not item.get('rating_key'):
            continue
        metas.append(_server_meta(item, provider))
    return {'metas': metas}


def _server_row_path(meta):
    """Route a server row to its own action instead of the generic item page."""
    item = meta.get('_server_item') or {}
    backend = meta.get('_backend')
    kind = item.get('media_type') or 'movie'
    if backend == 'plex':
        if kind in ('show', 'season'):
            return build_url(action='plex_children', server_id=item.get('server_id') or '',
                             key=item.get('key') or '', title=item.get('title') or ''), True
        return build_url(action='plex_play', server_id=item.get('server_id') or '',
                         rating_key=item.get('rating_key') or ''), False
    if kind in ('show', 'season'):
        return build_url(action='emby_children', key=item.get('rating_key') or '',
                         title=item.get('title') or ''), True
    return build_url(action='emby_play', item_id=item.get('rating_key') or ''), False


# v3.9.197 — canonical cross-namespace identity, after AIOMetadata's
# "advanced ID mapping" (IMDb / TMDB / TVDB / Kitsu / MAL / AniList / AniDB /
# TVmaze). Addons publish the SAME title under different ID systems, so
# deduping on the raw `id` alone let one movie appear once per namespace, and
# left anything that was not IMDb-keyed unmatched against Plex/Emby.
_ID_NAMESPACES = ('imdb', 'tmdb', 'tvdb', 'kitsu', 'mal', 'anilist', 'anidb', 'tvmaze')

_ID_FIELD_MAP = {
    'imdb': 'imdb', 'imdbid': 'imdb', 'imdb_id': 'imdb',
    'tmdb': 'tmdb', 'tmdbid': 'tmdb', 'tmdb_id': 'tmdb',
    'moviedb_id': 'tmdb', 'themoviedb_id': 'tmdb',
    'tvdb': 'tvdb', 'tvdbid': 'tvdb', 'tvdb_id': 'tvdb', 'thetvdb_id': 'tvdb',
    'kitsu': 'kitsu', 'kitsuid': 'kitsu', 'kitsu_id': 'kitsu',
    'mal': 'mal', 'malid': 'mal', 'mal_id': 'mal', 'myanimelist_id': 'mal',
    'anilist': 'anilist', 'anilistid': 'anilist', 'anilist_id': 'anilist',
    'anidb': 'anidb', 'anidbid': 'anidb', 'anidb_id': 'anidb',
    'tvmaze': 'tvmaze', 'tvmazeid': 'tvmaze', 'tvmaze_id': 'tvmaze',
}


def _meta_identity(meta):
    """Every ID this meta is known by, canonicalised as `namespace:value`."""
    out = set()
    meta = meta or {}

    def _add(namespace, value):
        value = str(value or '').strip().lower()
        if not value or namespace not in _ID_NAMESPACES:
            return
        if namespace == 'imdb':
            value = value.split(':')[0]
            if not value.startswith('tt'):
                return
        else:
            value = value.split(':')[0]
            if not value:
                return
        out.add('%s:%s' % (namespace, value))

    raw = str(meta.get('id') or '').strip()
    low = raw.lower()
    if low.startswith('tt'):
        _add('imdb', low)
    else:
        for sep in (':', '-'):
            if sep in low:
                head, tail = low.split(sep, 1)
                if head.strip() in _ID_NAMESPACES:
                    _add(head.strip(), tail)
                    break

    for key, value in list(meta.items()):
        namespace = _ID_FIELD_MAP.get(str(key).strip().lower())
        if namespace and not isinstance(value, (dict, list)):
            _add(namespace, value)

    for holder in (meta.get('behaviorHints') or {}, meta.get('externalIds') or {},
                   meta.get('external_ids') or {}, meta.get('ids') or {}):
        if isinstance(holder, dict):
            for key, value in holder.items():
                namespace = _ID_FIELD_MAP.get(str(key).strip().lower())
                if namespace and not isinstance(value, (dict, list)):
                    _add(namespace, value)

    if not out and raw:
        out.add('raw:%s' % low)      # last resort: the addon's own opaque id
    return out


def _catalog_supports_search(catalog):
    """True when this catalog can be searched by query alone.

    v3.9.195 — two rules, the second borrowed from Nuvio's SearchRepository:

      1. the catalog declares `search`, in ANY of the three spellings found in
         the wild: extra:[{"name":"search"}] / extraSupported:["search"] /
         extra:["search"];
      2. NO OTHER extra is required. A catalog that mandates e.g. a genre
         cannot answer a bare query — firing it burns a slot, usually times
         out, and then surfaces as a failed source.
    """
    catalog = catalog or {}
    has_search = False
    other_required = False

    required_names = set()
    for name in (catalog.get('extraRequired') or []):
        if isinstance(name, dict):
            name = name.get('name')
        if name:
            required_names.add(str(name).strip().lower())

    for field in ('extra', 'extraSupported'):
        for entry in (catalog.get(field) or []):
            if isinstance(entry, dict):
                name = str(entry.get('name') or '').strip().lower()
                required = bool(entry.get('isRequired') or entry.get('required'))
            else:
                name = str(entry or '').strip().lower()
                required = False
            if not name:
                continue
            if name == 'search':
                has_search = True
            elif required or name in required_names:
                other_required = True

    if required_names - {'search'}:
        other_required = True
    return bool(has_search and not other_required)

def _setting(key, default=''):
    """Read one addon setting as text.

    v4.8.6: this helper was USED in two places and never defined —
    `sync_options_action` (added in 4.8.3) and the cinematic-search hand-off
    in the TMDb search renderer. The first crashed the whole dispatcher with
    "name '_setting' is not defined" the moment the Sync mode and timing
    entry was opened, which is why that screen would not open at all; the
    second sat inside a broad `except`, so the cinematic search window had
    been silently failing to open ever since.
    """
    try:
        return ADDON.getSetting(key) or default
    except Exception:
        return default


