# v3.9.45: configuration backup and restore. The complete user-curated
# state of NuvioHub serialised to a single JSON document so it can be
# migrated to a new install or new device without losing setup work.
def _config_snapshot():
    """Build the full configuration snapshot for export."""
    snapshot = {
        'nuviohub_export_version': 1,
        'created_unix': int(time.time()),
        'plugin_version': ADDON.getAddonInfo('version'),
        'providers': [],
        'catalog_pins': [],
        'home_buckets': [],
        'bucket_art_map': {},
        'settings': {},
    }
    try:
        snapshot['providers'] = store.list_providers() or []
    except Exception:
        pass
    try:
        snapshot['catalog_pins'] = _load_catalog_pins() or []
    except Exception:
        pass
    try:
        snapshot['home_buckets'] = _home_bucket_defs(include_collection=False) or []
    except Exception:
        pass
    try:
        raw_map = (ADDON.getSetting('bucket_art_map') or '{}').strip()
        snapshot['bucket_art_map'] = json.loads(raw_map) if raw_map else {}
    except Exception:
        snapshot['bucket_art_map'] = {}
    # Capture every user-facing setting value. We enumerate from
    # settings.xml because addon.getSetting('') doesn't return a list.
    try:
        import xml.etree.ElementTree as _ET
        settings_xml_path = os.path.join(ADDON.getAddonInfo('path'), 'resources', 'settings.xml')
        tree = _ET.parse(settings_xml_path)
        for s in tree.findall('.//setting'):
            sid = s.get('id') or ''
            if not sid:
                continue
            try:
                snapshot['settings'][sid] = ADDON.getSetting(sid) or ''
            except Exception:
                pass
    except Exception:
        pass
    return snapshot


def config_export():
    """Write a complete configuration snapshot to a user-chosen file."""
    snapshot = _config_snapshot()
    dest_dir = xbmcgui.Dialog().browse(0, tr('Choose a save folder'), 'files', '', False, False, '')
    if not dest_dir:
        return
    timestamp = time.strftime('%Y%m%d-%H%M%S')
    filename = 'nuviohub-config-%s.json' % timestamp
    dest_path = os.path.join(dest_dir, filename)
    try:
        body = json.dumps(snapshot, ensure_ascii=False, indent=2)
        with xbmcvfs.File(dest_path, 'w') as fh:
            fh.write(body)
        notify(tr('Exported: %s') % filename)
    except Exception as exc:
        error(tr('Export failed: %s') % exc)


def config_import():
    """Restore configuration from a user-chosen JSON file."""
    src_path = xbmcgui.Dialog().browse(1, tr('Choose a previously-exported JSON file'), 'files', '.json', False, False, '')
    if not src_path or not src_path.lower().endswith('.json'):
        return
    if not xbmcgui.Dialog().yesno(
        'Nuvio Hub',
        tr('This will replace your current configuration with the file contents. Continue?'),
    ):
        return
    try:
        with xbmcvfs.File(src_path, 'r') as fh:
            text = fh.read()
        if not text:
            error(tr('The file is empty'))
            return
        snapshot = json.loads(text)
    except Exception as exc:
        error(tr('Could not read file: %s') % exc)
        return
    if not isinstance(snapshot, dict):
        error(tr('Invalid file format'))
        return
    from . import legacy_names as _legacy
    if int(snapshot.get('nuviohub_export_version') or snapshot.get(_legacy.OLD_EXPORT_VERSION_KEY) or 0) < 1:
        error(tr('Unsupported file version'))
        return
    # Restore providers — we keep the existing addition flow so all
    # manifest validation runs, but we cheat by writing the providers
    # store directly since the snapshot already contains validated
    # manifests at the time of export.
    restored_providers = 0
    try:
        providers_in = snapshot.get('providers') or []
        if providers_in:
            store.write_providers_raw(providers_in)
            restored_providers = len(providers_in)
    except Exception as exc:
        xbmc.log('[NuvioHub] import providers failed: %s' % exc, xbmc.LOGWARNING)
    restored_pins = 0
    try:
        pins_in = snapshot.get('catalog_pins') or []
        if pins_in:
            _save_catalog_pins(pins_in)
            restored_pins = len(pins_in)
    except Exception as exc:
        xbmc.log('[NuvioHub] import pins failed: %s' % exc, xbmc.LOGWARNING)
    try:
        bucket_art = snapshot.get('bucket_art_map') or {}
        if bucket_art:
            ADDON.setSetting('bucket_art_map', json.dumps(bucket_art, ensure_ascii=False))
    except Exception:
        pass
    restored_settings = 0
    try:
        _legacy_setting_ids = _legacy.SETTING_ALIAS_MAP
        for sid, sval in (snapshot.get('settings') or {}).items():
            sid = _legacy_setting_ids.get(sid, sid)
            # Skip the two settings whose state is captured by other
            # fields above to avoid double-write conflicts.
            if sid in ('bucket_art_map', 'catalog_pins_json'):
                continue
            try:
                ADDON.setSetting(sid, str(sval) if sval is not None else '')
                restored_settings += 1
            except Exception:
                pass
    except Exception:
        pass
    xbmcgui.Dialog().ok(
        'Nuvio Hub',
        tr('Imported successfully:\n• Providers: %d\n• Pinned catalogs: %d\n• Settings: %d') %
            (restored_providers, restored_pins, restored_settings))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass


def source_health():
    """Show diagnostic metrics for each installed source."""
    rows = store.list_providers() or []
    if not rows:
        notify(tr('No pinned add-ons'))
        return end_dir()
    # Read health snapshot from the existing blacklist / telemetry store
    # if present. The telemetry was recorded internally but never shown.
    try:
        from . import source_browser as _sb
        health_data = getattr(_sb, 'health_snapshot', lambda: {})() or {}
    except Exception:
        health_data = {}
    add_item(tr('[COLOR cyan]Add-on health — last 7 days[/COLOR]'),
             build_url(action='source_health'),
             is_folder=False,
             art=root_art('providers'),
             info={'title': 'Add-on health',
                   'plot': 'The higher the success rate and the lower the response time, the more reliable the add-on. Add-ons shown in grey have not been used in the past week.'})
    for prov in rows:
        prov_id = prov.get('id') or ''
        name = prov.get('name') or prov_id
        h = health_data.get(prov_id) or {}
        attempts = int(h.get('attempts') or 0)
        successes = int(h.get('successes') or 0)
        streams_produced = int(h.get('streams') or 0)
        avg_ms = int(h.get('avg_ms') or 0)
        last_failure = h.get('last_failure') or ''
        if attempts == 0:
            label = tr('[COLOR grey]%s — not used recently[/COLOR]') % name
            plot = 'No request to this add-on was recorded in the past seven days. It may be disabled or unused in your current lineup.'
        else:
            rate = (successes * 100) // max(1, attempts)
            colour = 'lightgreen' if rate >= 80 else ('yellow' if rate >= 50 else 'red')
            label = tr('[COLOR %s]%s — %d%% success • %d streams • %d ms[/COLOR]') % (colour, name, rate, streams_produced, avg_ms)
            plot_lines = [
                tr('Total attempts: %d') % attempts,
                tr('Succeeded: %d') % successes,
                tr('Streams produced: %d') % streams_produced,
                tr('Average response time: %d ms') % avg_ms,
            ]
            if last_failure:
                plot_lines.append(tr('Last failure: %s') % last_failure)
            plot = '\n'.join(plot_lines)
        add_item(label,
                 build_url(action='provider_menu', provider_id=prov_id),
                 art=provider_art(name, prov.get('manifest') or {}, base_url=prov.get('base_url') or ''),
                 info={'title': name, 'plot': plot})
    end_dir()


# v3.9.64: Performance Boost preset for slow devices (ARM 32-bit
# CoreELEC, older Fire TV, low-RAM boxes). Flips four settings at
# once so the user doesn't have to know what each one does:
#
#   1. lightweight_mode = true   — skip aggregated hub buckets +
#                                   skip the background index sync
#                                   scheduler. Sources stay fully
#                                   functional via the Sources page.
#   2. catalog_cache_ttl = 1800  — keep catalog responses 30 min
#                                   instead of the default 10 min,
#                                   reducing Stremio addon HTTP calls
#                                   by 3x for repeat browses.
#   3. meta_cache_ttl = 14400    — keep item metadata 4 hours instead
#                                   of the default 1 hour, reducing
#                                   per-item enrichment cost when the
#                                   user revisits the same lists.
#   4. tmdb_helper default       — set Nuvio Hub as TMDb Helper's
#                                   default player for movies and
#                                   episodes, so the skin's TMDb
#                                   Helper widgets browse via TMDb
#                                   Helper's local SQLite cache and
#                                   only hand off to Nuvio Hub at Play.
#
# This is the single biggest perceived-perf win for Arctic Fuse and
# any TMDb-Helper-dependent skin on a low-end device, because almost
# all browsing becomes a local cache hit instead of a Stremio HTTP
# round-trip.

PERFORMANCE_PRESET = (
    ('lightweight_mode',   'true'),
    ('catalog_cache_ttl',  '1800'),
    ('meta_cache_ttl',     '14400'),
)


# v3.9.103: one-tap "Recommended" preset. Bundles the quality profile +
# the performance preset into a single action so a first-run user goes
# from "nothing tuned" to "well-tuned" with one click instead of needing
# to find two separate settings buried in different categories.
RECOMMENDED_PRESET = (
    ('quality_profile',    'Balanced (recommended)'),
    ('lightweight_mode',   'true'),
    ('catalog_cache_ttl',  '1800'),
    ('meta_cache_ttl',     '14400'),
    ('bypass_all_filters', 'false'),  # ensure the new bypass is OFF in Recommended
)


def _performance_boost_state():
    """Return a dict with current preset state for the UI status row."""
    state = {'all_active': True, 'missing_count': 0, 'items': []}
    try:
        for key, want in PERFORMANCE_PRESET:
            cur = (ADDON.getSetting(key) or '').strip().lower()
            ok = cur == want.lower()
            state['items'].append((key, cur, want, ok))
            if not ok:
                state['all_active'] = False
                state['missing_count'] += 1
    except Exception:
        state['all_active'] = False
        state['missing_count'] = len(PERFORMANCE_PRESET)
    return state


def apply_performance_preset():
    """Flip all preset toggles after explaining trade-offs to the user."""
    state = _performance_boost_state()
    # Compose the explainer dialog: show exactly what will change so
    # the user understands the trade-offs rather than blindly accepting.
    lines = [
        tr('Will be applied to these settings:'),
        '',
    ]
    label_map = {
        'lightweight_mode':  tr('Lite mode (disables grouping folders and index sync)'),
        'catalog_cache_ttl': tr('Catalog cache: 30 minutes (instead of 10)'),
        'meta_cache_ttl':    tr('Metadata cache: 4 hours (instead of 1)'),
    }
    for key, cur, want, ok in state['items']:
        mark = '✓' if ok else '○'
        lines.append('[COLOR %s]%s[/COLOR] %s' % ('green' if ok else 'yellow', mark, label_map.get(key, key)))
    lines.extend([
        '',
        tr("The skin becomes lighter and faster. Lists use the cache instead of live fetches, and posters come from Kodi's cache after the first load. You lose no sources — everything stays on the Sources page."),
    ])
    if state['all_active']:
        # Already on — offer re-apply only.
        try:
            want = xbmcgui.Dialog().yesno(
                tr('Nuvio Hub • performance tuning'),
                tr('All lite-mode optimisations are already applied. Re-apply them anyway?'),
                yeslabel=tr('Re-apply'),
                nolabel=tr('Close'),
            )
        except Exception:
            want = False
        if not want:
            return integrations_menu()
    else:
        try:
            want = xbmcgui.Dialog().yesno(
                tr('Nuvio Hub • performance tuning'),
                '\n'.join(lines),
                yeslabel=tr('Enable all'),
                nolabel=tr('Cancel'),
            )
        except Exception:
            want = False
        if not want:
            return integrations_menu()

    applied = []
    failed = []
    for key, value in PERFORMANCE_PRESET:
        try:
            ADDON.setSetting(key, value)
            applied.append(key)
        except Exception as exc:
            xbmc.log('[NuvioHub] performance preset setSetting(%s, %s) failed: %s' % (key, value, exc), xbmc.LOGWARNING)
            failed.append(key)

    try:
        xbmc.log('[NuvioHub] performance preset applied: %s, failed: %s' % (
            ', '.join(applied) or 'none', ', '.join(failed) or 'none'), xbmc.LOGINFO)
    except Exception:
        pass

    if failed:
        notify(tr('Partially applied (%d succeeded, %d failed)') % (len(applied), len(failed)))
    else:
        notify(tr('Performance tuning applied ✓'))

    # Some toggles (lightweight_mode in particular) only take effect on
    # the next home() render. Suggest a restart of the addon's home so
    # the user sees the effect immediately. Optional — they can also
    # just navigate away and back.
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass

    return integrations_menu()


def _recommended_preset_state():
    """Return whether the full Recommended bundle is currently active."""
    state = {'all_active': True, 'missing_count': 0, 'items': []}
    try:
        for key, want in RECOMMENDED_PRESET:
            cur = (ADDON.getSetting(key) or '').strip()
            ok = cur.lower() == want.lower()
            state['items'].append((key, cur, want, ok))
            if not ok:
                state['all_active'] = False
                state['missing_count'] += 1
    except Exception:
        state['all_active'] = False
        state['missing_count'] = len(RECOMMENDED_PRESET)
    return state


def apply_recommended_preset():
    """One-tap "Recommended" setup: balanced quality profile + performance preset
    in a single confirmation. New users go from 'nothing tuned' to 'well-tuned'
    without hunting for two separate settings."""
    state = _recommended_preset_state()
    label_map = {
        'quality_profile':    tr('Quality profile: Balanced (recommended)'),
        'lightweight_mode':   tr('Lite mode (disables grouping folders and index sync)'),
        'catalog_cache_ttl':  tr('Catalog cache: 30 minutes'),
        'meta_cache_ttl':     tr('Metadata cache: 4 hours'),
        'bypass_all_filters': tr('Add-on filtering: on (filters are never bypassed)'),
    }
    lines = [tr('The recommended setup will apply:'), '']
    for key, cur, want, ok in state['items']:
        mark = '✓' if ok else '○'
        lines.append('[COLOR %s]%s[/COLOR] %s'
                     % ('green' if ok else 'yellow', mark,
                        label_map.get(key, key)))
    lines.extend([
        '',
        tr('Balanced: prefers 1080p+ and hides camera copies, with Debrid first. '
           'Lite mode serves lists from cache instead of fetching them live. '
           'You do not lose any add-ons — they all remain available on the Sources page.'),
    ])

    if state['all_active']:
        try:
            want_apply = xbmcgui.Dialog().yesno(
                'Nuvio Hub • ' + tr('Recommended setup'),
                tr('All recommended settings are already applied. Re-apply them anyway?'),
                yeslabel=tr('Re-apply'),
                nolabel=tr('Close'),
            )
        except Exception:
            want_apply = False
        if not want_apply:
            return integrations_menu()
    else:
        try:
            want_apply = xbmcgui.Dialog().yesno(
                'Nuvio Hub • ' + tr('Recommended setup'),
                '\n'.join(lines),
                yeslabel=tr('Enable all'),
                nolabel=tr('Cancel'),
            )
        except Exception:
            want_apply = False
        if not want_apply:
            return integrations_menu()

    applied = []
    failed = []
    for key, value in RECOMMENDED_PRESET:
        try:
            ADDON.setSetting(key, value)
            applied.append(key)
        except Exception as exc:
            xbmc.log('[NuvioHub] recommended preset setSetting(%s, %s) failed: %s'
                     % (key, value, exc), xbmc.LOGWARNING)
            failed.append(key)

    try:
        xbmc.log('[NuvioHub] recommended preset applied: %s, failed: %s'
                 % (', '.join(applied) or 'none',
                    ', '.join(failed) or 'none'), xbmc.LOGINFO)
    except Exception:
        pass

    if failed:
        notify(tr('Partially applied (%d succeeded, %d failed)') % (len(applied), len(failed)))
    else:
        notify(tr('Recommended setup applied ✓'))

    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass

    return integrations_menu()


def _first_run_done():
    """True if the welcome wizard has already been completed (or skipped)."""
    try:
        return (ADDON.getSetting('wizard_completed') or '').strip().lower() in ('true', '1', 'yes', 'on')
    except Exception:
        return True  # fail-safe: never re-show if we can't read


def _mark_first_run_done():
    try:
        ADDON.setSetting('wizard_completed', 'true')
    except Exception:
        pass


def maybe_show_first_run_wizard():
    return False  # The independent Nuvio interface owns onboarding.

def reset_first_run_wizard():
    """Action target so the user can re-run the wizard from Integrations."""
    try:
        ADDON.setSetting('wizard_completed', 'false')
        ADDON.setSetting('nuvio_wizard_applied', 'false')
        xbmcgui.Window(10000).clearProperty('nuvio.wizard.offered')
    except Exception:
        pass
    notify(tr('The wizard will appear the next time you open Nuvio Hub'))
    return integrations_menu()


# ────────────────────────────────────────────────────────────────────────────
# v3.9.106: AI Subtitles + IPTV service one-tap link
# ────────────────────────────────────────────────────────────────────────────
# The user runs a self-hosted AI-subtitles/IPTV backend (ai_subtitles.js + server.js)
# that exposes TWO Stremio-standard manifests per API key:
#
#   * Subtitles + AI translation:
#       {base}/subtitles/stremio/{apiKey}/manifest.json
#       Manifest id: legacy_names.SERVICE_MANIFEST_IDS
#
#   * IPTV (live channels + Xtream VOD/series via Stremio addon SDK):
#       {base}/{apiKey}/manifest.json
#       Manifest id: legacy_names.SERVICE_MANIFEST_IDS
#
# Both are Stremio addons → no special integration needed beyond what
# `add_provider_from_url` already does. This is purely a UX wrapper that
# (a) builds the two URLs from the user's saved api_key + base_url,
# (b) registers them as NuvioHub providers in one tap, and
# (c) cleanly removes them on unlink (detected by their stable manifest IDs).

_SERVICE_MANIFEST_IDS = _legacy_names.SERVICE_MANIFEST_IDS


def _service_base_url():
    raw = (ADDON.getSetting('nuviohub_service_base_url') or _legacy_names.SERVICE_BASE_URL).strip()
    # Strip trailing slashes; tolerate the user pasting a URL with a path.
    return raw.rstrip('/')


def _service_api_key():
    return (ADDON.getSetting('nuviohub_service_api_key') or '').strip()


def _service_build_urls(api_key=None, base=None):
    api_key = (api_key or _service_api_key()).strip()
    base = (base or _service_base_url()).rstrip('/')
    if not api_key or not base:
        return []
    return [
        ('AI Subtitles', '%s/subtitles/stremio/%s/manifest.json' % (base, api_key)),
        ('IPTV Service',  '%s/%s/manifest.json'                   % (base, api_key)),
    ]


def _service_installed_providers():
    """Return NuvioHub providers whose manifest id matches a known AI-subtitles/IPTV service id."""
    out = []
    try:
        for prov in (store.list_providers() or []):
            mfst = prov.get('manifest') or {}
            if mfst.get('id') in _SERVICE_MANIFEST_IDS:
                out.append(prov)
    except Exception:
        pass
    return out


def _service_state():
    """For the menu badge: linked / partial / not linked."""
    api_key = _service_api_key()
    installed = _service_installed_providers()
    return {
        'has_key': bool(api_key),
        'installed_count': len(installed),
        'expected_count': 2,
        'fully_linked': bool(api_key) and len(installed) >= 2,
    }


# ────────────────────────────────────────────────────────────────────────────
# Auto-trailer support intentionally removed in v3.9.111.
# NuvioHub no longer exposes action=auto_trailer or starts trailer playback from
# skin onload hooks; this keeps startup/playback lighter and avoids background
# polling on Kodi/CoreELEC devices.
# ────────────────────────────────────────────────────────────────────────────

def subtitle_service_link():
    """One-tap: install both service manifests as NuvioHub providers.

    Safe to invoke from RunPlugin (settings action button) — does not try to
    render a directory listing, just notifies and refreshes containers."""
    api_key = _service_api_key()
    if not api_key:
        # No settings field exposes the key; ask for it here and keep it.
        try:
            api_key = (xbmcgui.Dialog().input(tr('AI Subtitles & IPTV API key')) or '').strip()
        except Exception:
            api_key = ''
        if not api_key:
            notify(tr('Enter your AI Subtitles & IPTV API key first'))
            return
        ADDON.setSetting('nuviohub_service_api_key', api_key)

    urls = _service_build_urls()
    if not urls:
        notify(tr('Could not build service links'))
        return

    # Make linking idempotent — remove any old service providers first so a
    # re-link picks up the latest manifest (handy when the user rotates keys
    # or upgrades the backend).
    try:
        for prov in _service_installed_providers():
            try:
                store.remove_provider(prov.get('id') or '')
            except Exception:
                pass
    except Exception:
        pass

    installed_names = []
    failed = []
    for display_name, manifest_url in urls:
        try:
            from .nuviohub.api import add_provider_from_url
            add_provider_from_url(manifest_url, name=display_name)
            installed_names.append(display_name)
        except Exception as exc:
            try:
                xbmc.log('[NuvioHub] service link failed for %s: %s'
                         % (display_name, exc), xbmc.LOGWARNING)
            except Exception:
                pass
            failed.append((display_name, str(exc)))

    if installed_names and not failed:
        notify(tr('AI Subtitles & IPTV linked ✓ (%d add-ons)') % len(installed_names))
    elif installed_names and failed:
        try:
            xbmcgui.Dialog().ok(
                'Nuvio Hub • AI Subtitles & IPTV',
                tr('Partially linked:\n✓ %s\n✗ %s\n\nCheck the key and the server address.')
                  % (', '.join(installed_names),
                     ', '.join('%s (%s)' % (n, e[:60]) for n, e in failed)),
            )
        except Exception:
            notify(tr('Partially linked'))
    else:
        try:
            err_msg = '\n'.join('• %s: %s' % (n, e[:80]) for n, e in failed)
            xbmcgui.Dialog().ok(
                'Nuvio Hub • AI Subtitles & IPTV',
                tr('Linking failed completely:\n\n%s\n\nCheck:\n'
                   '1. The API key is correct\n'
                   '2. The server address is correct\n'
                   '3. Your subscription is active') % err_msg,
            )
        except Exception:
            notify(tr('Service linking failed'))

    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return


def subtitle_service_unlink():
    """Remove NuvioHub providers that came from the AI-subtitles/IPTV service.

    Safe to invoke from RunPlugin (settings action button) — does not try to
    render a directory listing."""
    installed = _service_installed_providers()
    if not installed:
        notify(tr('No AI Subtitles & IPTV add-ons registered'))
        return
    try:
        confirmed = xbmcgui.Dialog().yesno(
            'Nuvio Hub • AI Subtitles & IPTV',
            tr('Remove %d AI Subtitles & IPTV add-ons? Your key stays saved.') % len(installed),
            yeslabel=tr('Delete'),
            nolabel=tr('Cancel'),
        )
    except Exception:
        confirmed = True
    if not confirmed:
        return
    removed = 0
    for prov in installed:
        try:
            store.remove_provider(prov.get('id') or '')
            removed += 1
        except Exception:
            pass
    notify(tr('Removed %d AI Subtitles & IPTV add-ons') % removed)
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return


def _plex_error(exc):
    """Show a safe Plex error without ever exposing its auth token."""
    try:
        xbmc.log('[NuvioHub] Plex: %s' % exc, xbmc.LOGWARNING)
    except Exception:
        pass
    error(str(exc) or 'Could not connect to Plex')


def _plex_server(server_id):
    server = plex_client.server_by_id(server_id)
    if not server:
        raise plex_client.PlexError('This server is no longer available. Refresh the Plex list and try again.')
    return server


_ART_WARM_SEEN = set()
_ART_WARM_LOCK = threading.Lock()


def _warm_server_art(tmdb_id, imdb_id, media_type, title, year):
    """Resolve TMDb art in the background so the NEXT render is a cache hit."""
    key = '%s|%s|%s' % (media_type, tmdb_id, imdb_id)
    with _ART_WARM_LOCK:
        if key in _ART_WARM_SEEN or len(_ART_WARM_SEEN) > 400:
            return
        _ART_WARM_SEEN.add(key)

    def _run():
        try:
            _tmdb_direct.art_for(tmdb_id=tmdb_id, imdb_id=imdb_id,
                                 media_type=media_type, title=title, year=year)
        except Exception:
            pass

    _submit_optional(_run, key='art:%s' % key)


def _server_meta_source(backend):
    """Resolve the meta-source policy for a Plex/Emby server row.

    The server backends are treated as first-class meta targets ('plex_server' /
    'emby_server'), so they obey the SAME policy as everything else:

        per-server override  ->  global `default_meta_source`

    'native' means "keep the server's own artwork" — which is what you want when
    a library has custom posters, overlays (4K/HDR/Atmos badges), or bespoke art
    that TMDb simply does not have.
    """
    target = 'emby_server' if backend == 'emby' else 'plex_server'
    try:
        return (_meta_source.get_meta_source_for(target) or 'auto')
    except Exception:
        return 'auto'


def _server_tmdb_art(item, fallback, backend='plex'):
    """Resolve Plex/Emby row art according to the meta-source policy.

    Why (v3.9.232): server art means one AUTHENTICATED request per tile against
    the user's own — often remote — box. That is slow, and nothing else in Kodi
    can reuse it. TMDb art is a canonical image.tmdb.org URL, byte-identical to
    what TMDb Helper requests, so Kodi's TEXTURE CACHE is shared: titles TMDb
    Helper has already drawn paint instantly here, and posters are w500 (~70 KB)
    instead of a full-size server transcode.

    v3.9.234: this now honours `default_meta_source` (and a per-server override)
    instead of a separate boolean, so picking "TMDb Helper" once applies to the
    WHOLE addon — Stremio catalogs and Plex/Emby libraries alike. Choose
    'native' for a server whose posters carry overlays you want to keep.

    This never blocks the listing: only CACHED art is used on the render path;
    on a miss the server art is kept for this pass and TMDb is warmed in the
    background so the next visit is instant.
    """
    source_id = _server_meta_source(backend)
    # 'native' = the server's own art wins (custom posters / overlays / badges).
    if source_id == 'native':
        return fallback
    # Legacy escape hatch: the old boolean still force-disables the TMDb path.
    if not _setting_bool('server_art_from_tmdb', True):
        return fallback

    ids = item.get('ids') or {}
    tmdb_id = str(ids.get('tmdb_id') or '').strip()
    imdb_id = str(ids.get('imdb_id') or '').strip()
    if not tmdb_id and not imdb_id:
        return fallback

    media = item.get('media_type') or 'movie'
    # Seasons/episodes inherit the SHOW poster: TMDb per-episode stills are not
    # what these rows want, and the show poster is what the user recognises.
    mt = 'tv' if media in ('show', 'season', 'episode') else 'movie'
    _title = item.get('raw_title') or item.get('title') or ''
    _year = item.get('year') or ''

    # TIER 1 — TMDb Helper's OWN SQLite cache (ItemDetails.db), opened read-only.
    # This is the lightest possible source: no network, no API key, no second
    # copy of the data. Anything TMDb Helper has already browsed is served from
    # its own DB, and because the URLs it stores rebuild to the exact same
    # image.tmdb.org/t/p/w500 paths, Kodi's texture cache is shared too — those
    # posters are usually ALREADY on disk and paint with no download at all.
    bundle = {}
    try:
        bundle = _tmdb_art_db.get_art_bundle_from_db(
            tmdb_id=tmdb_id, media_type=mt, imdb_id=imdb_id,
            title=_title, year=_year) or {}
    except Exception:
        bundle = {}

    # TIER 2 — Nuvio Hub's own TMDb cache, cached-only (never blocks the listing).
    # This is a GAP-FILLER, not a contradiction of a 'tmdb_helper' choice: both
    # tiers resolve to identical image.tmdb.org URLs, so a title TMDb Helper has
    # not browsed yet still gets TMDb art instead of falling back to a heavy
    # server transcode. Only 'native' keeps the server's own artwork.
    if not bundle.get('poster'):
        try:
            bundle = _tmdb_direct.art_cached_only(
                tmdb_id=tmdb_id, imdb_id=imdb_id, media_type=mt,
                title=_title, year=_year) or {}
        except Exception:
            bundle = {}

    if bundle.get('poster'):
        out = dict(fallback or {})
        out['poster'] = bundle['poster']
        out['thumb'] = bundle['poster']
        out['icon'] = bundle['poster']
        if bundle.get('fanart'):
            out['fanart'] = bundle['fanart']
            out['landscape'] = bundle['fanart']
        if bundle.get('clearlogo'):
            out['clearlogo'] = bundle['clearlogo']
        return out

    # Both cached tiers missed: keep the server art for THIS render (never
    # block a listing) and warm Nuvio Hub's TMDb cache off-thread so the next
    # visit is instant. TMDb Helper's DB fills itself as the user browses it.
    _warm_server_art(tmdb_id, imdb_id, mt, _title, _year)
    return fallback


def _plex_item_art(item):
    poster = plex_client.artwork_url(item, item.get('thumb') or item.get('parent_thumb') or '')
    fanart = plex_client.artwork_url(item, item.get('art') or item.get('thumb') or '')
    return _server_tmdb_art(
        item, {'poster': poster, 'thumb': poster, 'fanart': fanart, 'landscape': fanart},
        backend='plex')


def _plex_item_info(item):
    media = item.get('media_type') or 'movie'
    kodi_type = {'show': 'tvshow', 'season': 'season', 'episode': 'episode'}.get(media, 'movie')
    title = item.get('raw_title') or item.get('title') or 'Plex'
    if media == 'episode':
        title = item.get('raw_title') or title
    # DPlex-style: the technical facts line (resolution/codec/size) leads the
    # plot so the info panel shows the file data first.
    plot = item.get('summary') or ''
    facts = item.get('info_line') or ''
    if facts:
        plot = ('%s\n\n%s' % (facts, plot)) if plot else facts
    info = {
        'title': title,
        'plot': plot,
        'year': item.get('year') or 0,
        'mediatype': kodi_type,
        'duration': int((item.get('duration_ms') or 0) / 1000),
    }
    if item.get('rating'):
        info['rating'] = float(item.get('rating') or 0)
    if item.get('content_rating'):
        info['mpaa'] = item.get('content_rating')
    if item.get('studio'):
        info['studio'] = item.get('studio')
    if item.get('tagline'):
        info['tagline'] = item.get('tagline')
    if item.get('premiered'):
        info['premiered'] = item.get('premiered')
    if item.get('genres'):
        info['genre'] = list(item.get('genres') or [])
    if item.get('directors'):
        info['director'] = list(item.get('directors') or [])
    if item.get('writers'):
        info['writer'] = list(item.get('writers') or [])
    if item.get('cast'):
        info['cast'] = list(item.get('cast') or [])
    if media == 'episode':
        info.update({
            'tvshowtitle': item.get('show_title') or '',
            'season': item.get('season') or 0,
            'episode': item.get('index') or 0,
        })
    return info


def _plex_item_ids(item):
    ids = dict(item.get('ids') or {})
    return {k: v for k, v in ids.items() if v}


def _plex_render_one(item):
    """Render one Plex row (shared by the Plex pages and unified search)."""
    kind = item.get('media_type') or 'movie'
    server_id = item.get('server_id') or ''
    rating_key = item.get('rating_key') or ''
    key = item.get('key') or ''
    if not server_id or not (rating_key or key):
        return False
    if kind in ('show', 'season'):
        if not key:
            return False
        path = build_url(action='plex_children', server_id=server_id,
                         key=key, title=item.get('title') or 'Plex')
        is_folder = True
    else:
        path = build_url(action='plex_play', server_id=server_id,
                         rating_key=rating_key)
        is_folder = False
    label = item.get('title') or 'Plex'
    # Identifying the server makes same-title search results immediately
    # useful when the user has a home server plus shared servers.
    server_name = item.get('server_name') or 'Plex'
    if kind == 'episode':
        label = '%s  [COLOR grey](S%02dE%02d)[/COLOR]' % (
            label, int(item.get('season') or 0), int(item.get('index') or 0))
    _facts = item.get('info_line') or ''
    add_item(label, path, is_folder=is_folder, info=_plex_item_info(item),
             art=_plex_item_art(item), ids=_plex_item_ids(item),
             label2=('%s • Plex • %s' % (_facts, server_name)) if _facts else ('Plex • %s' % server_name),
             # Native rows may open a version chooser. Marking them resolvable
             # makes Kodi report "playback failed" when the user presses Back.
             properties=None)
    return True


def _plex_render_items(items, empty_label='No items in Plex'):
    """Render Plex movies/shows/seasons/episodes in the current directory."""
    emitted = 0
    for item in items or []:
        if _plex_render_one(item):
            emitted += 1
    if not emitted:
        add_item('[COLOR grey]%s[/COLOR]' % empty_label,
                 build_url(action='plex_menu'), is_folder=True,
                 art=root_art('plex'), info={'title': empty_label})
    return emitted


def plex_login():
    """Link Plex by scanning a QR code (or typing the short code).

    v3.9.180: DPlex-style QR sign-in. The plex.tv/link URL is rendered as a
    local QR PNG (pure-Python encoder, no Pillow/network), so the phone camera
    opens the page with the code already filled in — far easier than typing a
    code on a TV remote. Typing still works: the code is shown next to the QR.
    """
    try:
        pin = plex_client.request_pin()
    except Exception as exc:
        return _plex_error(exc)
    code = str(pin.get('code') or '')
    link_url = pin.get('link_url') or ('https://plex.tv/link/?pin=%s' % code)
    xbmc.log('[NuvioHub] Plex PIN created id=%s flavor=%s' % (pin.get('id'), pin.get('flavor')), xbmc.LOGINFO)

    # v4.6.8: DUAL-PIN flow. 4.6.7 fed the auth deep link the weak 4-char
    # pin — app.plex.tv only accepts STRONG pins (plexapi gates oauthUrl
    # behind them explicitly), so linking broke. The weak pin now does
    # exactly what the early versions did (typed at plex.tv/link — the flow
    # that always worked), and a SEPARATE strong pin drives the QR deep
    # link. Polling alternates between the two; whichever authorises first
    # completes the link. Strong-pin failure degrades to the early
    # weak-only behaviour, never a broken QR.
    pin_qr = None
    try:
        pin_qr = plex_client.request_pin(strong=True)
        xbmc.log('[NuvioHub] Plex strong PIN created id=%s' % pin_qr.get('id'), xbmc.LOGINFO)
    except Exception as exc:
        xbmc.log('[NuvioHub] strong PIN unavailable (%s) — QR falls back to plex.tv/link' % exc,
                 xbmc.LOGWARNING)
        pin_qr = None

    qr_path = ''
    try:
        if pin_qr:
            scan_url = plex_client.auth_link_url(pin_qr.get('code') or '')
        else:
            scan_url = link_url
        qr_path = plex_qr.qr_png(scan_url)
    except Exception:
        qr_path = ''

    window = None
    try:
        window = plex_qr.QRLinkWindow(qr_path=qr_path, code=code)
        window.show()
    except Exception as exc:
        xbmc.log('[NuvioHub] QR window unavailable (%s) — falling back to dialog' % exc, xbmc.LOGWARNING)
        window = None
    progress = None
    if window is None:
        progress = xbmcgui.DialogProgress()
        progress.create('Plex', tr('Open plex.tv/link on your phone or browser.\nPIN: %s\nWaiting for confirmation…') % code)

    linked = None
    try:
        monitor = xbmc.Monitor()
        errors = 0
        # v4.6.8: poll the weak (typed) pin and, when present, the strong
        # (QR) pin on alternating ticks — same request rate as before.
        pin_targets = [pin] + ([pin_qr] if pin_qr else [])
        for tick in range(150):  # five minutes, matching the PIN lifetime
            if window is not None and window.cancelled:
                return
            if progress is not None and progress.iscanceled():
                return
            target = pin_targets[tick % len(pin_targets)]
            try:
                linked = plex_client.poll_pin(target.get('id'), target.get('code'),
                                              flavor=target.get('flavor') or 'legacy')
                errors = 0
            except Exception as exc:
                errors += 1
                if errors >= 5:
                    xbmc.log('[NuvioHub] Plex PIN poll failed: %s' % exc, xbmc.LOGERROR)
                    return _plex_error(exc)
                linked = None
            if linked:
                break
            if progress is not None:
                progress.update(min(99, int((tick + 1) * 100 / 150)),
                                tr('Open plex.tv/link on your phone or browser.\nPIN: %s\nWaiting for Plex to confirm the link…') % code)
            if monitor.waitForAbort(2):
                return
    finally:
        try:
            if window is not None:
                window.close()
            if progress is not None:
                progress.close()
        except Exception:
            pass

    if not linked:
        notify('Linking timed out — try again')
        return
    # Authentication and resource discovery are deliberately separate.
    # The durable account is already saved at this point; a temporary failure
    # in plex.tv/resources must not make a successful link look failed or make
    # the user repeat the PIN flow.
    servers = []
    try:
        servers = plex_client.servers(force=True)
    except Exception as exc:
        xbmc.log('[NuvioHub] Plex linked but resource discovery is temporarily unavailable: %s' % exc,
                 xbmc.LOGWARNING)
    xbmc.log('[NuvioHub] Plex linked: user=%s servers=%d' % (linked.get('username') or '?', len(servers)), xbmc.LOGINFO)
    if servers:
        notify(tr('Plex linked • %d servers') % len(servers))
    else:
        notify('Plex linked • servers will refresh automatically')
    xbmc.executebuiltin('Container.Refresh')


def plex_logout():
    try:
        confirmed = xbmcgui.Dialog().yesno('Plex', tr('Disconnect the Plex account from Nuvio Hub?'))
    except Exception:
        confirmed = True
    if confirmed:
        plex_client.sign_out()
        notify('Plex disconnected')
        try:
            xbmc.executebuiltin('Container.Refresh')
        except Exception:
            pass


def plex_menu():
    _set_render_section('plex')
    if not plex_client.is_signed_in():
        add_item('Link Plex with a PIN', build_url(action='plex_login'), is_folder=False,
                 art=root_art('accounts'),
                 info={'title': 'Plex', 'plot': 'Link Plex through plex.tv/link without entering a token by hand.'})
        add_item('Account &amp; settings', build_url(action='integrations_menu'),
                 art=root_art('accounts'))
        return end_dir(cache=False)
    account = plex_client.account()
    name = account.get('username') or 'Connected'
    add_item('Plex • %s' % name, build_url(action='plex_menu'),
             art=root_art('accounts'), is_folder=True,
             info={'title': 'Plex', 'plot': 'Every Plex library and server linked to this account.'})
    add_item('Continue on Plex', build_url(action='plex_continue'), art=root_art('continue'),
             info={'title': 'Continue on Plex', 'plot': 'Combines On Deck from every available server.'})
    add_item('All Plex servers', build_url(action='plex_servers'), art=root_art('plex'),
             info={'title': 'Plex servers', 'plot': 'Every private and shared server linked to the account.'})
    add_item('Search Plex', build_url(action='plex_search'), art=root_art('search_movie'),
             info={'title': 'Search Plex', 'plot': 'Search every library on every server, like Dplex.'})
    add_item('Refresh servers', build_url(action='plex_refresh'), is_folder=False,
             art=root_art('settings'), info={'title': 'Refresh Plex'})
    add_item('Disconnect Plex', build_url(action='plex_logout'), is_folder=False,
             art=root_art('accounts'), info={'title': 'Disconnect Plex'})
    end_dir(cache=False)


def plex_refresh():
    try:
        count = len(plex_client.servers(force=True))
        notify(tr('Plex refreshed • %d servers') % count)
    except Exception as exc:
        _plex_error(exc)
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass


def plex_servers():
    try:
        rows = plex_client.servers()
    except Exception as exc:
        _plex_error(exc)
        return end_dir(cache=False)
    for server in rows:
        name = server.get('name') or 'Plex Server'
        suffix = 'Local' if server.get('owned') else 'Shared'
        add_item('%s  [COLOR grey](%s)[/COLOR]' % (name, suffix),
                 build_url(action='plex_server', server_id=server.get('id') or ''),
                 art=root_art('plex'),
                 info={'title': name,
                       'plot': '%s • %s' % (server.get('product') or 'Plex Media Server', suffix)})
    if not rows:
        add_item('[COLOR yellow]No Plex servers found[/COLOR]',
                 build_url(action='plex_refresh'), is_folder=False, art=root_art('settings'),
                 info={'title': 'Plex', 'plot': 'Check that your account owns or shares a server, then refresh the list.'})
    end_dir(content='files', cache=False)


def plex_server(server_id):
    try:
        server = _plex_server(server_id)
        libraries = plex_client.libraries(server)
    except Exception as exc:
        _plex_error(exc)
        return end_dir(cache=False)
    name = server.get('name') or 'Plex Server'
    add_item(tr('Continue • %s') % name,
             build_url(action='plex_continue', server_id=server_id), art=root_art('continue'),
             info={'title': 'Continue on Plex', 'plot': tr('Next content from %s') % name})
    for library in libraries:
        library_title = library.get('title') or 'Library'
        _lib_type = library.get('type') or ''
        _lib_key = library.get('key') or ''
        _lib_url = lambda _sort, _k=library.get('key') or '', _t=library_title, _lt=_lib_type: build_url(
            action='plex_library', server_id=server_id, key=_k, title=_t,
            library_type=_lt, sort=_sort)
        # v3.9.172: the official Plex sorts on long-press, exactly like the
        # Plex app's own ordering options.
        _sorts = [("\u0622\u062e\u0631 \u0625\u0636\u0627\u0641\u0629", 'addedAt:desc'),
                  ('Last Release', 'originallyAvailableAt:desc'),
                  ('Rating', 'rating:desc'),
                  ("\u0627\u0644\u0627\u0633\u0645", 'titleSort'),
                  ('Year', 'year:desc')]
        if _lib_type == 'show':
            _sorts.insert(1, ('Latest episode released', 'episode.addedAt:desc'))
        # v3.9.232: the sort used to live ONLY in the Container.Update URL, so
        # nothing was stored and the tile always reopened unsorted — the user
        # had to re-pick the order every time.  Picking now goes through
        # plex_sort(), which SAVES the choice; the tile opens with it.
        _saved = sort_prefs.get_sort('plex', server_id, _lib_key, '')
        _ctx = [(tr('Sort: %s%s') % (('● ' if _key == _saved else ''), _label),
                 'RunPlugin(%s)' % build_url(
                     action='plex_sort', server_id=server_id, key=_lib_key,
                     title=library_title, library_type=_lib_type, sort=_key))
                for _label, _key in _sorts]
        _ctx.append(('Sort: default', 'RunPlugin(%s)' % build_url(
            action='plex_sort', server_id=server_id, key=_lib_key,
            title=library_title, library_type=_lib_type, sort='')))
        _saved_label = next((l for l, k in _sorts if k == _saved), '')
        _plot = '%s • %s' % (name, _lib_type or 'library')
        if _saved_label:
            _plot = tr('%s • sorted by: %s') % (_plot, _saved_label)
        add_item(library_title,
                 _lib_url(_saved),
                 art=root_art('plex'),
                 info={'title': library_title, 'plot': _plot},
                 context_menu=_ctx)
    if not libraries:
        add_item('[COLOR grey]No video libraries visible for this account[/COLOR]',
                 build_url(action='plex_servers'), art=root_art('plex'))
    end_dir(content='files', cache=False)


def plex_continue(server_id=''):
    rows = []
    try:
        servers = [_plex_server(server_id)] if server_id else plex_client.servers()
        for server in servers:
            try:
                rows.extend(plex_client.on_deck(server))
            except Exception as exc:
                try:
                    xbmc.log('[NuvioHub] Plex On Deck skipped: %s' % exc, xbmc.LOGWARNING)
                except Exception:
                    pass
    except Exception as exc:
        _plex_error(exc)
    _plex_render_items(rows, 'Nothing to continue on Plex')
    end_dir(content='videos', cache=False)


def plex_sort(server_id, key, title='', library_type='', sort=''):
    """Persist a sort choice for a Plex library, then reopen it that way.

    Invoked via RunPlugin from the library context menu.  The chosen sort is
    saved (empty = back to the server default) so the library tile — and any
    later visit — opens in the same order.
    """
    sort_prefs.set_sort('plex', server_id, key, sort or '')
    url = build_url(action='plex_library', server_id=server_id, key=key,
                    title=title, library_type=library_type, sort=sort or '',
                    start='0')
    xbmc.executebuiltin('Container.Update(%s,replace)' % url)


def plex_library(server_id, key, title='', library_type='', start='0', sort=''):
    # An explicit ?sort= wins (the chooser passes one, and so does "المزيد").
    # Otherwise fall back to the remembered choice for this library so that
    # reopening it keeps the order the user picked.
    if not sort:
        sort = sort_prefs.get_sort('plex', server_id, key, '')
    try:
        server = _plex_server(server_id)
        path = '/library/sections/%s/all' % key
        rows, total = plex_client.children(server, path, start=int(start or 0), sort=sort)
        _plex_render_items(rows, 'No items in this library')
        next_start = int(start or 0) + len(rows)
        if rows and total > next_start:
            add_item('More', build_url(action='plex_library', server_id=server_id,
                                          key=key, title=title, sort=sort,
                                          library_type=library_type, start=str(next_start)),
                     art=root_art('plex'), info={'title': 'More'})
    except Exception as exc:
        _plex_error(exc)
    content = 'tvshows' if library_type == 'show' else 'movies'
    end_dir(content=content, cache=False)


def plex_children(server_id, key, title='', start='0'):
    try:
        server = _plex_server(server_id)
        rows, total = plex_client.children(server, key, start=int(start or 0))
        _plex_render_items(rows, 'Nothing here')
        next_start = int(start or 0) + len(rows)
        if rows and total > next_start:
            add_item('More', build_url(action='plex_children', server_id=server_id,
                                          key=key, title=title, start=str(next_start)),
                     art=root_art('plex'), info={'title': 'More'})
    except Exception as exc:
        _plex_error(exc)
    end_dir(content='episodes', cache=False)


def plex_search(query='', media_type=''):
    if not plex_client.is_signed_in():
        return plex_menu()
    if not query:
        keyboard = xbmc.Keyboard('', tr('Search all Plex servers'))
        keyboard.doModal()
        if not keyboard.isConfirmed():
            return end_dir(cache=False)
        query = keyboard.getText().strip()
    if not query:
        return end_dir(cache=False)
    try:
        rows = plex_client.search_all(query, media_type)
    except Exception as exc:
        _plex_error(exc)
        rows = []
    add_item(tr('🔍 Plex: %s • %d results') % (query, len(rows)),
             build_url(action='plex_search', query=query, media_type=media_type),
             art=root_art('search_movie'), info={'title': 'Search Plex', 'plot': query})
    _plex_render_items(rows, 'No Plex results for this search')
    end_dir(content=_directory_content_for_type(media_type or 'movie'), cache=False)


def plex_play(server_id, rating_key):
    """Resolve fresh Plex metadata, then Direct Play with companion progress."""
    try:
        server = _plex_server(server_id)
        item = plex_client.metadata(server, rating_key)
    except Exception as exc:
        return _plex_error(exc)
    part_key = ''
    selected_version = {}
    versions = [v for v in (item.get('versions') or []) if v.get('part_key')]
    if len(versions) > 1:
        # DPlex-style version picker: poster + resolution/HDR/size per row.
        poster = plex_client.artwork_url(item, item.get('thumb') or '')
        try:
            rows = []
            for i, v in enumerate(versions):
                li = xbmcgui.ListItem(item.get('raw_title') or item.get('title') or 'Plex')
                try:
                    li.setLabel2(v.get('version_label') or 'Version %d' % (i + 1))
                    if poster:
                        li.setArt({'icon': poster, 'thumb': poster, 'poster': poster})
                except Exception:
                    pass
                rows.append(li)
            choice = xbmcgui.Dialog().select(tr('Choose version'), rows, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(
                tr('Choose version'), [v.get('version_label') or '?' for v in versions])
        if choice < 0:
            return
        selected_version = versions[choice]
        part_key = selected_version.get('part_key') or ''
    elif versions:
        selected_version = versions[0]
        part_key = selected_version.get('part_key') or ''
    try:
        stream_url = plex_client.playback_url(item, part_key=part_key)
    except Exception as exc:
        return _plex_error(exc)
    ids = item.get('ids') or {}
    media_type = item.get('media_type') or 'movie'
    # v3.9.206: content that exists ONLY on the user's server — a Turkish
    # series with no IMDb/TMDb entry, a home recording, a rare release — used
    # to end up with an EMPTY canonical_id here. Everything downstream keys on
    # it: the playback session, the resume point, the switch-source index. So
    # the item played once and could never be resumed. A stable, namespaced
    # fallback fixes all of that without touching identified content.
    canonical_id = (ids.get('imdb_id')
                    or ('tmdb:%s' % ids.get('tmdb_id') if ids.get('tmdb_id') else '')
                    or 'plex:%s:%s' % (server_id, rating_key))
    if not canonical_id:
        canonical_id = 'plex:%s:%s' % (server_id, rating_key)
    ctx = {
        'stream_url': stream_url,
        'stream_key': 'plex:%s:%s' % (server_id, rating_key),
        'provider_id': 'plex_native', 'provider_name': 'Plex Native • %s' % (server.get('name') or 'Server'),
        'server_type': 'plex', 'server_url': item.get('server_url') or '',
        'token': item.get('token') or server.get('token') or '',
        'rating_key': str(rating_key), 'client_id': plex_client.client_identifier(),
        'product': 'Nuvio Hub', 'product_version': ADDON.getAddonInfo('version') or '3.9.202', 'device_name': 'Kodi',
        'canonical_id': canonical_id, 'video_id': str(rating_key),
        'media_type': 'series' if media_type in ('show', 'season', 'episode') else 'movie',
        'title': item.get('raw_title') or item.get('title') or 'Plex',
        'show_title': item.get('show_title') or '',
        'year': item.get('year') or 0, 'plot': item.get('summary') or '',
        'duration_ms': item.get('duration_ms') or 0,
        'duration': int((item.get('duration_ms') or 0) / 1000),
        'resume_seconds': float(item.get('view_offset_ms') or 0) / 1000.0,
        'season': item.get('season') or 0, 'episode': item.get('index') or 0,
        'poster': plex_client.artwork_url(item, item.get('thumb') or ''),
        'background': plex_client.artwork_url(item, item.get('art') or item.get('thumb') or ''),
        'imdb_id': _normalize_imdb_id(ids.get('imdb_id')) or '', 'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'subtitles': list(selected_version.get('subtitles') or []),
    }
    return _play_with_context(ctx, stream_key=ctx['stream_key'], use_resolved_url=False)


def _emby_error(exc):
    notify('Emby: %s' % exc)


def _emby_server():
    servers = emby_client.servers()
    if not servers:
        raise Exception('Emby is not linked yet')
    return servers[0]


def _emby_art(item, server):
    thumb = emby_client.artwork_url(server, item.get('thumb') or '')
    fan = emby_client.artwork_url(server, item.get('art') or '', kind='Backdrop')
    return _server_tmdb_art(
        item, {'poster': thumb, 'thumb': thumb, 'icon': thumb, 'fanart': fan},
        backend='emby')


def _emby_render_one(item, server):
    kind = item.get('media_type') or 'movie'
    item_id = item.get('rating_key') or ''
    if not item_id:
        return False
    if kind in ('show', 'season'):
        path = build_url(action='emby_children', key=item_id,
                         title=item.get('title') or 'Emby')
        is_folder = True
    else:
        path = build_url(action='emby_play', item_id=item_id)
        is_folder = False
    label = item.get('title') or 'Emby'
    if kind == 'episode':
        label = '%s  [COLOR grey](S%02dE%02d)[/COLOR]' % (
            label, int(item.get('season') or 0), int(item.get('index') or 0))
    facts = item.get('info_line') or ''
    name = item.get('server_name') or 'Emby'
    add_item(label, path, is_folder=is_folder,
             info=_plex_item_info(item), art=_emby_art(item, server),
             ids=_plex_item_ids(item),
             label2=('%s • Emby • %s' % (facts, name)) if facts else ('Emby • %s' % name),
             properties=None)
    return True


def emby_continue():
    """Emby Continue Watching (Resume + Next Up), mirroring plex_continue."""
    rows = []
    try:
        server = _emby_server()
        try:
            resumed, _total = emby_client.resume(server)
            rows.extend(resumed)
        except Exception as exc:
            try:
                xbmc.log('[NuvioHub] Emby Resume skipped: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
        # Next Up fills in series whose last episode was finished, so the row
        # behaves like Plex's On Deck rather than a bare "partially played" list.
        try:
            seen = {r.get('rating_key') for r in rows}
            for row in emby_client.next_up(server):
                if row.get('rating_key') not in seen:
                    rows.append(row)
        except Exception as exc:
            try:
                xbmc.log('[NuvioHub] Emby NextUp skipped: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
    except Exception as exc:
        _emby_error(exc)
    _emby_render_items(rows, 'Nothing to continue on Emby')
    end_dir(content='videos', cache=False)


def _emby_render_items(items, empty_label='No items in Emby'):
    try:
        server = _emby_server()
    except Exception as exc:
        _emby_error(exc)
        return 0
    count = 0
    for item in items or []:
        if _emby_render_one(item, server):
            count += 1
    if not count:
        add_item('[COLOR grey]%s[/COLOR]' % empty_label, build_url(action='emby_menu'),
                 art=root_art('emby'))
    return count


def emby_login():
    """Sign in with the Emby username/password (EmbyCon's AuthenticateByName)."""
    url = xbmcgui.Dialog().input(tr('Emby server address (example: http://192.168.1.10:8096)'))
    if not url:
        return
    user = xbmcgui.Dialog().input(tr('Username'))
    if not user:
        return
    password = xbmcgui.Dialog().input(tr('Password'), option=xbmcgui.ALPHANUM_HIDE_INPUT)
    try:
        auth = emby_client.sign_in(url, user, password or '')
    except Exception as exc:
        return _emby_error(exc)
    xbmc.log('[NuvioHub] Emby linked: user=%s server=%s' % (auth.get('username'), auth.get('server_name')), xbmc.LOGINFO)
    notify(tr('Emby linked • %s') % (auth.get('server_name') or ''))
    xbmc.executebuiltin('Container.Refresh')


def emby_logout():
    emby_client.sign_out()
    notify('Emby disconnected')
    xbmc.executebuiltin('Container.Refresh')


def emby_menu():
    _set_render_section('emby')
    if not emby_client.is_signed_in():
        add_item('Link Emby', build_url(action='emby_login'), is_folder=False,
                 art=root_art('settings'), info={'title': 'Link Emby'})
        return end_dir(content='files', cache=False)
    try:
        server = _emby_server()
        # v3.9.232: Emby had NO continue-watching row at all while Plex has had
        # one all along. Emby's /Users/{id}/Items/Resume is the exact equivalent
        # of Plex's On Deck.
        add_item('Continue Watching • Emby',
                 build_url(action='emby_continue'), art=root_art('continue'),
                 info={'title': 'Continue Watching',
                       'plot': 'Pick up where you left off on Emby.'})
        for library in emby_client.libraries(server):
            _lkey = library.get('key') or ''
            _ltitle = library.get('title') or 'Library'
            _ltype = library.get('type') or ''
            _sorts = [("\u0622\u062e\u0631 \u0625\u0636\u0627\u0641\u0629", 'DateCreated:desc'),
                      ('Last Release', 'PremiereDate:desc'),
                      ('Rating', 'CommunityRating:desc'),
                      ("\u0627\u0644\u0627\u0633\u0645", 'SortName'),
                      ('Year', 'ProductionYear:desc')]
            # The sort is SAVED now (emby_sort persists it), so the tile itself
            # reopens in the chosen order instead of snapping back to SortName.
            _saved = sort_prefs.get_sort('emby', 'emby', _lkey, '')
            _ctx = [(tr('Sort: %s%s') % (('● ' if _key == _saved else ''), _label),
                     'RunPlugin(%s)' % build_url(
                         action='emby_sort', key=_lkey, title=_ltitle,
                         library_type=_ltype, current=_saved))
                    for _label, _key in _sorts]
            _saved_label = next((l for l, k in _sorts if k == _saved), '')
            add_item(_ltitle,
                     build_url(action='emby_library', key=_lkey, title=_ltitle,
                               library_type=_ltype, sort=_saved),
                     art=root_art('emby'), context_menu=_ctx,
                     info={'title': _ltitle,
                           'plot': (tr('Sorted by: %s') % _saved_label) if _saved_label else ''})
    except Exception as exc:
        _emby_error(exc)
    add_item('[COLOR grey]Disconnect Emby[/COLOR]', build_url(action='emby_logout'),
             is_folder=False, art=root_art('settings'))
    end_dir(content='files', cache=False)


_EMBY_SORTS = [
    ('SortName', "\u0627\u0644\u0627\u0633\u0645"),
    ('DateCreated:desc', 'Newest added'),
    ('PremiereDate:desc', 'Newest released'),
    ('ProductionYear:desc', 'Year'),
    ('CommunityRating:desc', 'Rating'),
]


def _emby_sort_title(value):
    return next((label for key, label in _EMBY_SORTS if key == (value or 'SortName')), "\u0627\u0644\u0627\u0633\u0645")


def emby_sort(key, title='', library_type='', current=''):
    """Pick a sort for an Emby library AND remember it.

    v3.9.232: the choice used to live only in the Container.Update URL, so it
    was forgotten as soon as the user left the library.  It is now stored per
    library, and the active entry is marked in the dialog.
    """
    # The store is authoritative: `current` is baked into the context-menu URL
    # when the PARENT list is rendered, so it goes stale as soon as the sort
    # changes without leaving that list.
    saved = sort_prefs.get_sort('emby', 'emby', key, '') or current or 'SortName'
    labels = [(('[COLOR limegreen]● %s[/COLOR]' % label) if _key == saved else label)
              for _key, label in _EMBY_SORTS]
    choice = xbmcgui.Dialog().select(tr('Emby sort'), labels)
    if choice < 0:
        return
    chosen = _EMBY_SORTS[choice][0]
    sort_prefs.set_sort('emby', 'emby', key, chosen)
    url = build_url(action='emby_library', key=key, title=title,
                    library_type=library_type, sort=chosen, start='0')
    xbmc.executebuiltin('Container.Update(%s,replace)' % url)


def emby_library(key, title='', library_type='', start='0', sort=''):
    # Explicit ?sort= wins; otherwise reopen with the remembered choice instead
    # of silently snapping back to SortName.
    if not sort:
        sort = sort_prefs.get_sort('emby', 'emby', key, '')
    sort = sort or 'SortName'
    try:
        server = _emby_server()
        # Top-level libraries are flattened recursively. Movie libraries return
        # only Movie rows; TV libraries return only Series rows. This removes
        # the filesystem/collection folders that Emby exposes as children.
        include_types = 'Series' if library_type == 'show' else 'Movie'
        rows, total = emby_client.children(
            server, key, start=int(start or 0), sort=sort,
            include_types=include_types, recursive=True)
        # v3.9.225: the sort control no longer eats the first slot of every
        # library. It lives where Plex's already does — long-press the library.
        _emby_render_items(rows)
        nxt = int(start or 0) + len(rows)
        if rows and total > nxt:
            add_item('More', build_url(action='emby_library', key=key, title=title,
                                          library_type=library_type, sort=sort,
                                          start=str(nxt)),
                     art=root_art('emby'), info={'title': 'More'})
    except Exception as exc:
        _emby_error(exc)
    end_dir(content='tvshows' if library_type == 'show' else 'movies', cache=False)


def emby_children(key, title='', start='0'):
    try:
        server = _emby_server()
        rows, total = emby_client.children(server, key, start=int(start or 0))
        _emby_render_items(rows)
        nxt = int(start or 0) + len(rows)
        if rows and total > nxt:
            add_item('More', build_url(action='emby_children', key=key, title=title,
                                          start=str(nxt)),
                     art=root_art('emby'), info={'title': 'More'})
    except Exception as exc:
        _emby_error(exc)
    end_dir(content='episodes', cache=False)


def emby_play(item_id):
    try:
        server = _emby_server()
        item = emby_client.metadata(server, item_id)
    except Exception as exc:
        return _emby_error(exc)
    versions = list(item.get('versions') or [])
    source_id = ''
    selected_version = {}
    if len(versions) > 1:
        poster = emby_client.artwork_url(server, item.get('thumb') or '')
        try:
            rows = []
            for i, version in enumerate(versions):
                li = xbmcgui.ListItem(item.get('raw_title') or item.get('title') or 'Emby')
                try:
                    li.setLabel2(version.get('version_label') or 'Version %d' % (i + 1))
                    if poster:
                        li.setArt({'icon': poster, 'thumb': poster, 'poster': poster})
                except Exception:
                    pass
                rows.append(li)
            choice = xbmcgui.Dialog().select(tr('Choose version'), rows, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(
                tr('Choose version'), [v.get('version_label') or '?' for v in versions])
        if choice < 0:
            return
        selected_version = versions[choice]
        source_id = selected_version.get('media_source_id') or ''
    elif versions:
        selected_version = versions[0]
        source_id = selected_version.get('media_source_id') or ''
    try:
        resolved = emby_client.resolve_playback(server, item_id, source_id)
        stream_url = resolved.get('url') or ''
        selected_version = resolved.get('version') or selected_version
        source_id = resolved.get('media_source_id') or source_id
    except Exception as exc:
        return _emby_error(exc)
    _ids = item.get('ids') or {}
    ctx = {
        'media_type': 'series' if item.get('media_type') == 'episode' else 'movie',
        'canonical_id': _ids.get('imdb_id') or ('tmdb:%s' % _ids.get('tmdb_id') if _ids.get('tmdb_id') else 'emby:%s' % item_id),
        'video_id': str(item_id),
        'title': item.get('raw_title') or item.get('title') or 'Emby',
        'show_title': item.get('show_title') or '',
        'stream_url': stream_url,
        'provider_id': 'emby_native',
        'provider_name': 'Emby Native • %s' % (server.get('name') or 'Server'),
        'server_type': 'emby',
        'server_url': server.get('url') or '',
        'token': server.get('token') or '',
        'item_id': str(item_id),
        'device_id': emby_client._device_id(),
        'session_id': resolved.get('play_session_id') or '',
        'native_playback_resolved': True,
        'poster': emby_client.artwork_url(server, item.get('thumb') or ''),
        'background': emby_client.artwork_url(server, item.get('art') or item.get('thumb') or '', kind='Backdrop'),
        'duration_ms': item.get('duration_ms') or 0,
        'duration': int((item.get('duration_ms') or 0) / 1000),
        'season': item.get('season') or None,
        'episode': item.get('index') or None,
        'imdb_id': _normalize_imdb_id(_ids.get('imdb_id')) or '',
        'tmdb_id': _ids.get('tmdb_id') or '',
        'tvdb_id': _ids.get('tvdb_id') or '',
        'subtitles': list(selected_version.get('subtitles') or []),
    }
    ctx['stream_key'] = cache_store.put('stream', {
        'stream_url': stream_url,
        'name': item.get('title') or 'Emby',
        'provider_name_raw': 'Emby • %s' % (server.get('name') or ''),
        'size_label': item.get('size_label') or '',
        'subtitles': list(selected_version.get('subtitles') or []),
    })
    return _play_with_context(ctx, stream_key=ctx['stream_key'], use_resolved_url=False)



