def _kodi_header_string(headers):
    """Return Kodi's URL header suffix from a dict/list of HTTP headers."""
    if not headers:
        return ''
    pairs = []
    try:
        if isinstance(headers, dict):
            iterable = headers.items()
        elif isinstance(headers, (list, tuple)):
            iterable = headers
        else:
            iterable = []
        for key, value in iterable:
            key = str(key or '').strip()
            if not key or value in (None, ''):
                continue
            pairs.append((key, str(value)))
    except Exception:
        pairs = []
    if not pairs:
        return ''
    try:
        return urlencode(pairs)
    except Exception:
        return '&'.join('%s=%s' % (quote_plus(k), quote_plus(v)) for k, v in pairs)


def _stream_row_request_headers(row):
    """Extract request headers from Stremio stream rows.

    Stremio aggregators-style addons can attach headers either at the top
    level (`requestHeaders`) or under `behaviorHints.proxyHeaders.request`.
    Kodi needs those encoded after a `|` suffix on the playable URL.
    """
    if not isinstance(row, dict):
        return {}
    out = {}

    def _merge(value):
        if not value:
            return
        try:
            if isinstance(value, dict):
                iterator = value.items()
            elif isinstance(value, (list, tuple)):
                iterator = value
            else:
                return
            for k, v in iterator:
                k = str(k or '').strip()
                if k and v not in (None, ''):
                    out[k] = str(v)
        except Exception:
            pass

    _merge(row.get('requestHeaders'))
    _merge(row.get('headers'))
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict):
        _merge(hints.get('requestHeaders'))
        proxy_headers = hints.get('proxyHeaders') or {}
        if isinstance(proxy_headers, dict):
            _merge(proxy_headers.get('request'))
            # Some implementations put the request headers directly under
            # proxyHeaders instead of nesting them under "request".
            if not any(k in proxy_headers for k in ('request', 'response')):
                _merge(proxy_headers)
    return out


def _apply_kodi_request_headers(url, row):
    url = str(url or '').strip()
    if not url:
        return ''
    # Plugin URLs should receive their own query params, not Kodi pipe headers.
    if url.lower().startswith('plugin://'):
        return url
    headers = _stream_row_request_headers(row)
    suffix = _kodi_header_string(headers)
    if not suffix:
        return url
    if '|' in url:
        base, existing = url.split('|', 1)
        if existing:
            return base + '|' + existing + '&' + suffix
        return base + '|' + suffix
    return url + '|' + suffix


def _torrent_handoff_url(magnet):
    """Return a Kodi plugin handoff URL for a magnet when a torrent player exists."""
    magnet = str(magnet or '').strip()
    if not magnet:
        return ''
    # Elementum is the most common Kodi torrent player and understands the
    # Stremio-style magnet handoff reliably. Quasar uses a compatible route.
    for addon_id, template in (
        ('plugin.video.elementum', 'plugin://plugin.video.elementum/play?uri=%s'),
        ('plugin.video.quasar', 'plugin://plugin.video.quasar/play?uri=%s'),
        # Torrest route support varies by build, but this is harmless when
        # installed and gives users another local torrent player option.
        ('plugin.video.torrest', 'plugin://plugin.video.torrest/play_magnet?magnet=%s'),
    ):
        try:
            xbmcaddon.Addon(addon_id)
            return template % quote_plus(magnet)
        except Exception:
            continue
    # Kodi cannot natively resolve magnets, but returning the magnet keeps the
    # source visible and lets any external/magnet handler attempt playback.
    return magnet


def _magnet_from_stream_row(row):
    if not isinstance(row, dict):
        return ''
    raw_url = str(row.get('url') or '').strip()
    if raw_url.lower().startswith('magnet:'):
        return raw_url
    hints = row.get('behaviorHints') or {}
    if not isinstance(hints, dict):
        hints = {}
    info_hash = (
        row.get('infoHash') or row.get('infohash') or row.get('btih') or
        hints.get('infoHash') or hints.get('infohash') or hints.get('btih') or ''
    )
    info_hash = re.sub(r'[^A-Fa-f0-9]', '', str(info_hash or '')).strip()
    if len(info_hash) not in (32, 40):
        return ''
    name = (
        row.get('title') or row.get('name') or row.get('filename') or
        hints.get('filename') or hints.get('title') or hints.get('name') or
        'NuvioHub torrent'
    )
    trackers = []
    for value in (row.get('sources') or hints.get('sources') or []):
        text = str(value or '').strip()
        if not text:
            continue
        if text.lower().startswith(('tracker:', 'dht:', 'udp://', 'http://', 'https://')):
            text = re.sub(r'^(tracker:|dht:)', '', text, flags=re.I).strip()
            if text.lower().startswith(('udp://', 'http://', 'https://')):
                trackers.append(text)
    magnet = 'magnet:?xt=urn:btih:%s&dn=%s' % (info_hash, quote_plus(str(name or 'NuvioHub torrent')))
    for tr_url in trackers[:30]:
        magnet += '&tr=%s' % quote_plus(tr_url)
    try:
        file_idx = row.get('fileIdx') if row.get('fileIdx') not in (None, '') else row.get('fileIndex')
        if file_idx in (None, ''):
            file_idx = hints.get('fileIdx') if hints.get('fileIdx') not in (None, '') else hints.get('fileIndex')
        if file_idx not in (None, ''):
            # Stremio/Torrentio fileIdx is 0-based. Elementum accepts `so` as
            # the selected file index in the magnet query.
            magnet += '&so=%s' % quote_plus(str(file_idx))
    except Exception:
        pass
    return magnet


def _stream_play_url_from_row(row):
    """Normalize a Stremio stream row into something Kodi can play.

    Important: do NOT use `externalUrl` as a fallback playable URL. In the
    Stremio stream schema it is usually an external webpage/intent, while
    `url` is the direct playable stream and `infoHash`/`fileIdx` is the torrent
    stream shape. Treating externalUrl as video is why Torrentio/AIOStreams
    rows could appear in Nuvio Hub but fail at playback.
    """
    if not isinstance(row, dict):
        return ''
    url = str(row.get('url') or '').strip()
    if url.lower().startswith('magnet:'):
        return _torrent_handoff_url(url)
    if url:
        return _apply_kodi_request_headers(url, row)
    magnet = _magnet_from_stream_row(row)
    if magnet:
        return _torrent_handoff_url(magnet)
    # Some Stremio/Nuvio-compatible addons return playable resolver links only
    # in externalUrl. Keep direct media, plugin, and manifest-resolver URLs;
    # reject ordinary webpages/configuration links.
    external = str(row.get('externalUrl') or '').strip()
    low = external.lower()
    if low.startswith(('plugin://', 'magnet:')):
        return _torrent_handoff_url(external) if low.startswith('magnet:') else external
    if low.startswith(('http://', 'https://')):
        path = low.split('?', 1)[0]
        media_exts = ('.m3u8', '.mp4', '.mkv', '.webm', '.ts', '.avi', '.mov', '.mpd')
        resolver_markers = ('/stream/', '/play/', '/resolve/', '/redirect/', 'video=', 'url=')
        blocked = ('/configure', '/settings', '/install', '/manifest.json')
        if not any(x in low for x in blocked) and (path.endswith(media_exts) or any(x in low for x in resolver_markers)):
            return _apply_kodi_request_headers(external, row)
    return ''


def _torrent_play_url_from_stream_row(row):
    # Backward-compatible wrapper for older calls in this file.
    magnet = _magnet_from_stream_row(row)
    return _torrent_handoff_url(magnet) if magnet else ''


def _stream_dedupe_signature(stream_url, display_name, size_label, quality, provider_name):
    """Build a normalized signature for a stream entry used to dedupe
    against entries already in the results list. The signature collapses
    case, whitespace, and known noise tokens so that two streams that
    are textually identical from the user's perspective compare equal.

    AIOStreams in particular is known to return the same logical stream
    multiple times because it internally aggregates several addons whose
    catalogs all point to the same upstream release. Without dedupe,
    the source window shows six rows of "ARKYN PR 4K" instead of one.
    """
    import re as _re
    name = (display_name or '').strip().lower()
    # Collapse any run of whitespace, dots, dashes, underscores, brackets
    # into a single space so "From.S01E01.WEB-DL" matches "From S01E01 WEB DL".
    name = _re.sub(r'[\s\._\-\[\]\(\){}|]+', ' ', name).strip()
    size = (size_label or '').strip().lower().replace(' ', '')
    qual = (quality or '').strip().lower()
    return '|'.join([name, size, qual, str(provider_name or '').strip().lower()])


def _append_stream_entries_from_data(entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids, title='', video_id=None, season=None, episode=None, show_title='', resume_seconds=0.0, resume_percent=0.0):
    provider_name = provider.get('name') or 'Provider'
    _provider_safe_origin = _provider_origin(provider)
    _provider_identity_art = provider_art(
        provider_name,
        provider.get('manifest') or {},
        provider.get('base_url') or provider.get('manifest_url') or '',
    )
    _provider_icon = (_provider_identity_art.get('icon') or
                      _provider_identity_art.get('thumb') or media_path('provider.png'))
    raw_streams = (data or {}).get('streams') or []
    # Be liberal with non-standard addons that return a single stream object
    # instead of a list. More importantly, never turn a multi-version response
    # into a provider-level singleton.
    if isinstance(raw_streams, dict):
        raw_streams = [raw_streams]
    elif not isinstance(raw_streams, (list, tuple)):
        raw_streams = []
    try:
        xbmc.log('[NuvioHub] Stremio raw streams: provider=%s request=%s rows=%d' % (
            provider_name, request_id, len(raw_streams)), xbmc.LOGINFO)
    except Exception:
        pass
    _before_provider_rows = len(entries)
    _dropped_no_url = 0
    for row in raw_streams:
        stream_url = _stream_play_url_from_row(row)
        if not stream_url:
            # v3.9.262: a row with no url/magnet/infoHash is unplayable and is
            # skipped — but count and LOG it, so "addon returned 3, Nuvio Hub shows 1"
            # can be diagnosed from kodi.log instead of guessed at.
            _dropped_no_url += 1
            # v4.7.5: this fired 486 times in ONE session of the user's log.
            # Per-row detail is a DEBUG concern and the per-provider summary
            # below keeps the diagnostic value at INFO; on ARM boxes the write
            # volume itself costs frame time during a source scan.
            try:
                if _dropped_no_url <= 3:
                    xbmc.log('[NuvioHub] Stremio row dropped (no playable url): provider=%s name=%r external=%r keys=%s' % (
                        provider_name, (row.get('name') or row.get('title') or '')[:60],
                        str(row.get('externalUrl') or '')[:180], sorted(list(row.keys()))[:12]), xbmc.LOGDEBUG)
            except Exception:
                pass
            continue
        facts = _stream_facts(
            row, provider_name, provider_origin=_provider_safe_origin)
        label, label2, plot = _stream_label(
            row, provider_name, facts=facts)
        display_name = facts['display_name']
        size = facts['size']
        video_bits = facts['video_bits']
        audio_bits = facts['audio_bits']
        quality, highlight = _quality_badge(video_bits)
        # Do not collapse exact URLs or matching name/size fingerprints.
        # The user explicitly wants every row from every addon/server.
        _kodi_info = _stream_meta_info_payload(
            best_meta, media_type=media_type,
            title=(title or best_meta.get('name') or canonical_id),
            show_title=(show_title or best_meta.get('name') or canonical_id),
            season=season, episode=episode,
        )
        _studio_prop = _kodi_info.get('studio') or ''
        _genre_prop = _kodi_info.get('genre') or ''
        if isinstance(_studio_prop, (list, tuple)):
            _studio_prop = ' / '.join([str(x) for x in _studio_prop if x])
        if isinstance(_genre_prop, (list, tuple)):
            _genre_prop = ' / '.join([str(x) for x in _genre_prop if x])
        payload = {
            'media_type': media_type,
            'canonical_id': canonical_id,
            'video_id': video_id or request_id,
            'provider_name': provider_name,
            'provider_id': provider.get('id') or '',
            'source_addon': facts.get('addon') or provider_name,
            'source_indexer': facts.get('indexer') or '',
            'source_service': facts.get('service') or '',
            'source_origin': facts.get('origin_line') or provider_name,
            'provider_origin': _provider_safe_origin,
            'provider_domain': facts.get('provider_domain') or '',
            'addon_url': facts.get('addon_url') or '',
            'addon_domain': facts.get('addon_domain') or '',
            'title': title or best_meta.get('name') or canonical_id,
            'show_title': show_title or best_meta.get('name') or canonical_id,
            'year': (_meta_info(best_meta).get('year') or 0),
            'stream_url': stream_url,
            'poster': art.get('poster') or '',
            'background': bg,
            'clearlogo': art.get('clearlogo') or '',
            'tmdb_id': ids.get('tmdb_id') or '',
            'imdb_id': ids.get('imdb_id') or '',
            'tvdb_id': ids.get('tvdb_id') or '',
            'external_ids': ids,
            'kodi_info': _kodi_info,
            'plot': _kodi_info.get('plot') or best_meta.get('description') or best_meta.get('overview') or '',
            'genre': _genre_prop,
            'studio': _studio_prop,
            'rating': _kodi_info.get('rating') or best_meta.get('imdbRating') or '',
            'premiered': _kodi_info.get('premiered') or '',
            'duration': _kodi_info.get('duration') or '',
            'cast': _kodi_info.get('cast') or [],
            'subtitles': row.get('subtitles') or [],
            'behaviorHints': row.get('behaviorHints') or {},
            'provider_base_url': provider.get('base_url') or '',
            'duration_ms': int((((row.get('behaviorHints') or {}).get('plexDuration') or (row.get('behaviorHints') or {}).get('durationMs') or 0)) or 0),
            'stream_name': row.get('name') or '',
            'stream_title': row.get('title') or '',
            'stream_description': row.get('description') or '',
            'formatter_tags': [],
            # v4.7.3: RAW stream text (AIOStreams formatter output with its
            # \u265b/emoji markers intact). User badges.json presets are
            # written against THIS text; the cleaned display name strips
            # the markers, so crown-gated rules could never match.
            'badge_blob_raw': ' | '.join(_collect_stream_texts(row))[:4096],
            # AIOStreams already formatted the description. source_info keeps
            # it for the details panel; duplicating it as another list property
            # only makes every row heavier and triggers a second badge scan.
            'formatter_summary': '',
            'video_bits': facts.get('video_bits') or [],
            'audio_bits': facts.get('audio_bits') or [],
            'request_headers': _stream_row_request_headers(row),
            'external_url': row.get('externalUrl') or '',
            'info_hash': (row.get('infoHash') or row.get('infohash') or ((row.get('behaviorHints') or {}) if isinstance(row.get('behaviorHints') or {}, dict) else {}).get('infoHash') or ''),
        }
        # Native Plex/Emby rows carry their direct progress and identity
        # context in behaviorHints. Copy it to the playback session so external
        # subtitle addons receive the full IDs and companion reporting does not
        # fall back to a generic Stremio row.
        _hints = row.get('behaviorHints') or {}
        if isinstance(_hints, dict) and _hints.get('nativeProvider'):
            payload['provider_id'] = '%s_native' % str(_hints.get('nativeProvider'))
            payload['server_type'] = str(_hints.get('serverType') or _hints.get('nativeProvider') or '')
            payload['server_url'] = str(_hints.get('serverUrl') or '')
            payload['server_id'] = str(_hints.get('serverId') or '')
            payload['token'] = str(_hints.get('token') or '')
            payload['rating_key'] = str(_hints.get('ratingKey') or '')
            payload['item_id'] = str(_hints.get('itemId') or '')
            payload['media_source_id'] = str(_hints.get('mediaSourceId') or '')
            payload['part_key'] = str(_hints.get('partKey') or '')
            payload['duration_ms'] = int(_hints.get('durationMs') or payload.get('duration_ms') or 0)
            payload['imdb_id'] = _normalize_imdb_id(_hints.get('imdbId') or payload.get('imdb_id')) or payload.get('imdb_id') or ''
            payload['tmdb_id'] = str(_hints.get('tmdbId') or payload.get('tmdb_id') or '')
            payload['tvdb_id'] = str(_hints.get('tvdbId') or payload.get('tvdb_id') or '')
            payload['external_ids'] = {
                'imdb_id': payload.get('imdb_id') or '',
                'tmdb_id': payload.get('tmdb_id') or '',
                'tvdb_id': payload.get('tvdb_id') or '',
            }

        if season is not None:
            payload['season'] = int(season)
        if episode is not None:
            payload['episode'] = int(episode)
        try:
            rs = float(resume_seconds or 0.0)
        except Exception:
            rs = 0.0
        if rs > 1.0:
            payload['resume_seconds'] = rs
        try:
            rp = float(resume_percent or 0.0)
        except Exception:
            rp = 0.0
        if rp > 1.0 and rp < 95.0:
            payload['resume_percent'] = rp
        cache_key = cache_store.put('stream', payload)
        _row_tags = facts.get('tags') or {}
        _stype, _stype_label, _stype_color = facts.get('source_type') or (
            ('direct',) + _SOURCE_TYPE_STYLES['direct'])
        entries.append({
            'stream_key': cache_key,
            # --- nuviohub-406-patch --- identity for same-provider collapsing
            'stream_url': stream_url,
            # v4.1.0: source-type chip (usenet/debrid/torrent/direct/server)
            'source_type': _stype,
            'source_type_label': _stype_label,
            'source_type_color': _stype_color,
            'name': display_name,
            'label2': label2,
            'count': '00.',
            'quality': quality,
            'highlight': highlight,
            'provider': facts.get('provider_badge') or _provider_badge(
                row, provider_name, text_blob=facts.get('_raw_blob') or ''),
            'provider_name_raw': provider_name,
            'provider_icon': _provider_icon,
            'addon': facts.get('addon') or provider_name,
            'provider_domain': facts.get('provider_domain') or '',
            'provider_url': _provider_safe_origin,
            'addon_url': facts.get('addon_url') or '',
            'addon_domain': facts.get('addon_domain') or '',
            'source_site': facts['site'],
            'indexer': facts.get('indexer') or '',
            'service_name': facts.get('service') or '',
            'origin_line': facts.get('origin_line') or provider_name,
            'size_label': size or '--',
            'extraInfo': ' | '.join(video_bits[:8]) if video_bits else '--',
            'extraInfo2': ' | '.join(audio_bits[:8]) if audio_bits else '--',
            'badges': _stream_badges(video_bits, audio_bits, row.get('subtitles') or []),
            'source_info': _source_info_text(
                row, provider_name, facts=facts,
                provider_origin=_provider_safe_origin) + '\n\n' + plot,
            # v3.9.198: identity fields for the AIOStreams-style deduplicator.
            'filename': str((row.get('behaviorHints') or {}).get('filename') or ''),
            'info_hash': str(row.get('infoHash') or row.get('infohash') or
                             (row.get('behaviorHints') or {}).get('infoHash') or ''),
            'file_idx': (row.get('fileIdx') if row.get('fileIdx') is not None
                         else (row.get('behaviorHints') or {}).get('fileIdx')) or 0,
            'size_bytes': _extract_size(
                (row.get('behaviorHints') or {}).get('videoSize'),
                row.get('size'), row.get('sizebytes')) or 0,
            'video_codec': facts.get('codec') or '',
            'audio': facts.get('audio') or '',
            'hdr': facts.get('hdr') or '',
            # v3.9.199: the AIOStreams-grade fact set, parsed from the raw title.
            'tags': _row_tags,
            'languages': _row_tags.get('languages') or [],
            'tag_line': stream_tag_line(_row_tags,
                                        size_label=facts.get('size') or '',
                                        provider=facts.get('addon') or provider_name),
        })
        try:
            _publish_last_streams_index(canonical_id, season, episode, entries, poster=art.get('poster') or '')
        except Exception:
            pass
    try:
        xbmc.log('[NuvioHub] Stremio appended streams: provider=%s raw=%d kept=%d dropped_no_url=%d' % (
            provider_name, len(raw_streams), len(entries) - _before_provider_rows, _dropped_no_url), xbmc.LOGINFO)
    except Exception:
        pass


def _provider_stats_line(entries, max_names=4):
    """Fen Light-style provider tally: "AIOStreams: 12 | Torrentio: 8".

    Gives instant confidence in the scan and makes a silent provider
    (0 rows) visible at a glance instead of needing kodi.log.
    """
    try:
        counts = {}
        for e in entries or []:
            name = str(e.get('provider_name_raw') or e.get('addon') or '?').strip()
            # Collapse "Plex • Server" style to the head token for brevity.
            head = name.split(' \u2022 ')[0].strip() or '?'
            counts[head] = counts.get(head, 0) + 1
        if not counts:
            return ''
        ranked = sorted(counts.items(), key=lambda kv: -kv[1])
        parts = ['%s: %d' % (n, c) for n, c in ranked[:max_names]]
        extra = len(ranked) - max_names
        if extra > 0:
            parts.append('+%d' % extra)
        return ' | '.join(parts)
    except Exception:
        return ''

def _stream_initial_target_count():
    """How many providers to wait for before opening the source window.

    Small by design so the window appears quickly, while slower providers
    keep filling in live behind the scenes.
    """
    try:
        workers = max(2, int(float(ADDON.getSetting('parallel_workers') or '8')))
    except Exception:
        workers = 8
    return max(1, min(3, workers // 3 or 1))


def _provider_signature_text(provider):
    manifest = (provider or {}).get('manifest') or {}
    return ' '.join([
        str((provider or {}).get('name') or ''),
        str((provider or {}).get('base_url') or ''),
        str((provider or {}).get('manifest_url') or ''),
        str((provider or {}).get('id') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()


def _stream_timeout_for_provider(provider):
    """Return a bounded timeout for a normal Stremio addon.

    Every installed manifest follows the same provider path. Aggregators such
    as AIOStreams are no longer called through a private/direct API. Their
    configured manifest URL is queried exactly like any other Stremio addon.
    """
    sig = _provider_signature_text(provider)
    try:
        base = int(float(ADDON.getSetting('timeout') or '20'))
    except Exception:
        base = 20
    if any(token in sig for token in ('torrentio', 'comet', 'mediafusion', 'stremthru', 'aiostream')):
        return max(10, min(max(base, 10), 25))
    return fast_timeout('stream')


def _setting_bool(name, default=False):
    try:
        raw = (ADDON.getSetting(name) or ('true' if default else 'false')).strip().lower()
    except Exception:
        raw = 'true' if default else 'false'
    return raw in ('true', '1', 'yes', 'on')


def _server_client(backend):
    return plex_client if backend == 'plex' else emby_client


def _server_stream_rows(backend, server, ids, media_type, titles,
                        season=None, episode=None):
    "ONE lookup for both servers: ID first, titles only as a fallback.\n\n    v3.9.218 — the unified path the user asked for.\n\n    Emby worked because it was asked by ID (AnyProviderIdEquals). Plex was\n    asked by TITLE — and an Arabic title can never match an English library,\n    let alone the literal string \"\u0627\u0644\u062d\u0644\u0642\u0629 16\". Both servers now take the same\n    route through the same code:\n\n        1. every ID we hold (imdb / tmdb / tvdb) -> find_all_by_ids\n        2. only if that finds nothing, the title variants\n        3. every hit is verified against the IDs before it is trusted\n\n    Whatever comes back is a normal Nuvio Hub source row, so the servers ARE\n    sources — ranked, badged, switchable and resumable like any other.\n    "
    client = _server_client(backend)
    identity = MediaIdentity(media_type=media_type, ids=ids, title=(titles or [''])[0],
                             titles=titles, season=season, episode=episode)
    ids = identity.ids
    series = identity.is_episode
    kind = identity.media_type

    # v3.9.225: the server step gets its OWN budget. It used to run inside the
    # shared source scan with no ceiling of its own, so a slow Plex server
    # starved the Stremio addons until they timed out and were blacklisted.
    # Failure accounting is suspended for the duration: a provider must only
    # ever be penalised for its own failures.
    _budget = _get_int_setting('server_lookup_seconds', 7, minimum=4, maximum=60)
    _deadline = time.time() + float(_budget)
    try:
        from .nuviohub.client import provider_health_pause
        provider_health_pause(_budget + 2)
    except Exception:
        pass

    matches, seen = [], set()

    def _take(rows):
        for row in (rows or []):
            key = str(row.get('rating_key') or '')
            if key and key not in seen:
                seen.add(key)
                matches.append(row)

    # 1) BY ID — the only lookup that survives a translated library
    try:
        _take(client.find_all_by_ids(server, ids, media_type=kind, title='', limit=24))
    except Exception as exc:
        xbmc.log('[NuvioHub] %s id lookup failed: %s' % (backend, exc), xbmc.LOGWARNING)

    # 2) BY TITLE — only if the ids found nothing (or the item has none)
    if not matches and time.time() < _deadline:
        for title in (titles or []):
            if not str(title or '').strip():
                continue
            if time.time() >= _deadline:
                xbmc.log('[NuvioHub] %s lookup: budget spent — stopping so the '
                         'Stremio providers keep their time' % backend, xbmc.LOGINFO)
                break
            try:
                _take(client.find_all_by_ids(server, ids, media_type=kind,
                                             title=title, limit=24))
            except Exception:
                continue
            # v3.9.222: do NOT stop at the first title that hits. A library
            # routinely holds the same film twice — once under its Arabic name
            # and once under its English one — and each copy is a real source.

    xbmc.log('[NuvioHub] %s lookup: server=%s ids=%s titles=%d -> %d item(s)'
             % (backend, server.get('name') or '?',
                ','.join('%s=%s' % (k, v) for k, v in sorted((ids or {}).items()) if v) or 'none',
                len(titles or []), len(matches)), xbmc.LOGINFO)
    if not matches:
        return []

    # 3) walk to the exact episode when needed
    items = []
    for match in matches:
        if series:
            try:
                row = client.episode_item(server, match, season, episode)
            except Exception:
                row = None
            if not row:
                continue
            try:
                items.append(client.metadata(server, row.get('rating_key')))
            except Exception:
                items.append(row)
        else:
            items.append(match)
    return items


def _emby_stream_payload(provider, media_type):
    """Emby versions as normal Nuvio Hub source rows (id-matched, EmbyCon-grade).

    Every MediaSource becomes a stream carrying its real file size, so ranking,
    badges, the switch-source index and resume all work with no special cases.
    """
    server = provider.get('_server') or {}
    title = provider.get('_title') or ''
    ids = provider.get('_ids') or {}
    season, episode = provider.get('_season'), provider.get('_episode')
    if not (ids.get('imdb_id') or ids.get('tmdb_id') or title):
        return {}
    series = _is_series_media(media_type) and season and episode
    matches = emby_client.find_all_by_ids(
        server, ids, media_type='series' if series else 'movie', title=title)
    if not matches:
        return {}
    items = []
    for match in matches:
        if series:
            episode_row = emby_client.episode_item(server, match, season, episode)
            if not episode_row:
                continue
            try:
                items.append(emby_client.metadata(server, episode_row.get('rating_key')))
            except Exception:
                items.append(episode_row)
        else:
            items.append(match)
    if not items:
        return {}
    server_name = server.get('name') or 'Emby'
    streams = []
    for item in items:
      for version in (item.get('versions') or []):
        url = emby_client.playback_url(server, item.get('rating_key'),
                                       version.get('media_source_id') or '')
        fname = os.path.basename(version.get('file') or '') or (item.get('raw_title') or title)
        facts = ' '.join(x for x in (version.get('resolution'), version.get('hdr'),
                                     version.get('video_codec'), version.get('audio'),
                                     version.get('size_label')) if x)
        streams.append({
            'name': '[COLOR %s]EMBY NATIVE[/COLOR]\n%s' % (EMBY_COLOR, server_name),
            'title': '%s\n%s' % (fname, facts),
            'url': url,
            'subtitles': list(version.get('subtitles') or []),
            'behaviorHints': {
                'filename': fname,
                'videoSize': version.get('size_bytes') or 0,
                'nativeProvider': 'emby',
                'serverType': 'emby',
                'serverUrl': server.get('url') or '',
                'token': server.get('token') or '',
                'itemId': str(item.get('rating_key') or ''),
                'mediaSourceId': str(version.get('media_source_id') or ''),
                'imdbId': _normalize_imdb_id((item.get('ids') or {}).get('imdb_id')) or '',
                'tmdbId': str((item.get('ids') or {}).get('tmdb_id') or ''),
                'tvdbId': str((item.get('ids') or {}).get('tvdb_id') or ''),
                'durationMs': int(item.get('duration_ms') or 0),
            },
        })
    return {'streams': streams}


def _plex_stream_payload(provider, media_type):
    """Built-in Plex source step (DPlex trakttokodi-style, v3.9.172).

    GUID-matches the current item on ONE server and returns every file
    version as a Stremio-shaped stream, so Plex copies flow through the
    normal source pipeline — ranking, badges, size parsing, the switch
    index and companion progress all apply with zero special cases.
    """
    server = provider.get('_server') or {}
    title = provider.get('_title') or ''
    titles = list(provider.get('_titles') or [])
    if title and title.casefold() not in [str(x).casefold() for x in titles]:
        titles.insert(0, title)
    if not titles and title:
        titles = [title]
    ids = provider.get('_ids') or {}
    wanted_year = str(provider.get('_year') or '').strip()
    season, episode = provider.get('_season'), provider.get('_episode')
    want_imdb = str(ids.get('imdb_id') or '').lower()
    want_tmdb = str(ids.get('tmdb_id') or '')
    want_tvdb = str(ids.get('tvdb_id') or '')
    if not title and not (want_imdb or want_tmdb or want_tvdb):
        return {}

    def _ids_match(it):
        iid = it.get('ids') or {}
        return ((want_imdb and str(iid.get('imdb_id') or '').lower() == want_imdb) or
                (want_tmdb and str(iid.get('tmdb_id') or '') == want_tmdb) or
                (want_tvdb and str(iid.get('tvdb_id') or '') == want_tvdb))

    # v3.9.218: the SAME lookup Emby uses — ID first, titles only as a
    # fallback. The 90 lines this replaces searched Plex by TITLE, which is
    # why an Arabic query never matched an English library and every server
    # answered 'no match' after 14 seconds.
    target_items = _server_stream_rows(
        'plex', server, ids, media_type, titles,
        season=season, episode=episode)

    if not target_items:
        xbmc.log('[NuvioHub] Plex Native no match: server=%s title=%s ids=%s' % (
            server.get('name') or '?', title,
            ','.join('%s=%s' % (key, ids.get(key))
                     for key in ('imdb_id', 'tmdb_id', 'tvdb_id') if ids.get(key)) or 'none'),
            xbmc.LOGWARNING)
        return {}
    server_name = server.get('name') or 'Plex'
    streams = []
    for target_item in target_items:
        try:
            item = plex_client.metadata(server, target_item.get('rating_key'))
        except Exception as exc:
            xbmc.log('[NuvioHub] Plex Native metadata failed: server=%s key=%s error=%s' % (
                server_name, target_item.get('rating_key') or '?', exc), xbmc.LOGWARNING)
            continue
        for version in (item.get('versions') or []):
            if not version.get('part_key'):
                continue
            try:
                url = plex_client.playback_url(item, part_key=version['part_key'])
            except Exception:
                continue
            fname = os.path.basename(version.get('file') or '') or (item.get('raw_title') or title)
            facts = ' '.join(x for x in (version.get('resolution'), version.get('hdr'),
                                         version.get('video_codec'), version.get('audio'),
                                         version.get('size_label')) if x)
            streams.append({
                'name': '[COLOR %s]PLEX NATIVE[/COLOR]\n%s' % (PLEX_COLOR, server_name),
                'title': '%s\n%s' % (fname, facts),
                'url': url,
                'subtitles': list(version.get('subtitles') or []),
                'behaviorHints': {
                    'filename': fname,
                    'videoSize': version.get('size_bytes') or 0,
                    'nativeProvider': 'plex',
                    'serverType': 'plex',
                    'serverUrl': item.get('server_url') or server.get('url') or '',
                    'serverId': str(server.get('id') or ''),
                    'token': item.get('token') or server.get('token') or '',
                    'ratingKey': str(item.get('rating_key') or target_item.get('rating_key') or ''),
                    'partKey': str(version.get('part_key') or ''),
                    'imdbId': _normalize_imdb_id((item.get('ids') or {}).get('imdb_id')) or '',
                    'tmdbId': str((item.get('ids') or {}).get('tmdb_id') or ''),
                    'tvdbId': str((item.get('ids') or {}).get('tvdb_id') or ''),
                    'durationMs': int(item.get('duration_ms') or 0),
                },
            })
    return {'streams': streams}


def _fetch_stream_payload(target, media_type):
    """Fetch one source payload and feed the local adaptive scheduler.

    The scheduler stores only latency/success counters; no media ids, URLs,
    credentials or viewing data are persisted.
    """
    provider, request_id = target
    started = time.monotonic()
    payload = {}
    failed = False
    try:
        if (provider or {}).get('id') in ('__plex__', '__emby__'):
            backend = 'plex' if (provider or {}).get('id') == '__plex__' else 'emby'
            server = (provider or {}).get('_server') or {}
            if not _server_health.should_query(backend, server):
                xbmc.log('[NuvioHub] %s server temporarily skipped by health router: %s' % (
                    backend, server.get('name') or '?'), xbmc.LOGINFO)
                return {}
            native_started = time.monotonic()
            try:
                payload = (_plex_stream_payload(provider, media_type) if backend == 'plex'
                           else _emby_stream_payload(provider, media_type))
                native_count = len((payload or {}).get('streams') or [])
                _server_health.record_result(backend, server,
                    time.monotonic() - native_started, True, native_count)
                xbmc.log('[NuvioHub] %s Native source result: server=%s streams=%d' % (
                    backend.capitalize(), server.get('name') or '?', native_count), xbmc.LOGINFO)
                return payload
            except Exception:
                _server_health.record_result(backend, server,
                    time.monotonic() - native_started, False, 0)
                raise
        try:
            payload = _stremio_provider.fetch(
                provider, media_type, request_id,
                timeout_override=_stream_timeout_for_provider(provider))
            return payload
        except Exception as exc:
            failed = True
            return exc
    except Exception as exc:
        failed = True
        xbmc.log('[NuvioHub] provider source error: %s' % exc, xbmc.LOGWARNING)
        return {}
    finally:
        try:
            count = len((payload or {}).get('streams') or []) if isinstance(payload, dict) else 0
            _provider_stats.record(provider, time.monotonic() - started,
                                   success=(not failed), result_count=count)
        except Exception:
            pass


def _source_parallel_workers(target_count=0):
    """Worker budget for stream-source scans.

    v3.9.87: CoreELEC boxes can hit "can't start new thread" when several
    plugin invokers, source refreshes and subtitle workers overlap. Keep source
    discovery parallel, but use a fixed 2-4 worker envelope.  Subtitle lookup
    now runs at the same time, so retaining the old six-stream-worker ceiling
    would recreate the CoreELEC thread spike through a different path.
    """
    try:
        base = int(float(ADDON.getSetting('parallel_workers') or parallel_workers() or 4))
    except Exception:
        try:
            base = int(parallel_workers() or 4)
        except Exception:
            base = 4
    workers = max(2, base)
    if target_count:
        workers = min(workers, max(1, int(target_count)))
    return max(1, min(4, workers))


def _source_quick_open_seconds():
    """How long to keep collecting after the first rows before opening UI.

    It is a short post-first-result grace; late providers continue through the
    live session refresh after the source window opens.
    """
    try:
        raw = float(ADDON.getSetting('streams_quick_open_seconds') or 0.4)
    except Exception:
        raw = 0.4
    # This is a post-first-result grace, not a minimum loading screen. The
    # settings UI allows 0.3s; honour it instead of silently clamping the
    # fast path. Providers keep filling the live source window afterwards.
    return max(0.3, min(raw, 4.0))


def _source_result_goal():
    """Unique-row threshold for the cinematic source-search screen.

    Kodi enum values are stored as zero-based indices.  A goal of ``0`` means
    patient mode: do not early-open; wait for every source (bounded by the
    existing global source timeout).
    """
    try:
        raw = str(ADDON.getSetting('streams_result_goal') or '1').strip()
        idx = int(float(raw))
    except Exception:
        idx = 1
    return {0: 10, 1: 20, 2: 40, 3: 0}.get(idx, 20)


def _source_enough_wait_seconds():
    try:
        raw = float(ADDON.getSetting('streams_enough_wait_seconds') or 8.0)
    except Exception:
        raw = 8.0
    return max(3.0, min(raw, 12.0))


def _source_progress_unique_count(entries):
    """Return the post-dedup count without ranking or rebuilding UI rows."""
    rows = list(entries or [])
    try:
        rows, _removed = _collapse_repeated_provider_rows(rows)
    except Exception:
        pass
    try:
        mode = _dedup_mode()
        if mode != 'off':
            order = (ADDON.getSetting('source_priority_order') or '')
            rows, _removed = dedupe_stream_entries(
                rows, mode=mode,
                priority=[part.strip().lower() for part in order.split(',') if part.strip()],
            )
    except Exception:
        pass
    return len(rows)


# DPlex bridge removed in v3.9.243. Plex Native is the single Plex provider.

def _collect_stream_entries(targets, media_type, canonical_id, best_meta, art, bg, ids, title='',
                            video_id='', season=None, episode=None, show_title='', resume_seconds=0.0,
                            resume_percent=0.0,
                            stop_after_first=False, show_loader=False,
                            processed_targets=None, scan_state=None):
    entries = []
    if not targets:
        return entries

    loader_title = title or show_title or best_meta.get('name') or canonical_id or tr('Add-ons')
    # v4.6.3: warm the MDBList aggregated-ratings cache in the background
    # while the providers are queried anyway. The picker's tmdbh_context
    # overlay only ever READS the warm cache (no network in its hot path) —
    # and since 4.2.2 nothing had ever warmed it, so the Letterboxd /
    # MDBList / MAL chips never rendered. Keyed by tmdb id first, exactly
    # like TMDb Helper's own MDBList lookups.
    try:
        from . import mdblist as _mdb_warm
        _mdb_warm.warm_ratings_async(
            imdb_id=(ids or {}).get('imdb_id') or '',
            media_type=media_type,
            tmdb_id=(ids or {}).get('tmdb_id') or '')
    except Exception as _silent_exc:
        log.silent('MDBLIST_WARM', _silent_exc)
    def _run(loader=None):
        # v3.9.43: hard global wall-clock ceiling. Per-provider timeouts
        # protect against any single provider hanging, but if many slow
        # providers each take the full per-provider timeout (which can
        # be 15 seconds for AIOStreams), the cumulative wait can feel
        # like a hang to the user. The ceiling forces the loop to exit
        # even if iter_parallel still has outstanding work. Twenty-five
        # seconds is generous for any realistic scan; the cancel and
        # "اكتفي بالموجود" buttons remain available throughout.
        import time as _t
        _started_at = _t.time()
        _hard_deadline = _started_at + 25.0
        _result_goal = _source_result_goal() if stop_after_first else 0
        _enough_wait = _source_enough_wait_seconds() if stop_after_first else 25.0
        _quick_grace = _source_quick_open_seconds() if stop_after_first else 0.0
        _parallel_timeout = (
            25.0 if (not stop_after_first or _result_goal == 0)
            else min(25.0, _enough_wait)
        )
        _unique_count = 0
        _source_race = start_parallel_race(
            lambda t: _fetch_stream_payload(t, media_type), targets,
            workers=_source_parallel_workers(len(targets)),
            # One race lives through both the foreground and live-refresh
            # phases, so slow aggregators are never requested twice.
            timeout=25.0, lane='streams',
        )

        for idx, (target, data) in enumerate(_iter_source_race(
                _source_race, lambda: _unique_count, lambda: bool(entries),
                _started_at, _parallel_timeout, stop_after_first,
                _result_goal, _quick_grace,
                should_stop=(loader.is_stopped if loader is not None else None),
                consume_continue=(loader.consume_continue_search if loader is not None else None),
                clear_sufficient=(loader.clear_sufficient if loader is not None else None),
                mark_sufficient=(lambda: loader.mark_sufficient(auto_seconds=0)
                                 if loader is not None else None),
            ), start=1):
            _now = _t.time()
            if _now > _hard_deadline:
                try:
                    xbmc.log('[NuvioHub] source gathering hit 25s hard ceiling — %d targets processed, %d entries gathered' % (idx, len(entries)), xbmc.LOGINFO)
                except Exception:
                    pass
                break
            provider, request_id = target
            if processed_targets is not None:
                try:
                    processed_targets.append(target)
                except Exception:
                    pass
            if loader is not None:
                # v3.9.32: respect either button. The XML now shows two:
                #   "اكتفي بالموجود" → stop scan, keep partial entries
                #   "إلغاء"            → stop scan AND drop entries (true abort)
                # is_stopped() is true for either; we differentiate after
                # the loop so the caller sees the right result list.
                if loader.is_stopped():
                    break
                loader.update(
                    provider_name=provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
                    index=idx,
                    status=tr('Searching for add-ons...'),
                    sub_status='%d %s' % (len(entries), tr('add-on')) if entries else '',
                )
            if isinstance(data, Exception) or not data:
                continue
            before = len(entries)
            _append_stream_entries_from_data(
                entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids,
                title=title, video_id=video_id, season=season, episode=episode, show_title=show_title,
                resume_seconds=resume_seconds, resume_percent=resume_percent,
            )
            if len(entries) > before:
                _unique_count = _source_progress_unique_count(entries)
            if loader is not None:
                loader.add_results(
                    len(entries) - before,
                    provider_name=provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
                    unique_total=_unique_count,
                )
        if scan_state is not None:
            scan_state['race'] = _source_race
            scan_state['pending_targets'] = _source_race.pending_items()
        if (scan_state is None or
                (loader is not None and loader.is_cancelled())):
            _source_race.cancel()
        if loader is not None:
            # v3.9.32: if the user pressed the true Cancel button (not
            # "Use what's found"), wipe the partial entries so the
            # caller treats it as an aborted search rather than showing
            # half-scanned sources the user explicitly didn't want.
            if loader.is_cancelled():
                entries[:] = []
            loader.set_finalizing()

    if show_loader:
        # v3.9.59/v3.9.60: build the subtitle for the bottom-sheet
        # layout's hero area: "2023 • Drama, Sci-Fi • S2E5".
        try:
            sub_parts = []
            _year = best_meta.get('year') or best_meta.get('releaseInfo') or ''
            if _year:
                sub_parts.append(str(_year))
            _genres = best_meta.get('genres') or best_meta.get('genre') or []
            if isinstance(_genres, list) and _genres:
                sub_parts.append(', '.join(str(g) for g in _genres[:2] if g))
            elif isinstance(_genres, str) and _genres:
                sub_parts.append(_genres)
            if season is not None and episode is not None:
                try:
                    sub_parts.append('S%dE%d' % (int(season), int(episode)))
                except Exception:
                    pass
            loader_subtitle = '  •  '.join(sub_parts)
        except Exception:
            loader_subtitle = ''

        # v3.9.89: pass the raw addon poster + IDs to the dialog and let
        # it route through art.clean_poster (same policy as the results
        # window and the player overlay). MetaHub TMDb wins when IMDb is
        # known; addon URL when it's clearly not a logo; local portrait
        # placeholder otherwise. NEVER fanart/thumb — they are landscape
        # and render as a banner stuck at the top of an empty card.
        _media_type_for_loader = (
            (best_meta or {}).get('media_type')
            or (best_meta or {}).get('type')
            or media_type
            or 'movie'
        )
        # v4.6.0: full ordered provider list for the dashboard cards.
        _loader_names = []
        for _tgt in targets:
            try:
                _prov = _tgt[0] or {}
                _nm = str(_prov.get('name')
                          or (_prov.get('manifest') or {}).get('name') or '').strip()
            except Exception:
                _nm = ''
            if _nm and _nm not in _loader_names:
                _loader_names.append(_nm)
        with SourcesLoadingDialog(
            title=loader_title,
            subtitle=loader_subtitle,
            fanart=bg or (art or {}).get('fanart') or '',
            poster=(art or {}).get('poster') or '',
            clearlogo=(art or {}).get('clearlogo') or (art or {}).get('logo') or '',
            media_type=_media_type_for_loader,
            imdb_id=(ids or {}).get('imdb_id') or '',
            tmdb_id=(ids or {}).get('tmdb_id') or '',
            provider_count=len(targets),
            provider_names=_loader_names,
        ) as loader:
            _run(loader)
    else:
        _run(None)
    return entries


_STREAM_REFRESH_SEM = threading.BoundedSemaphore(2)

def _start_stream_session_refresh(session_key, initial_entries, remaining_targets, media_type, canonical_id,
                                  best_meta, art, bg, ids, title='', video_id='', season=None,
                                  episode=None, show_title='', resume_seconds=0.0,
                                  resume_percent=0.0, scan_race=None):
    if not session_key or not remaining_targets:
        return

    def _worker():
        _acquired = False
        try:
            # Reused foreground futures already own their bounded stream lane;
            # consuming them needs no second network-refresh slot.
            if scan_race is None:
                try:
                    _acquired = _STREAM_REFRESH_SEM.acquire(timeout=1.5)
                except TypeError:
                    _acquired = _STREAM_REFRESH_SEM.acquire(False)
                if not _acquired:
                    xbmc.log('[NuvioHub] live source refresh slots busy; continuing in low-concurrency mode', xbmc.LOGINFO)
        except Exception:
            _acquired = False
        entries = list(initial_entries or [])
        version = 1
        last_request_id = str(video_id or '')
        try:
            refresh_workers = (_source_parallel_workers(len(remaining_targets))
                               if _acquired else 1)
            if scan_race is not None:
                _iterator = scan_race.iter_completed(timeout=25.0)
            else:
                _iterator = iter_parallel(
                    lambda t: _fetch_stream_payload(t, media_type),
                    remaining_targets, workers=refresh_workers, timeout=25.0,
                    lane='stream_refresh')
            for target, data in _iterator:
                try:
                    provider, request_id = target
                except Exception:
                    continue
                last_request_id = str(video_id or request_id or last_request_id or '')
                if isinstance(data, Exception) or not data:
                    continue
                before = len(entries)
                _append_stream_entries_from_data(
                    entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids,
                    title=title, video_id=video_id, season=season, episode=episode, show_title=show_title,
                    resume_seconds=resume_seconds, resume_percent=resume_percent,
                )
                if len(entries) == before:
                    continue
                fresh = list(entries[before:])
                del entries[before:]
                entries.extend(_finalize_stream_entries(fresh, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id))
                version += 1
                source_session.update(session_key, {
                    'entries': _finalize_stream_entries(list(entries), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id),
                    'done': False,
                    'version': version,
                })

        finally:
            if scan_race is not None:
                try:
                    scan_race.cancel()
                except Exception:
                    pass
            try:
                source_session.update(session_key, {
                    'entries': _finalize_stream_entries(list(entries), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id),
                    'done': True,
                    'version': version + 1,
                })
            except Exception:
                pass
            if _acquired:
                try:
                    _STREAM_REFRESH_SEM.release()
                except Exception:
                    pass

    try:
        threading.Thread(target=_worker, name='NuvioHubStreamRefresh', daemon=True).start()
    except RuntimeError as exc:
        try:
            xbmc.log('[NuvioHub] skipped background source refresh: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass
        try:
            source_session.update(session_key, {
                'entries': _finalize_stream_entries(list(initial_entries or []), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=str(video_id or '')),
                'done': True,
                'version': 2,
            })
        except Exception:
            pass


def _full_parallel_source_scan_enabled():
    """Optional patient mode: wait for all providers before opening results."""
    try:
        raw = (ADDON.getSetting('streams_full_parallel_scan') or 'false').strip().lower()
    except Exception:
        return False
    return raw in ('true', '1', 'yes', 'on')


def _is_suspect_logo_poster(url):
    """v3.9.85: detect URLs that look like addon icons/logos rather than
    real movie/TV posters. Several Stremio addons (notably some Arabic
    anime addons and small streaming providers) return their OWN logo
    as the poster when their meta record for an item lacks a real one.
    We never want such logos to show in the loading dialog, the source
    picker, or the player overlay — they look broken and identical for
    every item from that addon. The check is two-tier:

      1. Allow-list known reliable poster CDNs (TMDb, MetaHub, Fanart.tv,
         Amazon Images, Imgur). These never get filtered.
      2. Reject URLs matching common addon-icon patterns: paths ending
         in /icon.png, /logo.png, /addon.png, /favicon.*, or containing
         '/logo' or '/icon' segments.

    Returns True if the URL should be treated as a logo (and therefore
    rejected as a poster). False = the URL is fine to use as a poster.
    """
    if not url or not isinstance(url, str):
        return False
    url_low = url.lower()
    safe_hosts = (
        'image.tmdb.org', 'images.metahub.space', 'media-amazon.com',
        'm.media-amazon.com', 'img.youtube.com', 'i.imgur.com',
        'fanart.tv', 'assets.fanart.tv', 'static.metahub.space',
        'image.com', 'imgcdn', 'imageapi',
    )
    for h in safe_hosts:
        if h in url_low:
            return False
    suspect_endings = (
        '/icon.png', '/icon.jpg', '/icon.jpeg', '/icon.webp',
        '/logo.png', '/logo.jpg', '/logo.jpeg', '/logo.webp',
        '/addon.png', '/addon.jpg',
        '/favicon.png', '/favicon.ico', '/favicon.jpg',
        '/poster.png', '/poster.jpg',
        '/banner.png', '/banner.jpg',
    )
    for ending in suspect_endings:
        if url_low.endswith(ending):
            return True
    # Path-segment match — catches /icon/, /logo/, /branding/ subpaths
    for seg in ('/logo/', '/icon/', '/icons/', '/branding/', '/brand/', '/assets/icon'):
        if seg in url_low:
            return True
    return False


def _clean_poster(url, fallback='', imdb_id=''):
    """v3.9.86: poster sourcing with TMDb-first preference.

    Order of preference:
      1. TMDb/MetaHub clean URL if imdb_id is available — most reliable
         source for movie/TV posters, covers ~all titles with an IMDb
         entry, never returns addon logos. MetaHub is the same CDN
         Stremio's official Cinemeta addon uses, keyed by IMDb ID.
      2. The addon-provided URL if it passes the logo-suspect check —
         catches the case where TMDb has no entry but a niche addon
         (anime fan-database, fan-translated content, etc.) does have
         a real poster.
      3. The supplied fallback (typically the fanart/background image
         so the loading dialog and player overlay still show something
         visual even when both sources fail).

    The previous v3.9.85 behaviour was the addon URL first with logo
    filtering. That worked but exposed users to the addon-logo problem
    whenever the addon URL passed the heuristic by luck (e.g. hosted
    on imgur). The user-reported case was an Arabic anime addon
    returning its orange fox icon for the live-action show "FROM";
    moving TMDb to first place fixes that class of issue at the source
    instead of relying on URL pattern detection.
    """
    # Tier 1: TMDb/MetaHub clean URL
    imdb_id = (imdb_id or '').strip()
    if imdb_id.startswith('tt') and len(imdb_id) >= 4:
        return _METAHUB_POSTER % imdb_id
    # Tier 2: addon-provided URL, if not suspect
    if url and not _is_suspect_logo_poster(url):
        return url
    if url:
        try:
            xbmc.log('[NuvioHub] rejected suspect addon-logo poster: %s' % url[:120], xbmc.LOGINFO)
        except Exception:
            pass
    # Tier 3: caller-supplied fallback
    return fallback or ''



def _quick_to_results_enabled():
    """Default to fast parallel opening with live background completion.

    Full-scan mode is still available for users who prefer waiting up front.
    """
    if _full_parallel_source_scan_enabled():
        return False
    try:
        raw = (ADDON.getSetting('streams_quick_to_results') or 'true').strip().lower()
    except Exception:
        return True

    return raw in ('true', '1', 'yes', 'on')


def _source_scan_cancelled():
    """True when the user backed out of the source scan on purpose.

    v3.9.227: pressing Back mid-scan produced "playback failed" — wrong and
    alarming. The user did not fail; they left. Only a scan that ran to
    completion and genuinely found nothing deserves an error.
    """
    try:
        if xbmc.Monitor().abortRequested():
            return True
    except Exception:
        pass
    for prop in ('nuviohub.sources.cancelled', 'nuviohub.sources.stopped'):
        try:
            if (xbmcgui.Window(WINDOW_ID).getProperty(prop) or '') == '1':
                return True
        except Exception:
            continue
    return False


def _server_direct_entry(canonical_id, media_type, season=None, episode=None):
    """Play a server item DIRECTLY when the source scan comes back empty.

    v3.9.207 — the honest fix for content that lives ONLY on the user's server.

    A Turkish series with no IMDb/TMDb entry cannot be matched by any Stremio
    addon, and the id-based lookup inside the native Plex/Emby source step has
    nothing to match on either — so the scan ends with zero sources and the
    item simply refuses to play. But we do not NEED to search: the item came
    from the server, we hold its rating key, and the file is right there.

    So when the canonical id IS a server id (`plex:<server>:<key>` /
    `emby:<key>`), resolve the file straight from that server and hand back one
    ready-to-play entry. Identified content is untouched — this only runs after
    everything else has already returned nothing.
    """
    cid = str(canonical_id or '')
    if not cid.startswith(('plex:', 'emby:')):
        return []
    try:
        backend, rest = cid.split(':', 1)
        if backend == 'plex':
            server_id, rating_key = rest.split(':', 1)
            server = _plex_server(server_id)
            item = plex_client.metadata(server, rating_key)
            versions = [v for v in (item.get('versions') or []) if v.get('part_key')]
            make_url = lambda v: plex_client.playback_url(item, part_key=v['part_key'])
            poster = plex_client.artwork_url(item, item.get('thumb') or '')
            label = 'PLEX NATIVE'
            colour = PLEX_COLOR
            server_name = server.get('name') or 'Plex'
        else:
            rating_key = rest
            server = _emby_server()
            item = emby_client.metadata(server, rating_key)
            versions = [v for v in (item.get('versions') or []) if v.get('media_source_id')]
            make_url = lambda v: emby_client.playback_url(
                server, item.get('rating_key'), v.get('media_source_id') or '')
            poster = emby_client.artwork_url(server, item.get('thumb') or '')
            label = 'EMBY NATIVE'
            colour = EMBY_COLOR
            server_name = server.get('name') or 'Emby'
    except Exception as exc:
        xbmc.log('[NuvioHub] direct server play unavailable: %s' % exc, xbmc.LOGWARNING)
        return []

    if not versions:
        return []

    entries = []
    for version in versions:
        try:
            url = make_url(version)
        except Exception:
            continue
        name = os.path.basename(version.get('file') or '') or (
            item.get('raw_title') or item.get('title') or 'Direct')
        facts = version.get('info_line') or ''
        payload = {
            'stream_url': url,
            'name': name,
            'title': item.get('title') or '',
            'poster': poster,
            'provider_name': '%s \u2022 %s' % (
                'Plex' if label.startswith('PLEX') else 'Emby', server_name),
            'subtitles': list(version.get('subtitles') or []),
            'size_label': version.get('size_label') or '',
        }
        entries.append({
            'stream_key': cache_store.put('stream', payload),
            'name': '[COLOR %s]%s[/COLOR]  %s' % (colour, label, name),
            'quality': version.get('resolution') or '',
            'provider': 'PLEX' if label.startswith('PLEX') else 'EMBY',
            'provider_name_raw': payload['provider_name'],
            'addon': payload['provider_name'],
            'source_site': server_name,
            'size_label': version.get('size_label') or '',
            'size_bytes': version.get('size_bytes') or 0,
            'filename': name,
            'label2': '%s \u2022 %s' % (facts, payload['provider_name']) if facts
                      else payload['provider_name'],
            'source_info': facts,
            'stream_url': url,
        })
    xbmc.log('[NuvioHub] direct server play: %d version(s) for %s'
             % (len(entries), cid), xbmc.LOGINFO)
    return entries


def streams(media_type, canonical_id, title='', resume_seconds='0', resume_percent='', preferred_provider_name='', source_provider_id='', source_mode='', seed_ids=None, ui_seed=None):
    from .frontend_bridge import legacy_streams
    return legacy_streams(**locals())
    _clear_source_transient_props(clear_global=False)
    _mark_interactive_busy()
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    best_meta, has_cached_meta = _fast_meta_for_sources(media_type, canonical_id, providers, title=title, source_provider_id=source_provider_id)
    best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, media_type)
    art = _resolve_meta_art(providers[0] if providers else {}, media_type, best_meta, fallback_art=provider_fb) if has_cached_meta else dict(provider_fb)
    art = _prefer_item_art(art, best_meta, media_type, fallback_art=provider_fb)
    art = _merge_ui_seed_into_art(art, ui_seed)
    ids = _merge_seed_ids(_merge_seed_ids(extract_ids(best_meta), seed_ids or {}), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    # Subtitle discovery is independent from the chosen release. Start it at
    # the same moment as stream discovery so one fixed five-second budget
    # covers both phases. Source/native sidecars are still merged only after
    # the user picks the exact stream.
    try:
        start_subtitle_prefetch(
            media_type, canonical_id, ids=ids,
            title=title or best_meta.get('name') or best_meta.get('title') or canonical_id,
        )
    except Exception as exc:
        xbmc.log('[NuvioHub] source-scan subtitle prefetch failed: %s' % exc,
                 xbmc.LOGDEBUG)
    _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    win = xbmcgui.Window(WINDOW_ID)
    logo = art.get('clearlogo') or ''
    win.setProperty('clearlogo', logo)
    win.setProperty('tvshow.clearlogo', logo)
    bg = _content_background(art, provider_fb)
    win.setProperty('fanart', bg)
    win.setProperty('poster', art.get('poster') or '')
    try:
        resume_seconds = float(resume_seconds or 0.0)
    except Exception:
        resume_seconds = 0.0
    try:
        resume_percent_val = float(resume_percent or 0.0)
    except Exception:
        resume_percent_val = 0.0
    targets_all = _prioritize_provider_targets(list(_stream_provider_targets(media_type, canonical_id, meta=stream_meta)), preferred_provider_name=preferred_provider_name)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    # v3.9.65: race all candidate providers and open the source picker
    # as soon as the FIRST entry arrives (instead of waiting for every
    # provider). Slow providers continue to fill the live results window
    # through the existing stream_session refresh thread, and the user
    # can click any source the moment it appears.
    _quick = _quick_to_results_enabled()
    loading_art = _loading_art_fast(media_type, best_meta, art, bg, ids, title=title or canonical_id)
    art = _merge_ui_seed_into_art(art, loading_art)
    bg = loading_art.get('fanart') or bg
    processed_targets = []
    scan_state = {}
    entries = _collect_stream_entries(
        targets, media_type, canonical_id, best_meta, art, bg, ids,
        title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
        stop_after_first=_quick, processed_targets=processed_targets,
        scan_state=scan_state,
    )
    _active_race = scan_state.get('race')
    if _active_race is not None:
        remaining_targets = _active_race.pending_items()
    else:
        processed_set = set((id(p), rid) for p, rid in processed_targets)
        remaining_targets = [t for t in targets if (id(t[0]), t[1]) not in processed_set]
    if not entries and fallback_targets:
        processed_targets = []
        try:
            if _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        scan_state = {}
        entries = _collect_stream_entries(
            fallback_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
            stop_after_first=_quick, processed_targets=processed_targets,
            scan_state=scan_state,
        )
        _active_race = scan_state.get('race')
        if _active_race is not None:
            remaining_targets = _active_race.pending_items()
        else:
            processed_set = set((id(p), rid) for p, rid in processed_targets)
            remaining_targets = [t for t in fallback_targets if (id(t[0]), t[1]) not in processed_set]
    if not entries:
        # Nothing matched anywhere — but if this item CAME from the user's own
        # server we do not need a match at all: play the file directly.
        entries = _server_direct_entry(canonical_id, media_type)
    if not entries:
        try:
            if _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        if _source_scan_cancelled():
            xbmc.log('[NuvioHub] source scan cancelled by the user — no error', xbmc.LOGINFO)
            if HANDLE >= 0:
                try:
                    xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
                except Exception:
                    pass
            return end_dir(cache=False)
        error(tr('No playback links were found'))
        if HANDLE >= 0:
            try:
                xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
            except Exception:
                pass
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id)
    # Pull plot/year/genre/rating from best_meta so the source window can
    # render the redesigned hero panel (Plot textbox, year-genre-rating row).
    _genres = best_meta.get('genres') or []
    if isinstance(_genres, list):
        _genre_str = ' / '.join([str(g) for g in _genres[:3] if g])
    else:
        _genre_str = str(_genres or '')
    _year_val = ''
    _release = best_meta.get('releaseInfo') or best_meta.get('year') or ''
    if _release:
        _ymatch = YEAR_RE.search(str(_release))
        if _ymatch:
            _year_val = _ymatch.group(1)
    _rating = best_meta.get('imdbRating') or ''
    try:
        if _rating:
            _rating = '%.1f' % float(_rating)
    except Exception:
        _rating = str(_rating or '')
    _src_info = _stream_meta_info_payload(best_meta, media_type=media_type, title=title or best_meta.get('name') or canonical_id)
    _src_studio = _src_info.get('studio') or ''
    if isinstance(_src_studio, (list, tuple)):
        _src_studio = ' / '.join([str(x) for x in _src_studio if x])
    meta = {
        'title': title or best_meta.get('name') or canonical_id,
        'poster': art.get('poster') or provider_fb.get('poster') or provider_fb.get('thumb') or '',
        'fanart': _content_background(art, provider_fb),
        'clearlogo': art.get('clearlogo') or '',
        'plot': best_meta.get('description') or best_meta.get('overview') or '',
        'year': _year_val,
        'genre': _genre_str,
        'rating': _rating,
        'studio': _src_studio,
        'imdb_id': ids.get('imdb_id') or '',
        'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'media_type': media_type,
        'canonical_id': canonical_id,
    }
    session_key = ''
    if remaining_targets:
        session_key = source_session.create(entries, done=False, version=1)
        _start_stream_session_refresh(
            session_key, entries, remaining_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val,
            scan_race=_active_race,
        )
    return _show_stream_window(entries, meta, session_key=session_key)



def _video_season_num(video):
    """Season number of a Stremio video entry, with season 0 kept as 0.

    v3.9.239: both series_meta() and season() parsed this with a bare
    `or 1` fallback. JSON number 0 is falsy, so SPECIALS
    (season 0) were silently merged into Season 1 — polluting its episode list
    and letting a special "S01E01" collide with the real S01E01, which could
    send stream matching after the wrong video id. A string '0' did NOT trigger
    it (non-empty strings are truthy), so the bug was intermittent by provider.
    Missing/None/garbage still defaults to season 1.
    """
    raw = video.get('season')
    if raw is None or raw == '':
        return 1
    try:
        return int(raw)
    except Exception:
        return 1


def series_meta(media_type, canonical_id, title='', source_provider_id=''):
    from .frontend_bridge import legacy_streams
    return legacy_streams(**locals())
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    meta = None
    meta_provider = None
    for provider in providers:
        try:
            data = fetch_meta(provider, media_type, canonical_id, timeout_override=fast_timeout('meta'))
            meta = data.get('meta') or data.get('metas')
            if isinstance(meta, list):
                meta = meta[0] if meta else None
            if meta and meta.get('videos'):
                meta_provider = provider
                break
        except Exception:
            continue
    if not meta:
        error(tr('Could not fetch the series data'))
        return end_dir()
    try:
        from . import meta_source as _meta_source
        if _is_virtual_meta_target(source_provider_id):
            meta = _meta_source.override_virtual_meta(source_provider_id, media_type, meta) or meta
        else:
            meta = _meta_source.override_meta(meta_provider or (providers[0] if providers else {}), media_type, meta) or meta
    except Exception:
        pass
    seasons = {}
    videos = meta.get('videos') or []
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id, json.dumps(videos))
    art_provider = meta_provider or (providers[0] if providers else {})
    provider_fb = _item_fallback_art(art_provider, media_type)
    series_art = _resolve_meta_art(art_provider, media_type, meta, fallback_art=provider_fb)
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.art', json.dumps(series_art))
    resolved_series_title = meta.get('name') or title or canonical_id
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.title', resolved_series_title)
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type', media_type or 'series')
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id', source_provider_id if _is_virtual_meta_target(source_provider_id) else ((art_provider or {}).get('id') or source_provider_id or ''))
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.native_art', '1' if (_provider_prefers_native_art(art_provider) or _provider_uses_explicit_meta_art(art_provider)) else '0')
    ids = _merge_seed_ids(extract_ids(meta), _get_tmdbh_seed_ids(canonical_id))
    for video in videos:
        season_num = _video_season_num(video)
        seasons.setdefault(season_num, []).append(video)
    for season_num in sorted(seasons.keys()):
        _season_label = 'Specials' if season_num == 0 else (tr('Season %s') % season_num)
        add_item(
            _season_label,
            build_url(action='season', media_type=media_type, canonical_id=canonical_id, season=season_num, title=resolved_series_title),
            info={'title': _season_label, 'tvshowtitle': resolved_series_title, 'mediatype': 'season'},
            art=dict(series_art, thumb=series_art.get('poster'), icon=series_art.get('poster')),
            ids=ids,
        )
    end_dir(content='seasons')


def season(canonical_id, season, title='', media_type=''):
    raw = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id)
    videos = []
    if raw:
        try:
            videos = json.loads(raw)
        except Exception:
            videos = []
    art_raw = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.art')
    series_art = {}
    if art_raw:
        try:
            series_art = json.loads(art_raw)
        except Exception:
            series_art = {}
    show_title = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.title') or title
    media_type = media_type or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type') or 'series'
    prefer_native_art = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.native_art') == '1'
    season = int(season)
    # Compute once — canonical_id doesn't change across episodes.
    episode_ids = _merge_seed_ids(extract_ids({'id': canonical_id}), _get_tmdbh_seed_ids(canonical_id))
    for video in videos:
        if _video_season_num(video) != season:
            continue
        ep = int(video.get('episode') or 0)
        # v3.9.239: a video without an id used to fall back to the BARE series
        # id, but providers expect '<series>:<season>:<episode>' for episode
        # streams (Cinemeta convention) — a bare series id matches nothing.
        _ep_video_id = video.get('id') or ('%s:%s:%s' % (canonical_id, season, ep))
        vtitle = video.get('title') or ('S%02dE%02d' % (season, ep))
        label = 'S%02dE%02d — %s' % (season, ep, vtitle)
        meta = {'id': video.get('id') or canonical_id, 'name': vtitle, 'poster': video.get('thumbnail') or '', 'background': video.get('thumbnail') or '', 'type': 'series'}
        episode_art = native_meta_art(meta, media_type if media_type in ('anime','series') else 'series', fallback_art=series_art) if prefer_native_art else enrich_meta_art(meta, media_type if media_type in ('anime','series') else 'series', fallback_art=series_art)
        episode_path, episode_is_folder = _content_click_path(media_type=media_type or 'series', canonical_id=canonical_id, video_id=_ep_video_id, season=season, episode=ep, title=vtitle, tmdb_id=episode_ids.get('tmdb_id') or '', imdb_id=episode_ids.get('imdb_id') or '', tvdb_id=episode_ids.get('tvdb_id') or '', source_provider_id=xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or '', ui_seed=episode_art)
        episode_menu = _build_source_picker_menu(media_type=media_type or 'series', canonical_id=canonical_id, title=vtitle, season=season, episode=ep, video_id=_ep_video_id, source_provider_id=xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or '') + _build_player_chooser_menu(media_type=media_type or 'series', canonical_id=canonical_id, title=vtitle, season=season, episode=ep, video_id=_ep_video_id)
        add_item(label, episode_path, is_folder=episode_is_folder, info={'title': vtitle, 'episode': ep, 'season': season, 'tvshowtitle': show_title, 'mediatype': 'episode', 'plot': video.get('overview') or ''}, art=episode_art, context_menu=episode_menu)
    end_dir(content='episodes')


# v3.9.104: pre-cache the NEXT episode's stream sources while the current
# episode is still playing. Triggered ~60s into playback (long enough that the
# user is committed; short enough that the binge UX feels instant). Runs in a
# daemon thread, silently — no UI, no loader, no notifications. Result lands
# in precache_store and is consumed by episode_streams() on the next play.
def _precache_episode_async(canonical_id, video_id, season, episode, title='', media_type='series', delay_seconds=60):
    try:
        from . import precache_store as _pc
    except Exception:
        return
    try:
        season_i = int(season or 0)
        episode_i = int(episode or 0)
    except Exception:
        return
    if not canonical_id or season_i <= 0 or episode_i <= 0:
        return
    # Reserve the slot so a second trigger for the same episode (rare but
    # possible if the user replays) doesn't spin up a duplicate scrape.
    if not _pc.mark_inflight(canonical_id, season_i, episode_i):
        return

    def _worker():
        try:
            import time as _t
            if delay_seconds > 0:
                _t.sleep(delay_seconds)
            # Abort if Kodi is shutting down or the user already moved on to
            # something else mid-binge — no point scraping a stale next-up.
            try:
                if xbmc.Monitor().abortRequested():
                    return
            except Exception:
                pass
            try:
                xbmc.log('[NuvioHub] precache worker scraping s%se%s of %s'
                         % (season_i, episode_i, canonical_id), xbmc.LOGINFO)
            except Exception:
                pass
            # Replicate the early setup that episode_streams() does, but never
            # call into UI code (no loader, no picker open, no transient
            # property writes).
            providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id='')
            best_meta, _has = _fast_meta_for_sources(media_type, canonical_id, providers,
                                                     title=title or canonical_id, source_provider_id='')
            ids = _merge_seed_ids(extract_ids(best_meta), _get_tmdbh_seed_ids(canonical_id))
            ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id,
                                     title=title or best_meta.get('name') or best_meta.get('title') or '')
            stream_meta = _meta_with_seed_ids(best_meta, ids)
            direct_targets = []
            for provider in store.list_providers():
                if supports_resource(provider, 'stream', media_type=media_type, item_id=video_id):
                    direct_targets.append((provider, video_id))
            targets_all = direct_targets + [t for t in _stream_provider_targets(
                media_type, canonical_id, meta=stream_meta, season=season_i, episode=episode_i)
                if t not in direct_targets]
            targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name='')
            targets, fallback_targets = _split_targets_by_source_mode(targets_all,
                                                                       source_provider_id='', source_mode='')
            if not targets and not fallback_targets:
                return
            # Silent scrape: show_loader=False. stop_after_first=False so the
            # pre-cache has the FULL list (no point cutting short when no user
            # is waiting). Empty art dicts because we don't need to write to UI.
            entries = _collect_stream_entries(
                targets, media_type, canonical_id, best_meta, {}, '', ids,
                title=title or video_id, video_id=video_id, season=season_i, episode=episode_i,
                show_title=best_meta.get('name') or canonical_id,
                resume_seconds=0.0, resume_percent=0.0,
                show_loader=False, stop_after_first=False, processed_targets=None,
            )
            if not entries and fallback_targets:
                entries = _collect_stream_entries(
                    fallback_targets, media_type, canonical_id, best_meta, {}, '', ids,
                    title=title or video_id, video_id=video_id, season=season_i, episode=episode_i,
                    show_title=best_meta.get('name') or canonical_id,
                    resume_seconds=0.0, resume_percent=0.0,
                    show_loader=False, stop_after_first=False, processed_targets=None,
                )
            if entries:
                _pc.put(canonical_id, season_i, episode_i, entries, meta=best_meta)
                try:
                    xbmc.log('[NuvioHub] precache STORED %d entries for s%se%s'
                             % (len(entries), season_i, episode_i), xbmc.LOGINFO)
                except Exception:
                    pass
            else:
                try:
                    xbmc.log('[NuvioHub] precache worker found 0 entries for s%se%s'
                             % (season_i, episode_i), xbmc.LOGWARNING)
                except Exception:
                    pass
        except Exception as exc:
            try:
                xbmc.log('[NuvioHub] precache worker crashed: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
        finally:
            try:
                _pc.release_inflight(canonical_id, season_i, episode_i)
            except Exception:
                pass

    import threading as _th
    try:
        t = _th.Thread(target=_worker, name='NuvioHubPrecache-s%se%s' % (season_i, episode_i))
        t.daemon = True
        t.start()
    except RuntimeError as exc:
        try:
            xbmc.log('[NuvioHub] skipped next-episode precache: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass


def episode_streams(canonical_id, video_id, season, episode, title='', media_type='', resume_seconds='0', resume_percent='', preferred_provider_name='', source_provider_id='', source_mode='', seed_ids=None, ui_seed=None):
    from .frontend_bridge import legacy_streams
    return legacy_streams(**locals())
    _clear_source_transient_props(clear_global=False)
    _mark_interactive_busy()
    media_type = media_type or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type') or 'series'
    source_provider_id = source_provider_id or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or ''
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    best_meta, has_cached_meta = _fast_meta_for_sources(media_type, canonical_id, providers, title=title or canonical_id, source_provider_id=source_provider_id)
    best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, media_type)
    art = _resolve_meta_art(providers[0] if providers else {}, media_type, best_meta, fallback_art=provider_fb) if has_cached_meta else dict(provider_fb)
    art = _prefer_item_art(art, best_meta, media_type, fallback_art=provider_fb)
    art = _merge_ui_seed_into_art(art, ui_seed)
    ids = _merge_seed_ids(_merge_seed_ids(extract_ids(best_meta), seed_ids or {}), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    try:
        start_subtitle_prefetch(
            media_type, canonical_id, ids=ids,
            title=title or best_meta.get('name') or canonical_id,
            season=season, episode=episode,
        )
    except Exception as exc:
        xbmc.log('[NuvioHub] episode source-scan subtitle prefetch failed: %s' % exc,
                 xbmc.LOGDEBUG)
    _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    win = xbmcgui.Window(WINDOW_ID)
    logo = art.get('clearlogo') or ''
    win.setProperty('clearlogo', logo)
    win.setProperty('tvshow.clearlogo', logo)
    bg = _content_background(art, provider_fb)
    win.setProperty('fanart', bg)
    win.setProperty('poster', art.get('poster') or '')
    direct_targets = []
    for provider in store.list_providers():
        if not _get_bool_setting('stremio_sources_enabled', True):
            break
        if _stremio_provider.supports_stream(provider, media_type, item_id=video_id):
            direct_targets.append((provider, video_id))
    try:
        resume_seconds = float(resume_seconds or 0.0)
    except Exception:
        resume_seconds = 0.0
    try:
        resume_percent_val = float(resume_percent or 0.0)
    except Exception:
        resume_percent_val = 0.0
    targets_all = direct_targets + [t for t in _stream_provider_targets(media_type, canonical_id, meta=stream_meta, season=season, episode=episode) if t not in direct_targets]
    targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name=preferred_provider_name)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    # v3.9.65: same race strategy as movies — open the source picker
    # the moment the FIRST entry arrives (instead of waiting for every
    # provider). Especially valuable for NextUp/collection-driven
    # episode playback where the user wants to start watching ASAP.
    _quick = _quick_to_results_enabled()
    loading_art = _loading_art_fast(media_type, best_meta, art, bg, ids, title=title or best_meta.get('name') or canonical_id)
    art = _merge_ui_seed_into_art(art, loading_art)
    bg = loading_art.get('fanart') or bg

    # v3.9.104: pre-cache hit short-circuits the entire scrape. If the previous
    # episode's playback warmed sources for this one, we use them as-is and
    # the picker opens instantly. Cache miss falls through to the normal
    # network scrape unchanged.
    entries = None
    remaining_targets = []
    try:
        from . import precache_store as _pc
        _hit = _pc.consume(canonical_id, season, episode)
        if _hit:
            cached_entries, _cached_meta = _hit
            if cached_entries:
                entries = list(cached_entries)
                try:
                    xbmc.log('[NuvioHub] precache HIT for s%se%s (%d entries) — skipping live scrape'
                             % (season, episode, len(entries)), xbmc.LOGINFO)
                except Exception:
                    pass
    except Exception as _pc_exc:
        try:
            xbmc.log('[NuvioHub] precache lookup failed: %s' % _pc_exc, xbmc.LOGDEBUG)
        except Exception:
            pass

    processed_targets = []
    scan_state = {}
    if entries is None:
        entries = _collect_stream_entries(
            targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title or video_id, video_id=video_id, season=season, episode=episode,
            show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
            stop_after_first=_quick, processed_targets=processed_targets,
            scan_state=scan_state,
        )
        _active_race = scan_state.get('race')
        if _active_race is not None:
            remaining_targets = _active_race.pending_items()
        else:
            processed_set = set((id(p), rid) for p, rid in processed_targets)
            remaining_targets = [t for t in targets if (id(t[0]), t[1]) not in processed_set]
        if not entries and fallback_targets:
            processed_targets = []
            try:
                if _active_race is not None:
                    _active_race.cancel()
            except Exception:
                pass
            scan_state = {}
            entries = _collect_stream_entries(
                fallback_targets, media_type, canonical_id, best_meta, art, bg, ids,
                title=title or video_id, video_id=video_id, season=season, episode=episode,
                show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
                stop_after_first=_quick, processed_targets=processed_targets,
                scan_state=scan_state,
            )
            _active_race = scan_state.get('race')
            if _active_race is not None:
                remaining_targets = _active_race.pending_items()
            else:
                processed_set = set((id(p), rid) for p, rid in processed_targets)
                remaining_targets = [t for t in fallback_targets if (id(t[0]), t[1]) not in processed_set]
    if not entries:
        try:
            if entries is None or _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        if _source_scan_cancelled():
            xbmc.log('[NuvioHub] source scan cancelled by the user — no error', xbmc.LOGINFO)
            return end_dir(cache=False)
        error(tr('No playback links were found for the episode'))
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id, video_id=video_id)
    # Pull plot/year/genre/rating from best_meta so the source window can
    # render the redesigned hero panel for the episode picker too.
    _ep_genres = best_meta.get('genres') or []
    if isinstance(_ep_genres, list):
        _ep_genre_str = ' / '.join([str(g) for g in _ep_genres[:3] if g])
    else:
        _ep_genre_str = str(_ep_genres or '')
    _ep_year_val = ''
    _ep_release = best_meta.get('releaseInfo') or best_meta.get('year') or ''
    if _ep_release:
        _ep_ymatch = YEAR_RE.search(str(_ep_release))
        if _ep_ymatch:
            _ep_year_val = _ep_ymatch.group(1)
    _ep_rating = best_meta.get('imdbRating') or ''
    try:
        if _ep_rating:
            _ep_rating = '%.1f' % float(_ep_rating)
    except Exception:
        _ep_rating = str(_ep_rating or '')
    _ep_info = _stream_meta_info_payload(best_meta, media_type=media_type, title=title or video_id, show_title=best_meta.get('name') or canonical_id, season=season, episode=episode)
    _ep_studio = _ep_info.get('studio') or ''
    if isinstance(_ep_studio, (list, tuple)):
        _ep_studio = ' / '.join([str(x) for x in _ep_studio if x])
    meta = {
        'title': title or video_id,
        'poster': art.get('poster') or provider_fb.get('poster') or provider_fb.get('thumb') or '',
        'fanart': _content_background(art, provider_fb),
        'clearlogo': art.get('clearlogo') or '',
        'plot': best_meta.get('description') or best_meta.get('overview') or '',
        'year': _ep_year_val,
        'genre': _ep_genre_str,
        'rating': _ep_rating,
        'studio': _ep_studio,
        'imdb_id': ids.get('imdb_id') or '',
        'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'media_type': media_type,
        'canonical_id': canonical_id,
        'season': season,
        'episode': episode,
    }
    session_key = ''
    if remaining_targets:
        session_key = source_session.create(entries, done=False, version=1)
        _start_stream_session_refresh(
            session_key, entries, remaining_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title or video_id, video_id=video_id, season=season, episode=episode,
            show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val,
            scan_race=_active_race,
        )
    return _show_stream_window(entries, meta, session_key=session_key)

def _resolve_best_id(video_type, tmdb_id='', imdb_id='', tvdb_id='', title=''):
    if tmdb_id:
        return 'tmdb:%s' % tmdb_id
    if imdb_id:
        return imdb_id if str(imdb_id).startswith('tt') else 'imdb:%s' % imdb_id
    if tvdb_id:
        return 'tvdb:%s' % tvdb_id
    return title or ''


def _find_episode_video_id(canonical_id, season, episode):
    providers = _provider_order_for_id('series', canonical_id)
    for provider in providers:
        try:
            data = fetch_meta(provider, 'series', canonical_id, timeout_override=fast_timeout('meta'))
            meta = data.get('meta') or data.get('metas')
            if isinstance(meta, list):
                meta = meta[0] if meta else None
            videos = (meta or {}).get('videos') or []
            for video in videos:
                if int(video.get('season') or 0) == int(season or 0) and int(video.get('episode') or 0) == int(episode or 0):
                    return video.get('id') or canonical_id, (meta or {}).get('name') or canonical_id
        except Exception:
            continue
    return canonical_id, ''



def _tmdbh_resume_from_continue(media_type='movie', canonical_id='', tmdb_id='', imdb_id='', tvdb_id='', season='', episode='', title=''):
    """Best-effort resume bridge for TMDb Helper -> NuvioHub playback.

    When a skin/widget launches playback through TMDb Helper, the player URL
    does not carry NuvioHub's local Continue Watching position. NuvioHub's own CW
    screen resumes correctly because it calls cw_resume with resume_seconds,
    but the TMDbH handoff only gives IDs.  Look up the matching row in our
    playback database and inject resume_seconds/resume_percent into the source
    picker/autoplay path.  This keeps TMDbH widgets from starting local NuvioHub
    progress at 0:00.
    """
    def _norm_imdb(v):
        v = str(v or '').strip()
        if v.lower().startswith('imdb:'):
            v = v.split(':', 1)[1].strip()
        if v.isdigit():
            v = 'tt%s' % v
        return v.lower()

    wanted = {
        'canonical': str(canonical_id or '').strip().lower(),
        'tmdb_id': str(tmdb_id or '').strip(),
        'imdb_id': _norm_imdb(imdb_id),
        'tvdb_id': str(tvdb_id or '').strip(),
    }

    def _norm_title(value):
        # Last-resort legacy matching only.  Keep Arabic/Latin letters and
        # digits, collapse punctuation/spacing, and require a UNIQUE row
        # below.  This recovers opaque provider ids from old databases without
        # guessing between remakes or identically named shows.
        value = str(value or '').strip().casefold()
        value = re.sub(r'[^\w]+', ' ', value, flags=re.UNICODE)
        return ' '.join(value.split())

    wanted_title = _norm_title(title)
    try:
        wanted['season'] = int(season or 0)
    except Exception:
        wanted['season'] = 0
    try:
        wanted['episode'] = int(episode or 0)
    except Exception:
        wanted['episode'] = 0

    is_episode = wanted['season'] > 0 and wanted['episode'] > 0

    def _resume_payload(row):
        """Normalize a stored row into the playback arguments we need."""
        try:
            pos = float(row.get('position') or 0.0)
        except Exception:
            pos = 0.0
        try:
            pct = float(row.get('percent') or 0.0)
        except Exception:
            pct = 0.0
        if pos <= 1.0 and not (1.0 < pct < 95.0):
            return {}
        return {
            'resume_seconds': pos if pos > 1.0 else 0,
            'resume_percent': ('%.2f' % pct) if (pos <= 1.0 and 1.0 < pct < 95.0) else '',
            'provider_name': row.get('provider_name') or '',
            'poster': row.get('poster') or '',
            'fanart': row.get('background') or '',
            'clearlogo': row.get('clearlogo') or '',
            'updated_at': int(row.get('updated_at') or 0),
            'source': 'nuviohub',
        }

    # v3.9.157: New rows have independent standard ids and are found via
    # indexed lookups.  This is both reliable for provider-private ids and
    # avoids loading/scanning 500 Continue Watching rows on every TMDbH play.
    try:
        direct_row = playback_store.find_resume_entry(
            media_type='series' if is_episode else 'movie',
            canonical_id=canonical_id,
            tmdb_id=wanted['tmdb_id'], imdb_id=wanted['imdb_id'], tvdb_id=wanted['tvdb_id'],
            season=wanted['season'], episode=wanted['episode'],
        )
        direct_payload = _resume_payload(direct_row or {})
        if direct_payload:
            xbmc.log('[NuvioHub] TMDbH resume bridge matched indexed playback row', xbmc.LOGINFO)
            return direct_payload
    except Exception as exc:
        try:
            xbmc.log('[NuvioHub] TMDbH indexed resume lookup failed: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass

    # Compatibility path for progress recorded before the schema migration.
    # Old rows do not have dedicated id columns, so retain the conservative
    # parser below until users naturally re-save their playback positions.
    try:
        rows = playback_store.list_continue_items(limit=500) or []
    except Exception:
        return {}
    title_candidates = []
    for row in rows:
        try:
            row_mt = str(row.get('media_type') or '').strip().lower()
            row_is_episode = _continue_row_is_episode(row)
            if is_episode != bool(row_is_episode):
                continue
            if is_episode:
                if int(row.get('season') or 0) != wanted['season'] or int(row.get('episode') or 0) != wanted['episode']:
                    continue
            elif row_mt not in ('movie', 'movies', ''):
                # Avoid matching a show-level row against movie playback.
                continue

            row_canonical = str(row.get('canonical_id') or '').strip()
            row_video = str(row.get('video_id') or '').strip()
            if wanted_title and _norm_title(row.get('title') or '') == wanted_title:
                title_candidates.append(row)
            row_ids = _merge_seed_ids(extract_ids({'id': row_canonical}), extract_ids({'id': row_video}))
            # Some older rows were saved with plain tmdb/imdb ids embedded in
            # canonical/video only, while TMDb Helper calls us with explicit
            # route ids. Keep the matching permissive but still require
            # season/episode equality for episodes (checked above).
            row_tmdb = str(row_ids.get('tmdb_id') or '').strip()
            row_imdb = _norm_imdb(row_ids.get('imdb_id') or '')
            row_tvdb = str(row_ids.get('tvdb_id') or '').strip()

            matched = False
            _row_keys = set([row_canonical.lower(), row_video.lower()])
            if row_tmdb:
                _row_keys.update(['tmdb:%s' % row_tmdb, 'tmdb:movie:%s' % row_tmdb, 'tmdb:tv:%s' % row_tmdb, 'tmdb:series:%s' % row_tmdb])
            if row_imdb:
                _row_keys.update([row_imdb, 'imdb:%s' % row_imdb])
            if row_tvdb:
                _row_keys.update(['tvdb:%s' % row_tvdb])
            if wanted['canonical'] and wanted['canonical'] in _row_keys:
                matched = True
            if not matched and wanted['tmdb_id'] and row_tmdb and wanted['tmdb_id'] == row_tmdb:
                matched = True
            if not matched and wanted['imdb_id'] and row_imdb and wanted['imdb_id'] == row_imdb:
                matched = True
            if not matched and wanted['tvdb_id'] and row_tvdb and wanted['tvdb_id'] == row_tvdb:
                matched = True
            if not matched:
                continue

            out = _resume_payload(row)
            if not out:
                continue
            try:
                xbmc.log('[NuvioHub] TMDbH resume bridge matched legacy CW row', xbmc.LOGINFO)
            except Exception:
                pass
            return out
        except Exception:
            continue
    # Old provider rows may contain only an opaque provider id.  When there is
    # exactly one unfinished row with the same normalized title (and the same
    # season/episode was already required above), it is safe enough to bridge
    # it once.  More than one candidate deliberately returns no resume.
    if len(title_candidates) == 1:
        out = _resume_payload(title_candidates[0])
        if out:
            try:
                xbmc.log('[NuvioHub] TMDbH resume bridge matched unique legacy title', xbmc.LOGINFO)
            except Exception:
                pass
            return out
    return {}


def _persist_unified_resume_hint(hint, media_type, canonical_id, video_id, title='', season=None, episode=None, ids=None, poster='', fanart='', clearlogo=''):
    """Mirror an external/live progress hint into Nuvio Hub's unified DB.

    Local Nuvio Hub rows are already persisted by the player monitor. TMDb
    Helper/Kodi and Trakt hints are saved here so Continue Watching immediately
    shows the same position and subsequent launches no longer require a remote
    lookup. Existing settings and historical rows are never deleted.
    """
    hint = dict(hint or {})
    source = str(hint.get('source') or '').strip().lower()
    if not hint or source in ('', 'nuviohub'):
        return False
    try:
        position = float(hint.get('resume_seconds') or 0.0)
        percent = float(hint.get('resume_percent') or 0.0)
        duration = float(hint.get('duration') or 0.0)
    except Exception:
        return False
    if duration <= 0 and position > 0 and percent > 1:
        duration = position * 100.0 / percent
    if percent <= 0 and duration > 0:
        percent = position * 100.0 / duration
    if position <= 30.0 or not (0.0 < percent < 95.0):
        return False
    ids = dict(ids or {})
    label = {'trakt': 'Trakt', 'tmdbhelper': 'TMDb Helper / Kodi', 'handoff': 'TMDb Helper'}.get(source, source.title())
    try:
        playback_store.upsert_entry(
            media_type, canonical_id, video_id, title or canonical_id, label,
            poster or '', fanart or '', clearlogo or '', season, episode,
            position, duration, percent, '', 'unified_import',
            ext_updated_at=(int(hint.get('updated_at') or 0) or None),
            tmdb_id=ids.get('tmdb_id') or '', imdb_id=ids.get('imdb_id') or '',
            tvdb_id=ids.get('tvdb_id') or '',
            show_tmdb_id=(ids.get('tmdb_id') or '') if media_type == 'series' else '',
        )
        return True
    except Exception as exc:
        xbmc.log('[NuvioHub] unified resume persist failed: %s' % exc, xbmc.LOGWARNING)
        return False

def tmdb_player(video_type='movie', tmdb_id='', imdb_id='', tvdb_id='', title='', year='', showname='', season='', episode='', ar_title='', ar_showname='', poster='', fanart='', resume_seconds='', resume_percent='', resume_duration='', resume_updated_at=''):
    vtype = (video_type or 'movie').lower()
    # Suppress duplicate TMDb Helper handoffs. TMDb Helper sometimes
    # fires its play URL twice in quick succession (especially when
    # users tap "Play" before the dialog has fully rendered). The dedup
    # key includes season/episode so different episodes of the same
    # show don't suppress each other.
    _tp_key = 'tmdb_player|%s|%s|%s|%s|%s|%s' % (
        vtype, tmdb_id or '', imdb_id or '', tvdb_id or '',
        str(season or ''), str(episode or ''),
    )
    if _dispatch_in_flight(_tp_key, window_seconds=12):
        xbmc.log('[NuvioHub] tmdb_player: duplicate dispatch suppressed (%s)' % _tp_key, xbmc.LOGINFO)
        return
    lookup_title = showname or title

    # Fallback: when the player JSON didn't pass any IDs (e.g. invoked from a
    # widget where TMDb Helper's service monitor populated home-window props
    # but the URL template was missing keys), try those props as last-resort
    # seed before declaring failure.
    if not (tmdb_id or imdb_id or tvdb_id):
        try:
            _mon_win = xbmcgui.Window(10000)
            tmdb_id = tmdb_id or (_mon_win.getProperty('TMDbHelper.ListItem.TMDb') or '').strip()
            imdb_id = imdb_id or (_mon_win.getProperty('TMDbHelper.ListItem.IMDb') or '').strip()
            tvdb_id = tvdb_id or (_mon_win.getProperty('TMDbHelper.ListItem.TVDb') or '').strip()
        except Exception:
            pass

    canonical_id = _resolve_best_id(vtype, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id, title=lookup_title)
    if not canonical_id:
        error('Missing IDs for TMDb Helper player')
        return end_dir()

    # Preserve the IDs TMDb Helper gave us so downstream code (subtitle broker,
    # scrobbler, companion sync) has real identifiers even when our meta
    # provider can't resolve them from the canonical id alone. Scope the stash
    # by canonical_id so a later unrelated stream doesn't wrongly inherit it.
    seed_ids = {
        'tmdb_id': str(tmdb_id or '').strip(),
        'imdb_id': str(imdb_id or '').strip() if str(imdb_id or '').startswith('tt') else ('tt%s' % imdb_id if imdb_id and str(imdb_id).isdigit() else str(imdb_id or '').strip()),
        'tvdb_id': str(tvdb_id or '').strip(),
    }
    _resume_media_type = 'series' if vtype in ('episode', 'show', 'series', 'tv') else 'movie'
    _local_resume = _tmdbh_resume_from_continue(
        media_type=_resume_media_type, canonical_id=canonical_id,
        tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id,
        season=season, episode=episode, title=lookup_title,
    )
    # Capture the focused item before the source window replaces Kodi's
    # ListItem context. This is what allows TMDb Helper/Kodi resume to work
    # even when Nuvio Hub has never played the item before.
    try:
        _live_resume = tmdbh_context.read_resume_hint(
            expected_tmdb_id=tmdb_id or None, expected_imdb_id=imdb_id or None,
            season=season, episode=episode) or {}
    except Exception:
        _live_resume = {}
    _explicit_resume = {}
    try:
        _epos, _epct, _edur = float(resume_seconds or 0), float(resume_percent or 0), float(resume_duration or 0)
        if _epos > 30 and _epct < 95:
            _explicit_resume = {'resume_seconds': _epos, 'resume_percent': _epct, 'duration': _edur, 'updated_at': int(float(resume_updated_at or 0)), 'source': 'handoff'}
    except Exception:
        _explicit_resume = {}
    _trakt_resume = {}
    if not (_explicit_resume or _live_resume):
        try:
            _trakt_resume = trakt.find_playback_progress(
                media_type=_resume_media_type, tmdb_id=tmdb_id, imdb_id=imdb_id,
                tvdb_id=tvdb_id, season=season, episode=episode) or {}
        except Exception:
            _trakt_resume = {}
    # Explicit/live context wins because it belongs to the item the user just
    # pressed. Otherwise choose the newest timestamp between Nuvio Hub and Trakt.
    if _explicit_resume:
        _tmdbh_resume_seed = _explicit_resume
    elif _live_resume:
        _tmdbh_resume_seed = _live_resume
    else:
        _local_ts = int((_local_resume or {}).get('updated_at') or 0)
        _trakt_ts = int((_trakt_resume or {}).get('updated_at') or 0)
        _tmdbh_resume_seed = _trakt_resume if (_trakt_resume and _trakt_ts > _local_ts) else (_local_resume or _trakt_resume or {})
    resume_seconds = _tmdbh_resume_seed.get('resume_seconds') or 0
    resume_percent = _tmdbh_resume_seed.get('resume_percent') or ''
    xbmc.log('[NuvioHub] unified resume source=%s pos=%.1f pct=%s' % (
        _tmdbh_resume_seed.get('source') or _tmdbh_resume_seed.get('provider_name') or 'none',
        float(resume_seconds or 0), str(resume_percent or '')), xbmc.LOGINFO)
    # v3.9.156: poster picker dialog is opt-in via settings; default keeps
    # the original search + full results page.
    _tmdbh_pick = (ADDON.getSetting('tmdbh_poster_picker') or 'false').strip().lower() in ('true', '1', 'yes', 'on')
    if not poster and _tmdbh_resume_seed.get('poster'):
        poster = _tmdbh_resume_seed.get('poster')
    if not fanart and _tmdbh_resume_seed.get('fanart'):
        fanart = _tmdbh_resume_seed.get('fanart')

    # Stash optional player-supplied art / Arabic-title hints so downstream
    # meta lookups can use them as a fast-path before hitting TMDb / Trakt.
    # These come from the v2 nuviohub.json player keys: {ar_title}, {poster},
    # {fanart}. Older v1 player files don't pass them; the empty defaults
    # mean nothing breaks.
    try:
        if ar_title:
            seed_ids['ar_title'] = ar_title
        if ar_showname:
            seed_ids['ar_showname'] = ar_showname
        if poster:
            seed_ids['poster'] = poster
        if fanart:
            seed_ids['fanart'] = fanart
    except Exception:
        pass

    try:
        win = xbmcgui.Window(WINDOW_ID)
        win.setProperty('nuviohub.tmdbh_seed_ids', json.dumps(seed_ids))
        win.setProperty('nuviohub.tmdbh_seed_for', canonical_id or '')
        win.setProperty('nuviohub.invoked_by_tmdbh', '1')
        _mark_tmdbh_handoff(60)
    except Exception:
        pass

    auto_first = False
    try:
        auto_first = (ADDON.getSetting('tmdbh_auto_play_first') or 'false').lower() == 'true'
    except Exception:
        auto_first = False

    if vtype in ('episode', 'show', 'series', 'tv'):
        if season and episode:
            video_id, resolved_title = _find_episode_video_id(canonical_id, season, episode)
            _persist_unified_resume_hint(
                _tmdbh_resume_seed, 'series', canonical_id, video_id,
                title=title or resolved_title or showname or canonical_id,
                season=int(season or 0), episode=int(episode or 0), ids=seed_ids,
                poster=poster or _tmdbh_resume_seed.get('poster') or '',
                fanart=fanart or _tmdbh_resume_seed.get('fanart') or '',
                clearlogo=_tmdbh_resume_seed.get('clearlogo') or '')
            if auto_first or _tmdbh_pick:
                return _auto_play_first_episode(canonical_id, video_id, season, episode, title=title or resolved_title or showname or canonical_id, seed_ids=seed_ids, resume_seconds=resume_seconds, resume_percent=resume_percent or '', preferred_provider_name=_tmdbh_resume_seed.get('provider_name') or '', pick_dialog=(_tmdbh_pick and not auto_first))
            return episode_streams(canonical_id, video_id, season, episode, title=title or resolved_title or showname or canonical_id, media_type='series', seed_ids=seed_ids, resume_seconds=resume_seconds, resume_percent=resume_percent or '', preferred_provider_name=_tmdbh_resume_seed.get('provider_name') or '', ui_seed={'ui_poster': poster or '', 'ui_fanart': fanart or '', 'ui_clearlogo': _tmdbh_resume_seed.get('clearlogo') or ''})
        return series_meta('series', canonical_id, title=showname or title or canonical_id)

    _persist_unified_resume_hint(
        _tmdbh_resume_seed, 'movie', canonical_id, canonical_id,
        title=title or canonical_id, ids=seed_ids,
        poster=poster or _tmdbh_resume_seed.get('poster') or '',
        fanart=fanart or _tmdbh_resume_seed.get('fanart') or '',
        clearlogo=_tmdbh_resume_seed.get('clearlogo') or '')
    if auto_first or _tmdbh_pick:
        return _auto_play_first_movie(canonical_id, title=title or canonical_id, seed_ids=seed_ids, resume_seconds=resume_seconds, resume_percent=resume_percent or '', preferred_provider_name=_tmdbh_resume_seed.get('provider_name') or '', pick_dialog=(_tmdbh_pick and not auto_first))
    return streams('movie', canonical_id, title=title or canonical_id, seed_ids=seed_ids, resume_seconds=resume_seconds, resume_percent=resume_percent or '', preferred_provider_name=_tmdbh_resume_seed.get('provider_name') or '', ui_seed={'ui_poster': poster or '', 'ui_fanart': fanart or '', 'ui_clearlogo': _tmdbh_resume_seed.get('clearlogo') or ''})


def _normalise_imdb_id_value(value):
    value = str(value or '').strip()
    if not value:
        return ''
    if value.lower().startswith('imdb:'):
        value = value.split(':', 1)[1].strip()
    if value.isdigit():
        value = 'tt%s' % value
    return value if re.match(r'^tt\d{5,10}$', value, re.I) else value


def _seed_ids_from_values(tmdb_id='', imdb_id='', tvdb_id='', canonical_id=''):
    """Normalize explicit route IDs from URLs/context into NuvioHub's *_id dict."""
    ids = {
        'tmdb_id': str(tmdb_id or '').strip(),
        'imdb_id': _normalise_imdb_id_value(imdb_id),
        'tvdb_id': str(tvdb_id or '').strip(),
    }
    ids = _merge_seed_ids(ids, extract_ids({'id': canonical_id or ''}))
    return {k: v for k, v in ids.items() if v}


def _ids_from_playback_ctx(ctx):
    ctx = ctx or {}
    ids = _seed_ids_from_values(
        tmdb_id=ctx.get('tmdb_id') or '',
        imdb_id=ctx.get('imdb_id') or '',
        tvdb_id=ctx.get('tvdb_id') or '',
        canonical_id=ctx.get('canonical_id') or '',
    )
    ext = ctx.get('external_ids') or {}
    if isinstance(ext, dict):
        ids = _merge_seed_ids(ids, {
            'tmdb_id': ext.get('tmdb_id') or ext.get('tmdb') or '',
            'imdb_id': _normalise_imdb_id_value(ext.get('imdb_id') or ext.get('imdb') or ''),
            'tvdb_id': ext.get('tvdb_id') or ext.get('tvdb') or '',
        })
    # Some episode stream ids arrive as tt1234567:1:2. Keep the show IMDb id.
    for key in ('video_id', 'stream_url'):
        text = str(ctx.get(key) or '')
        if not ids.get('imdb_id'):
            m = re.search(r'(tt\d{5,10})', text, re.I)
            if m:
                ids['imdb_id'] = m.group(1)
    return ids


def _ensure_playback_ids(ctx):
    """Best-effort final ID repair before Player.play/setResolvedUrl.

    a4kSubtitles can read IMDb from Kodi's player metadata and/or from the
    video file URL. Stream collection already tries to resolve IDs, but this
    final guard recovers IDs lost by older source-picker routes or quick-open
    paths. It is intentionally quiet and never blocks playback on failure.
    """
    out = dict(ctx or {})
    ids = _ids_from_playback_ctx(out)
    if not ids.get('imdb_id') and (ids.get('tmdb_id') or out.get('title') or out.get('show_title')):
        try:
            probe_meta = {
                'id': out.get('canonical_id') or '',
                'name': out.get('show_title') or out.get('title') or '',
                'title': out.get('show_title') or out.get('title') or '',
                'type': 'series' if out.get('season') or out.get('episode') or _is_series_media(out.get('media_type')) else 'movie',
            }
            ids = _enrich_stream_ids(ids, probe_meta.get('type') or 'movie', meta=probe_meta, canonical_id=out.get('canonical_id') or '', title=probe_meta.get('title') or '')
        except Exception:
            pass
    for key in ('tmdb_id', 'imdb_id', 'tvdb_id'):
        if ids.get(key) and not out.get(key):
            out[key] = ids.get(key)
    if ids:
        ext = dict(out.get('external_ids') or {}) if isinstance(out.get('external_ids') or {}, dict) else {}
        if ids.get('imdb_id'):
            ext.setdefault('imdb', ids.get('imdb_id'))
            ext.setdefault('imdb_id', ids.get('imdb_id'))
        if ids.get('tmdb_id'):
            ext.setdefault('tmdb', ids.get('tmdb_id'))
            ext.setdefault('tmdb_id', ids.get('tmdb_id'))
        if ids.get('tvdb_id'):
            ext.setdefault('tvdb', ids.get('tvdb_id'))
            ext.setdefault('tvdb_id', ids.get('tvdb_id'))
        out['external_ids'] = ext
    return out


def _append_a4k_ids_to_url(url, ctx):
    """Append Syncler/Stremio-style |ids={...} metadata for a4kSubtitles.

    a4kSubtitles supports IMDb metadata passed through the playing file URL;
    adding the compact ids object lets it recover IMDb even when Kodi's
    VideoPlayer.IMDBNumber infolabel is delayed/empty for plugin handoffs.
    """
    url = str(url or '').strip()
    if not url:
        return url
    lower = url.lower()
    # Do not append |ids={...} to real media URLs. Kodi treats the pipe suffix
    # as URL/header options, and several PlexBridge/Plexio/CDN links fail to
    # open when an unknown ids option is added after the file URL. The playback
    # ListItem still carries IMDb/TMDb/TVDb via InfoTag, UniqueIDs and window
    # properties for a4k/subtitle addons.
    if lower.startswith(('http://', 'https://', 'ftp://', 'smb://', 'nfs://', 'dav://', 'davs://', 'file://')):
        return url
    if lower.startswith(('plugin://', 'magnet:')) or '|ids=' in lower or '&ids=' in lower:
        return url
    ids = _ids_from_playback_ctx(ctx)
    payload = {}
    if ids.get('tmdb_id'):
        try:
            payload['tmdb'] = int(str(ids.get('tmdb_id')))
        except Exception:
            payload['tmdb'] = str(ids.get('tmdb_id'))
    if ids.get('imdb_id'):
        payload['imdb'] = str(ids.get('imdb_id'))
    if ids.get('tvdb_id'):
        try:
            payload['tvdb'] = int(str(ids.get('tvdb_id')))
        except Exception:
            payload['tvdb'] = str(ids.get('tvdb_id'))
    try:
        if ctx.get('season') not in (None, '', '0', 0):
            payload['season'] = int(ctx.get('season') or 0)
        if ctx.get('episode') not in (None, '', '0', 0):
            payload['episode'] = int(ctx.get('episode') or 0)
    except Exception:
        pass
    if not payload.get('imdb'):
        return url
    marker = 'ids=' + json.dumps(payload, separators=(',', ':'), ensure_ascii=False)
    if '|' in url:
        base, opts = url.split('|', 1)
        return base + '|' + (opts + '&' if opts else '') + marker
    return url + '|' + marker


def _meta_with_seed_ids(meta, ids):
    """Expose resolved ids to stream target discovery without changing UI meta."""
    out = dict(meta or {})
    ids = ids or {}
    external = dict(out.get('externalIds') or {}) if isinstance(out.get('externalIds') or {}, dict) else {}
    for src, external_key, camel_key in (
        ('imdb_id', 'imdb', 'imdbId'),
        ('tmdb_id', 'tmdb', 'tmdbId'),
        ('tvdb_id', 'tvdb', 'tvdbId'),
    ):
        val = str(ids.get(src) or '').strip()
        if not val:
            continue
        out.setdefault(src, val)
        out.setdefault(camel_key, val)
        external.setdefault(external_key, val)
    if external:
        out['externalIds'] = external
    return out


def _local_resume_lookup(media_type, canonical_id, video_id='', season=None, episode=None):
    "(seconds, percent) from Nuvio Hub's local progress DB, else (0.0, 0.0).\n\n    v3.9.153: playback launched from TMDb Helper's own lists reaches\n    _auto_play_first_* with resume 0 because TMDbH cannot know Nuvio Hub's\n    saved positions. Continue-Watching data already lives in\n    playback_store — look the item up so \"\u0627\u0633\u062a\u0643\u0645\u0627\u0644 \u0627\u0644\u0645\u0634\u0627\u0647\u062f\u0629\" works no matter\n    which side started playback. Finished items (>=95%) and tiny positions\n    (<=30s) return zero so fresh plays stay fresh.\n    "
    def _n(v):
        t = str(v).strip() if v is not None else ''
        return str(int(t)) if t.isdigit() else t
    want_mt = 'series' if _is_series_media(media_type) else str(media_type or 'movie')
    # Fast indexed lookup first. This avoids loading and scanning up to 500
    # continue-watching rows on every TMDb Helper handoff.
    try:
        ids = extract_ids({'id': canonical_id or ''}) or {}
        row = playback_store.find_resume_entry(
            media_type=want_mt,
            canonical_id=canonical_id or video_id or '',
            tmdb_id=ids.get('tmdb_id') or '',
            imdb_id=ids.get('imdb_id') or '',
            tvdb_id=ids.get('tvdb_id') or '',
            season=season, episode=episode,
        )
        if row:
            pos = float(row.get('position') or 0.0)
            dur = float(row.get('duration') or 0.0)
            pct = float(row.get('percent') or 0.0)
            if pct <= 0.0 and dur > 0:
                pct = pos / dur * 100.0
            if pos > 30.0 and (pct <= 0.0 or pct < 95.0):
                return pos, pct
            return 0.0, 0.0
    except Exception:
        pass

    # Compatibility fallback for old/pre-migration rows that do not yet carry
    # indexed external IDs. It only runs after the fast path misses.
    try:
        rows = playback_store.list_continue_items(limit=500) or []
    except Exception:
        return 0.0, 0.0
    cid, vid = _n(canonical_id), _n(video_id)
    sn, ep = _n(season), _n(episode)
    for r in rows:
        try:
            if str(r.get('media_type') or '') != want_mt:
                continue
            if not ((cid and _n(r.get('canonical_id')) == cid) or (vid and _n(r.get('video_id')) == vid)):
                continue
            if sn and _n(r.get('season')) != sn:
                continue
            if ep and _n(r.get('episode')) != ep:
                continue
            pos = float(r.get('position') or 0.0)
            dur = float(r.get('duration') or 0.0)
            pct = float(r.get('percent') or 0.0)
            if pct <= 0.0 and dur > 0:
                pct = pos / dur * 100.0
            if pos > 30.0 and (pct <= 0.0 or pct < 95.0):
                return pos, pct
            return 0.0, 0.0
        except Exception:
            continue
    return 0.0, 0.0


def _auto_play_first_movie(canonical_id, title='', seed_ids=None, preferred_provider_name='', resume_seconds=0.0, resume_percent=0.0, source_provider_id='', source_mode='', pick_dialog=False):
    from .frontend_bridge import legacy_streams
    return legacy_streams(media_type='movie', **locals())
    try:
        if float(resume_seconds or 0) <= 1.0 and float(resume_percent or 0) <= 1.0:
            _rs, _rp = _local_resume_lookup('movie', canonical_id)
            if _rs > 1.0 or _rp > 1.0:
                resume_seconds, resume_percent = _rs, _rp
    except Exception:
        pass
    providers = _provider_order_for_id_with_context('movie', canonical_id, source_provider_id=source_provider_id)
    best_meta = _best_meta_for_item('movie', canonical_id, providers, source_provider_id=source_provider_id)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, 'movie')
    art = _resolve_meta_art(providers[0] if providers else {}, 'movie', best_meta, fallback_art=provider_fb)
    art = _prefer_item_art(art, best_meta, 'movie', fallback_art=provider_fb)
    bg = _content_background(art, provider_fb)
    ids = _merge_seed_ids(extract_ids(best_meta), seed_ids or _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, 'movie', meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    entries = []
    targets_all = _prioritize_provider_targets(list(_stream_provider_targets('movie', canonical_id, meta=stream_meta)), preferred_provider_name=preferred_provider_name)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    def _fetch(t):
        return _fetch_stream_payload(t, 'movie')

    for target, data in run_parallel(_fetch, targets):
        if isinstance(data, Exception) or not data:
            continue
        p, rid = target
        _append_stream_entries_from_data(entries, data, p, rid, 'movie', canonical_id, best_meta, art, bg, ids, title=title, resume_seconds=resume_seconds, resume_percent=resume_percent)
    if not entries and fallback_targets:
        for target, data in run_parallel(_fetch, fallback_targets):
            if isinstance(data, Exception) or not data:
                continue
            p, rid = target
            _append_stream_entries_from_data(entries, data, p, rid, 'movie', canonical_id, best_meta, art, bg, ids, title=title, resume_seconds=resume_seconds, resume_percent=resume_percent)
    if not entries:
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        error(tr('No playback links were found'))
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type='movie', canonical_id=canonical_id)
    if pick_dialog:
        try:
            items = []
            for e in entries:
                li = xbmcgui.ListItem(e.get('name') or e.get('stream_title') or '?')
                try:
                    li.setLabel2(_entry_second_line(e))
                    _p = art.get('poster') or ''
                    if _p:
                        li.setArt({'icon': _p, 'thumb': _p, 'poster': _p})
                except Exception:
                    pass
                items.append(li)
            choice = xbmcgui.Dialog().select(tr('Choose add-on'), items, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(tr('Choose add-on'), [e.get('name') or '?' for e in entries])
        if choice < 0:
            _clear_tmdbh_transient()
            _clear_source_transient_props(clear_global=True)
            if HANDLE >= 0:
                try:
                    xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
                except Exception:
                    pass
            return
        return play(entries[choice]['stream_key'], resume_seconds=resume_seconds, resume_percent=resume_percent)
    return play(entries[0]['stream_key'], resume_seconds=resume_seconds, resume_percent=resume_percent)


def _auto_play_first_episode(canonical_id, video_id, season, episode, title='', seed_ids=None, preferred_provider_name='', resume_seconds=0.0, resume_percent=0.0, source_provider_id='', source_mode='', pick_dialog=False):
    from .frontend_bridge import legacy_streams
    return legacy_streams(media_type='series', **locals())
    try:
        if float(resume_seconds or 0) <= 1.0 and float(resume_percent or 0) <= 1.0:
            _rs, _rp = _local_resume_lookup('series', canonical_id, video_id, season, episode)
            if _rs > 1.0 or _rp > 1.0:
                resume_seconds, resume_percent = _rs, _rp
    except Exception:
        pass
    providers = _provider_order_for_id_with_context('series', canonical_id, source_provider_id=source_provider_id)
    best_meta = _best_meta_for_item('series', canonical_id, providers, source_provider_id=source_provider_id)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, 'series')
    art = _resolve_meta_art(providers[0] if providers else {}, 'series', best_meta, fallback_art=provider_fb)
    art = _prefer_item_art(art, best_meta, 'series', fallback_art=provider_fb)
    bg = _content_background(art, provider_fb)
    ids = _merge_seed_ids(extract_ids(best_meta), seed_ids or _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, 'series', meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    entries = []
    request_id = video_id or ('%s:%s:%s' % (canonical_id, season, episode))
    targets_all = _prioritize_provider_targets(list(_stream_provider_targets('series', canonical_id, meta=stream_meta, season=season, episode=episode)), preferred_provider_name=preferred_provider_name)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    def _fetch(t):
        return _fetch_stream_payload(t, 'series')

    for target, data in run_parallel(_fetch, targets):
        if isinstance(data, Exception) or not data:
            continue
        p, rid = target
        _append_stream_entries_from_data(entries, data, p, rid, 'series', canonical_id, best_meta, art, bg, ids, title=title, video_id=video_id, season=season, episode=episode, resume_seconds=resume_seconds, resume_percent=resume_percent)
    if not entries and fallback_targets:
        for target, data in run_parallel(_fetch, fallback_targets):
            if isinstance(data, Exception) or not data:
                continue
            p, rid = target
            _append_stream_entries_from_data(entries, data, p, rid, 'series', canonical_id, best_meta, art, bg, ids, title=title, video_id=video_id, season=season, episode=episode, resume_seconds=resume_seconds, resume_percent=resume_percent)
    if not entries:
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        error(tr('No playback links were found'))
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type='series', canonical_id=canonical_id, video_id=video_id)
    if pick_dialog:
        try:
            items = []
            for e in entries:
                li = xbmcgui.ListItem(e.get('name') or e.get('stream_title') or '?')
                try:
                    li.setLabel2(_entry_second_line(e))
                    _p = art.get('poster') or ''
                    if _p:
                        li.setArt({'icon': _p, 'thumb': _p, 'poster': _p})
                except Exception:
                    pass
                items.append(li)
            choice = xbmcgui.Dialog().select(tr('Choose add-on'), items, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(tr('Choose add-on'), [e.get('name') or '?' for e in entries])
        if choice < 0:
            _clear_tmdbh_transient()
            _clear_source_transient_props(clear_global=True)
            if HANDLE >= 0:
                try:
                    xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
                except Exception:
                    pass
            return
        return play(entries[choice]['stream_key'], resume_seconds=resume_seconds, resume_percent=resume_percent)
    return play(entries[0]['stream_key'], resume_seconds=resume_seconds, resume_percent=resume_percent)


def _parse_canonical_ids(canonical_id):
    """Extract tmdb/imdb/tvdb from a canonical id like 'tmdb:123', 'imdb:tt123',
    'tvdb:456', plain 'tt0000123', or unknown text."""
    cid = str(canonical_id or '').strip()
    if cid.startswith('tmdb:'):
        return {'tmdb_id': cid.split(':', 1)[1], 'imdb_id': '', 'tvdb_id': ''}
    if cid.startswith('imdb:'):
        tail = cid.split(':', 1)[1].strip()
        if tail.startswith('tt') and tail[2:].isdigit():
            return {'tmdb_id': '', 'imdb_id': tail, 'tvdb_id': ''}
        if tail.isdigit():
            return {'tmdb_id': '', 'imdb_id': 'tt%s' % tail, 'tvdb_id': ''}
    if cid.startswith('tvdb:'):
        tail = cid.split(':', 1)[1].strip()
        if tail.isdigit():
            return {'tmdb_id': '', 'imdb_id': '', 'tvdb_id': tail}
    if cid.startswith('tt') and cid[2:].isdigit():
        return {'tmdb_id': '', 'imdb_id': cid, 'tvdb_id': ''}
    return {'tmdb_id': '', 'imdb_id': '', 'tvdb_id': ''}


def _virtual_meta_override(target_key, media_type, seed_meta):
    try:
        from . import meta_source as _meta_source
        return _meta_source.override_virtual_meta(target_key, media_type, seed_meta or {}) or (seed_meta or {})
    except Exception:
        return seed_meta or {}



def _pov_parse_ts(value):
    text = str(value or '').strip()
    if not text:
        return None
    try:
        return int(float(text))
    except Exception:
        pass
    try:
        import datetime as _dt
        clean = text.replace('Z', '+00:00')
        if clean.endswith('+00:00') and '.' in clean:
            # fromisoformat accepts fractional seconds + offset on Kodi 20/21.
            pass
        dt = _dt.datetime.fromisoformat(clean)
        if dt.tzinfo:
            return int(dt.timestamp())
        return int(time.mktime(dt.timetuple()))
    except Exception:
        pass
    for fmt in ('%Y-%m-%dT%H:%M:%S.000Z', '%Y-%m-%dT%H:%M:%SZ', '%Y-%m-%d %H:%M:%S'):
        try:
            return int(time.mktime(time.strptime(text, fmt)))
        except Exception:
            continue
    return None


def _pov_profile_dir():
    try:
        return xbmcvfs.translatePath('special://profile/addon_data/plugin.video.pov/')
    except Exception:
        return ''


def _pov_setting(setting_id, default=''):
    try:
        import xml.etree.ElementTree as _ET
        settings_path = os.path.join(_pov_profile_dir(), 'settings.xml')
        if not os.path.exists(settings_path):
            return default
        root = _ET.parse(settings_path).getroot()
        for node in root.findall('setting'):
            if node.get('id') == setting_id:
                return node.get('value') or node.text or default
    except Exception:
        pass
    return default


def _pov_progress_db_paths():
    base = _pov_profile_dir()
    if not base:
        return []
    watched_ind = str(_pov_setting('watched_indicators', '0') or '0')
    mapping = {
        '0': [('POV', 'watched.db')],
        '1': [('POV Trakt', 'traktcache4.db')],
        '2': [('POV MDBList', 'mdblcache.db')],
    }
    ordered = list(mapping.get(watched_ind, mapping['0']))
    # Also scan the other POV progress stores as a fallback. Some builds keep
    # local progress in watched.db even when the watched provider is Trakt, and
    # this mirrors POV's practical cache behavior without needing Trakt auth.
    for item in [('POV', 'watched.db'), ('POV Trakt', 'traktcache4.db'), ('POV MDBList', 'mdblcache.db')]:
        if item not in ordered:
            ordered.append(item)
    out = []
    for label, name in ordered:
        path = os.path.join(base, name)
        if os.path.exists(path):
            out.append((label, path))
    return out


def _import_pov_progress_if_available(limit=250, force=False):
    """Mirror POV's in-progress cache into Nuvio Hub Continue Watching.

    POV stores resume rows in SQLite (`watched.db`, `traktcache4.db`, or
    `mdblcache.db` depending on its watched provider). Reading those local rows
    makes Nuvio Hub behave like POV on the home page: no separate Nuvio Hub Trakt
    activation is required, and widgets get ordinary playable resume items.
    """
    try:
        win = xbmcgui.Window(WINDOW_ID)
        now = int(time.time())
        if not force:
            try:
                last = int(win.getProperty('nuviohub.pov_progress_import_ts') or '0')
            except Exception:
                last = 0
            if last and now - last < 180:
                return 0
        try:
            win.setProperty('nuviohub.pov_progress_import_ts', str(now))
        except Exception:
            pass
    except Exception:
        pass

    try:
        import sqlite3 as _sqlite3
    except Exception:
        return 0

    imported = 0
    seen = set()
    for provider_label, db_path in _pov_progress_db_paths():
        try:
            conn = _sqlite3.connect(db_path, timeout=2)
            cur = conn.cursor()
            cur.execute("""
                SELECT db_type, media_id, season, episode, resume_point, curr_time, last_played, title
                FROM progress
                WHERE db_type IN ('movie','episode')
            """)
            rows = cur.fetchall()
            conn.close()
        except Exception:
            continue
        # Sort in Python so numeric and ISO timestamps both work.
        try:
            rows.sort(key=lambda r: _pov_parse_ts(r[6]) or 0, reverse=True)
        except Exception:
            pass
        for db_type, media_id, season, episode, resume_point, curr_time, last_played, title in rows[:int(limit or 250)]:
            try:
                tmdb_id = str(media_id or '').strip()
                if not tmdb_id:
                    continue
                try:
                    percent = float(resume_point or 0.0)
                except Exception:
                    percent = 0.0
                if not (percent > 1.0 and percent < 95.0):
                    continue
                canonical = tmdb_id if tmdb_id.startswith('tmdb:') else ('tmdb:%s' % tmdb_id)
                if db_type == 'episode':
                    mt = 'series'
                    season_i = int(season or 0)
                    episode_i = int(episode or 0)
                    if season_i <= 0:
                        continue
                    video_id = '%s:%s:%s' % (canonical, season_i, episode_i)
                else:
                    mt = 'movie'
                    season_i = None
                    episode_i = None
                    video_id = canonical
                key = (mt, canonical, video_id)
                if key in seen:
                    continue
                seen.add(key)
                try:
                    position = float(curr_time or 0.0)
                except Exception:
                    position = 0.0
                duration = 0.0
                if position > 1.0 and percent > 1.0:
                    duration = max(position + 1.0, position * 100.0 / percent)
                updated_at = _pov_parse_ts(last_played)
                playback_store.upsert_entry(
                    mt, canonical, video_id, title or canonical, provider_label,
                    '', '', '', season_i, episode_i, position, duration, percent,
                    '', 'pov_progress', ext_updated_at=updated_at,
                )
                imported += 1
            except Exception:
                continue
    if imported:
        try:
            xbmc.log('[NuvioHub] imported %d POV progress rows' % imported, xbmc.LOGINFO)
        except Exception:
            pass
    return imported

def _cw_target_key(row):
    mt = (row.get('media_type') or '').lower()
    return 'virtual.continue.series' if mt in ('series', 'anime', 'show', 'tv') or (row.get('season') and row.get('episode') is not None) else 'virtual.continue.movie'


def _fav_target_key(row):
    """Virtual metadata target for Favorites / Watchlist rows.

    Favorites are not tied to one concrete Stremio provider, so they need the
    same virtual metadata mapping used by Continue Watching and Collection.
    This lets users pick TMDb Helper / Cinemeta / AIOMetadata specifically for
    favorite widgets without affecting stream provider order.
    """
    mt = (row.get('media_type') or '').lower()
    return 'virtual.favorites.series' if mt in ('series', 'anime', 'show', 'tv') else 'virtual.favorites.movie'


def _lazy_fill_row_art(row):
    """Fill Continue Watching artwork using the configured metadata target."""
    target_key = _cw_target_key(row)
    source_id = 'auto'
    try:
        from . import meta_source as _meta_source
        source_id = (_meta_source.get_meta_source_for(target_key) or 'auto')
    except Exception:
        source_id = 'auto'
    if source_id == 'native':
        return row

    explicit_source = source_id not in ('', 'auto')
    try:
        tokenized_art = _row_poster_looks_provider_tokenized(row.get('poster')) or _row_poster_looks_provider_tokenized(row.get('background'))
    except Exception:
        tokenized_art = False
    needs_fill = tokenized_art or not (row.get('poster') and row.get('background') and row.get('clearlogo'))
    seed_meta = {
        'id': row.get('canonical_id') or '',
        'name': row.get('title') or row.get('canonical_id') or '',
        'title': row.get('title') or row.get('canonical_id') or '',
        'poster': row.get('poster') or '',
        'background': row.get('background') or '',
        'logo': row.get('clearlogo') or '',
        'clearlogo': row.get('clearlogo') or '',
    }
    if not needs_fill and not explicit_source:
        return row

    ids = _parse_canonical_ids(row.get('canonical_id'))
    tmdb_id = ids.get('tmdb_id') or ''
    imdb_id = ids.get('imdb_id') or ''
    media_kind = 'series' if row.get('media_type') in ('series', 'anime', 'tv', 'show') or (row.get('season') and row.get('episode') is not None) else 'movie'
    if (tmdb_id or imdb_id) and not explicit_source:
        media_type = 'tv' if media_kind == 'series' else 'movie'
        try:
            bundle = _tmdb_art_db.get_art_bundle_from_db(
                tmdb_id=tmdb_id, media_type=media_type, imdb_id=imdb_id, title=row.get('title') or ''
            ) or {}
        except Exception:
            bundle = {}
        # Bug fix: previously this skipped TMDb posters when the user had
        # picked "محلي فقط" globally — but Continue Watching rows from Trakt
        # have no local artwork to begin with, so the row stayed blank
        # forever. CW is a virtual surface; in auto mode we allow remote fill.
        if not seed_meta.get('poster'):
            seed_meta['poster'] = bundle.get('poster') or ''
        if not seed_meta.get('background'):
            seed_meta['background'] = bundle.get('fanart') or bundle.get('landscape') or ''
        if not seed_meta.get('clearlogo'):
            seed_meta['clearlogo'] = bundle.get('clearlogo') or ''
            seed_meta['logo'] = seed_meta['clearlogo'] or ''
        # Hard fallback only in auto mode. If the user explicitly chose
        # TMDb Helper/Trakt/Cinemeta, do not bypass that choice with API art.
        if not (seed_meta.get('poster') and seed_meta.get('background')):
            try:
                direct_bundle = _tmdb_direct.art_for(
                    tmdb_id=tmdb_id, imdb_id=imdb_id,
                    media_type=media_type, title=row.get('title') or '',
                ) or {}
                if not seed_meta.get('poster'):
                    seed_meta['poster'] = direct_bundle.get('poster') or ''
                if not seed_meta.get('background'):
                    seed_meta['background'] = direct_bundle.get('fanart') or direct_bundle.get('landscape') or ''
                if not seed_meta.get('clearlogo'):
                    seed_meta['clearlogo'] = direct_bundle.get('clearlogo') or ''
                    seed_meta['logo'] = seed_meta['clearlogo'] or ''
            except Exception:
                pass

    meta = _virtual_meta_override(target_key, media_kind, seed_meta)
    try:
        _meta_mem_put(media_kind, row.get('canonical_id') or '', meta, source_provider_id=target_key)
    except Exception:
        pass
    if explicit_source:
        poster = meta.get('poster') or ''
        background = meta.get('background') or meta.get('fanart') or meta.get('landscape') or ''
        clearlogo = meta.get('clearlogo') or ''
    else:
        poster = meta.get('poster') or seed_meta.get('poster') or ''
        background = meta.get('background') or meta.get('fanart') or meta.get('landscape') or seed_meta.get('background') or ''
        clearlogo = meta.get('clearlogo') or seed_meta.get('clearlogo') or ''
    # Last pass for virtual rows: if the selected meta source still didn't
    # provide a movie/show fanart, use the same resolver shared by Next Up and
    # Favorites. This keeps Continue Watching from falling back to the addon
    # background or poster when a real title fanart exists.
    if not explicit_source and (not background or tokenized_art):
        try:
            resolved_art = _resolve_row_art(dict(row, poster=poster, background=background, clearlogo=clearlogo)) or {}
            poster = poster or resolved_art.get('poster') or resolved_art.get('thumb') or ''
            background = resolved_art.get('fanart') or resolved_art.get('landscape') or background or ''
            clearlogo = clearlogo or resolved_art.get('clearlogo') or ''
        except Exception:
            pass
    if poster or background or clearlogo:
        try:
            playback_store.update_art(
                row.get('media_type'), row.get('canonical_id'), row.get('video_id'),
                poster, background, clearlogo,
            )
        except Exception:
            pass
        row = dict(row)
        row['poster'] = poster
        row['background'] = background
        row['clearlogo'] = clearlogo
    return row


def _continue_item_source_path(row):
    is_episode = _continue_row_is_episode(row)
    # Bug fix (3.7.91): pass resume_percent as a fallback. Trakt-imported rows
    # often have position=0 because Trakt's /sync/playback didn't return
    # runtime (now fetched via ?extended=full, but legacy DB rows may still
    # have position=0 with a valid percent). The companion resume
    # coordinator uses percent × player.getTotalTime() to compute the
    # resume target if seconds are missing.
    try:
        position_raw = row.get('position')
        position_val = float(position_raw) if position_raw not in (None, '') else 0.0
    except Exception:
        position_val = 0.0
    try:
        percent_raw = row.get('percent')
        percent_val = float(percent_raw) if percent_raw not in (None, '') else 0.0
    except Exception:
        percent_val = 0.0
    common = {
        'title': row.get('title') or row.get('canonical_id') or '',
        'resume_seconds': position_val if position_val > 1.0 else 0,
        'resume_percent': ('%.2f' % percent_val) if (position_val <= 1.0 and percent_val > 1.0 and percent_val < 95.0) else '',
        'preferred_provider_name': row.get('provider_name') or '',
        'source_provider_id': _cw_target_key(row),
    }
    if row.get('native_server_id') and row.get('native_item_id'):
        try:
            common['ui_seed_key'] = cache_store.put('ui_seed', {
                'native_server_id': str(row.get('native_server_id')),
                'native_item_id': str(row.get('native_item_id')),
                'ui_poster': row.get('poster') or '',
                'ui_fanart': row.get('background') or '',
                'ui_clearlogo': row.get('clearlogo') or '',
            }, ttl_hours=24)
        except Exception:
            pass
    if is_episode:
        return build_url(action='episode_streams', canonical_id=row.get('canonical_id'), video_id=row.get('video_id'), season=row.get('season'), episode=row.get('episode'), media_type=row.get('media_type') or 'series', **common)
    return build_url(action='streams', media_type=row.get('media_type'), canonical_id=row.get('canonical_id'), **common)


def cw_resume(media_type='', canonical_id='', video_id='', season='', episode='', title='', position='0', resume_percent='', provider_name='', direct='0', source_provider_id='', ui_poster='', ui_fanart='', ui_clearlogo='', studio='', ui_seed_key=''):
    target_media_type = media_type or ('series' if season not in (None, '', '0', 0) and episode not in (None, '', '0', 0) else 'movie')
    is_direct = str(direct or '').strip().lower() in ('1', 'true', 'yes', 'on')
    if is_direct:
        if target_media_type in ('series', 'tv', 'show', 'anime') or (season not in (None, '', '0', 0) and episode not in (None, '', '0', 0)):
            return _auto_play_first_episode(canonical_id, video_id or canonical_id, season, episode, title=title or canonical_id, resume_seconds=position or '0', resume_percent=resume_percent or '', preferred_provider_name=provider_name or '', source_provider_id=source_provider_id or '')
        return _auto_play_first_movie(canonical_id, title=title or canonical_id, resume_seconds=position or '0', resume_percent=resume_percent or '', preferred_provider_name=provider_name or '', source_provider_id=source_provider_id or '')
    # Seed the picker hero with the Continue Watching row's own art + studio so
    # fanart / clearlogo / studio appear immediately when resuming from CW —
    # not just when opening from a catalogue click.
    ui_seed = _ui_seed_from_route(
        ui_poster=ui_poster, ui_fanart=ui_fanart,
        ui_clearlogo=ui_clearlogo, ui_seed_key=ui_seed_key)
    if studio:
        ui_seed['studio'] = studio
    # Continue Watching must honor Nuvio Hub's own resume position. Redirecting
    # here to TMDb Helper discards our stored resume_seconds and the item starts
    # from the beginning. Keep this path inside Nuvio Hub; users still have an
    # explicit player chooser in the context menu when they want TMDb Helper.
    return _dispatch_nuviohub_play(
        media_type=target_media_type,
        canonical_id=canonical_id,
        title=title or canonical_id,
        video_id=video_id,
        season=season,
        episode=episode,
        resume_seconds=position or '0',
        resume_percent=resume_percent or '',
        preferred_provider_name=provider_name or '',
        source_provider_id=source_provider_id or '',
        ui_seed=ui_seed or None,
    )


def cw_play_from_start(media_type='', canonical_id='', video_id='', season='', episode='', title='', provider_name='', source_provider_id=''):
    # v3.9.39: route through cw_resume with direct='0' so the source
    # picker appears, matching the main click action's behaviour.
    return cw_resume(
        media_type=media_type,
        canonical_id=canonical_id,
        video_id=video_id,
        season=season,
        episode=episode,
        title=title,
        position='0',
        provider_name=provider_name,
        direct='0',
        source_provider_id=source_provider_id,
    )


def _continue_row_is_episode(row):
    try:
        return int(row.get('season') or 0) > 0 and int(row.get('episode') or 0) >= 0
    except Exception:
        return False


def _continue_item_from_start_path(row):
    row = dict(row or {})
    row['position'] = 0
    return _continue_item_source_path(row)



# Pure digits are only id-like at 5+ chars: '180', '300', '1917' are real
# movie titles; '28739' is a database id. Uppercase alnum mixes (JSGB4701)
# are ids at 4+ chars.
_CW_CODE_RE = re.compile(r'^(?:(?=[A-Z0-9]*[A-Z])[A-Z0-9]{4,}|\d{5,})$')


def _cw_looks_like_code(text):
    """True for id-like 'titles' (JSGB4701, 28739) that must never be shown."""
    t = str(text or '').strip()
    return (not t) or bool(_CW_CODE_RE.match(t))


def _cw_show_name(row):
    """Best-effort SHOW name for a continue-watching episode row — cached only.

    v3.9.240: the store's `title` held the EPISODE name ("Episode 3"), and the
    renderer then set info['tvshowtitle'] = title — so skins displayed the
    episode title as the SHOW title. Rows whose title was empty fell back to
    the raw canonical_id, which is how codes like 'JSGB4701' / '28739' ended up
    on screen. Derivation order: the stored show_title (new writes), then TMDb
    Helper's local DB, then Nuvio Hub's cached TMDb art/meta — never the network.
    """
    show = str(row.get('show_title') or '').strip()
    if show and not _cw_looks_like_code(show):
        return show
    tmdb_id = str(row.get('show_tmdb_id') or row.get('tmdb_id') or '').strip()
    imdb_id = str(row.get('imdb_id') or '').strip()
    if tmdb_id or imdb_id:
        try:
            bundle = _tmdb_art_db.get_meta_bundle_from_db(
                tmdb_id=tmdb_id, imdb_id=imdb_id, media_type='tv') or {}
            name = str(bundle.get('title') or bundle.get('name') or '').strip()
            if name and not _cw_looks_like_code(name):
                return name
        except Exception:
            pass
    return ''


def _cw_episode_poster(row):
    """SHOW poster for an episode row when the cache has one — cached only.

    The stored poster is usually the EPISODE STILL (a random frame), which is
    what made the shelf look like a wall of screenshots. The still stays as
    landscape; the portrait poster becomes the show poster when available.
    """
    tmdb_id = str(row.get('show_tmdb_id') or row.get('tmdb_id') or '').strip()
    imdb_id = str(row.get('imdb_id') or '').strip()
    if not (tmdb_id or imdb_id):
        return ''
    try:
        bundle = _tmdb_art_db.get_art_bundle_from_db(
            tmdb_id=tmdb_id, imdb_id=imdb_id, media_type='tv') or {}
        if bundle.get('poster'):
            return bundle['poster']
    except Exception:
        pass
    try:
        bundle = _tmdb_direct.art_cached_only(
            tmdb_id=tmdb_id, imdb_id=imdb_id, media_type='tv') or {}
        return bundle.get('poster') or ''
    except Exception:
        return ''


def _apply_continue_art_style(art):
    """v4.3.0: user-selectable Continue Watching artwork style.

    'poster' (default) keeps the portrait card; 'landscape' promotes the
    wide art into thumb/icon so Arctic Fuse widgets and the in-addon section
    render banner-style cards. Every original key stays present, so nothing
    downstream (resume, context menus, info views) loses data.
    """
    try:
        style = (_setting('continue_art_style', 'poster') or 'poster').strip().lower()
    except Exception:
        style = 'poster'
    if style in ('landscape', 'banner', '1'):
        wide = art.get('landscape') or art.get('fanart') or art.get('poster') or ''
        if wide:
            art['thumb'] = wide
            art['icon'] = wide
            art['banner'] = wide
    else:
        if art.get('poster'):
            art['thumb'] = art['poster']
    return art


def _home_payload(limit=12):
    """Cinematic home payload from local SQLite data only.

    The first eight visible cards are enriched from TMDb Helper's read-only
    database.  No TMDb/fanart HTTP request is started by opening Home.
    """
    rows_out = []
    try:
        raw = playback_store.list_continue_items(limit=limit)
    except Exception:
        raw = []
    def _clock(seconds):
        try:
            seconds = max(0, int(float(seconds or 0)))
        except Exception:
            seconds = 0
        return '%d:%02d' % (seconds // 60, seconds % 60)

    def _runtime_label(value, duration=0):
        # playback.db stores seconds, including short videos and long movies.
        # Only helper metadata needs the legacy unit normalization below.
        if value in (None, '', 0, '0'):
            try:
                minutes = int(float(duration or 0) / 60.0)
            except (TypeError, ValueError, OverflowError):
                minutes = 0
            return (tr('%d min') % minutes) if minutes > 0 else ''
        raw_value = value if value not in (None, '') else duration
        try:
            number = int(float(raw_value or 0))
        except Exception:
            number = 0
        if number > 10000:  # milliseconds
            number = int(number / 60000.0)
        elif number > 600:  # seconds
            number = int(number / 60.0)
        return (tr('%d min') % number) if number > 0 else ''

    for index, row in enumerate(raw):
        is_episode = _continue_row_is_episode(row)
        title = str(row.get('title') or '').strip() or 'Unknown'
        season = row.get('season') if row.get('season') is not None else ''
        episode = row.get('episode') or ''
        subtitle = ''
        if is_episode and season != '' and episode:
            subtitle = 'S%s • E%s' % (season, episode)
        percent = 0
        try:
            percent = int(float(row.get('percent') or 0))
        except Exception:
            percent = 0
        helper_type = 'tv' if is_episode or str(row.get('media_type') or '').lower() in ('series', 'tv', 'show', 'anime') else 'movie'
        helper_tmdb = str(row.get('show_tmdb_id') or row.get('tmdb_id') or '').strip()
        helper_imdb = str(row.get('imdb_id') or '').strip()
        helper = {}
        if index < 8 and (helper_tmdb or helper_imdb or title):
            try:
                helper = _tmdb_art_db.get_meta_bundle_from_db(
                    tmdb_id=helper_tmdb, imdb_id=helper_imdb,
                    media_type=helper_type, title=title) or {}
            except Exception:
                helper = {}
        elif helper_tmdb or helper_imdb:
            try:
                helper = _tmdb_art_db.get_art_bundle_from_db(
                    tmdb_id=helper_tmdb, imdb_id=helper_imdb,
                    media_type=helper_type, title=title) or {}
            except Exception:
                helper = {}

        helper_title = str(helper.get('title') or helper.get('name') or '').strip()
        display_title = helper_title or title
        episode_name = title if is_episode and helper_title and title != helper_title else ''
        if is_episode and season != '' and episode:
            subtitle = 'S%s • E%s' % (season, episode)
            if episode_name:
                subtitle = '%s  •  %s' % (subtitle, episode_name)

        fanart = (helper.get('fanart') or helper.get('landscape') or
                  row.get('background') or row.get('landscape') or '')
        landscape = helper.get('landscape') or fanart
        poster = helper.get('poster') or row.get('poster') or ''
        clearlogo = helper.get('clearlogo') or helper.get('logo') or row.get('clearlogo') or ''
        plot = helper.get('plot') or helper.get('overview') or helper.get('description') or ''
        year = helper.get('year') or ''
        rating = helper.get('rating') or helper.get('imdbRating') or ''
        runtime_label = _runtime_label(helper.get('runtime'), row.get('duration'))
        kind_label = tr('Series') if helper_type == 'tv' else tr('Movie')
        meta_bits = [str(bit) for bit in (year, kind_label, runtime_label) if bit not in (None, '')]
        if rating not in (None, '', 0, 0.0):
            try:
                meta_bits.append('★ %.1f' % float(rating))
            except Exception:
                meta_bits.append('★ %s' % rating)

        # Reuse the established Continue Watching artwork policy, then prefer
        # its wide variant for this window's landscape rail.  The cinematic
        # layout must never stretch a portrait poster into a 16:9 card.
        home_art = _apply_continue_art_style({
            'thumb': poster,
            'poster': poster,
            'fanart': fanart,
            'landscape': landscape,
            'clearlogo': clearlogo,
        })

        _native_seed_key = ''
        if row.get('native_server_id') and row.get('native_item_id'):
            try:
                _native_seed_key = cache_store.put('ui_seed', {
                    'native_server_id': str(row.get('native_server_id')),
                    'native_item_id': str(row.get('native_item_id')),
                }, ttl_hours=24)
            except Exception:
                _native_seed_key = ''
        resume_path = build_url(
            action='cw_resume',
            media_type=row.get('media_type') or ('series' if is_episode else 'movie'),
            canonical_id=row.get('canonical_id') or '',
            video_id=row.get('video_id') or '',
            season=season, episode=episode,
            title=display_title,
            position=row.get('position') or 0,
            resume_percent=row.get('percent') or '',
            provider_name=row.get('provider_name') or '',
            direct='0',
            source_provider_id=_cw_target_key(row),
            ui_poster=poster,
            ui_fanart=fanart,
            ui_clearlogo=clearlogo,
            studio=row.get('studio') or '',
            ui_seed_key=_native_seed_key,
        )
        rows_out.append({
            'title': display_title,
            'subtitle': subtitle,
            'percent_label': ('%d%%' % percent) if percent > 0 else '',
            'percent_value': str(percent),
            'thumb': home_art.get('landscape') or home_art.get('fanart') or home_art.get('thumb') or poster,
            'poster': home_art.get('poster') or poster,
            'fanart': home_art.get('fanart') or fanart,
            'landscape': home_art.get('landscape') or landscape,
            'clearlogo': home_art.get('clearlogo') or clearlogo,
            'plot': plot,
            'meta_line': '  •  '.join(meta_bits),
            'resume_label': tr('Continue from %s') % _clock(row.get('position')),
            'resume_path': resume_path,
            'progress_key': [row.get('media_type') or '', row.get('canonical_id') or '', row.get('video_id') or ''],
            'target': {
                'media_type': row.get('media_type') or ('series' if is_episode else 'movie'),
                'canonical_id': row.get('canonical_id') or '', 'video_id': row.get('video_id') or '',
                'imdb_id': helper_imdb, 'tmdb_id': helper_tmdb, 'tvdb_id': row.get('tvdb_id') or '',
                'season': season, 'episode': episode, 'resume_seconds': row.get('position') or 0,
                'title': display_title,
            },
        })
    # Build Explore from the user's locally available catalogues.  Enumerate
    # providers/pins/folders once so Home remains as light as the classic
    # implementation even when several Stremio addons are linked.
    sections = [
        {'label': tr('Next episode'), 'path': build_url(action='nextup')},
    ]
    try:
        catalog_buckets = set(
            str(entry[2] or '') for entry in (_hub_catalog_entries() or [])
            if isinstance(entry, (list, tuple)) and len(entry) >= 3
        )
    except Exception:
        catalog_buckets = set()
    try:
        pin_buckets = set(str(row.get('bucket') or '') for row in (_load_catalog_pins() or []))
    except Exception:
        pin_buckets = set()
    try:
        folder_rows = list(_load_home_subfolders() or [])
    except Exception:
        folder_rows = []
    child_buckets = {}
    for folder_row in folder_rows:
        parent = str(folder_row.get('parent') or '')
        child = str(folder_row.get('bucket') or '')
        if parent and child:
            child_buckets.setdefault(parent, set()).add(child)

    for bucket_row in _home_bucket_defs(include_collection=False):
        bucket = str(bucket_row.get('bucket') or '')
        if not bucket:
            continue
        available = (
            bucket in catalog_buckets or
            bucket in pin_buckets or
            bool(child_buckets.get(bucket)) or
            bool(child_buckets.get(bucket, set()) & pin_buckets) or
            bucket.startswith('custom:')
        )
        if not available:
            continue
        title = (_custom_home_bucket_title(bucket) or _hub_bucket_title(bucket) or
                 bucket_row.get('title') or bucket)
        sections.append({
            'label': tr(title),
            'path': build_url(action='hub_section', bucket=bucket),
        })
        if len(sections) >= 8:
            break

    # Keep setup/management reachable when fewer media buckets are present.
    utilities = [
        {'label': tr('Add-ons'), 'path': build_url(action='providers')},
        {'label': tr('My accounts'), 'path': build_url(action='sync_accounts_menu')},
    ]
    for utility in utilities:
        if len(sections) >= 8:
            break
        sections.append(utility)
    nav = [
        # Already on Home: keep this button inert instead of closing the
        # cinematic window and exposing the classic fallback underneath it.
        {'label': tr('Home'), 'path': ''},
        {'label': tr('Movies'), 'path': build_url(action='hub_section', bucket='movies')},
        {'label': tr('Series'), 'path': build_url(action='hub_section', bucket='series')},
        {'label': tr('Anime'), 'path': build_url(action='hub_section', bucket='anime')},
        {'label': tr('Live'), 'path': build_url(action='hub_section', bucket='live')},
        {'label': tr('Search'), 'path': build_url(action='hub_search_menu')},
    ]
    return {'continue': rows_out, 'sections': sections, 'nav': nav}


def home_xml():
    from .frontend_bridge import open_home
    return open_home()


def continue_watching(page='0'):
    _set_render_section('continue')
    # POV-style bridge: pull local POV progress rows into Nuvio Hub before
    # rendering. This is SQLite-only and throttled, so it stays lightweight.
    try:
        _import_pov_progress_if_available()
    except Exception:
        pass
    # Keep the screen snappy: slice first, then enrich only the visible rows.
    all_rows = playback_store.list_continue_items(limit=500)
    page_num, _page_size, raw_rows, has_more = _page_slice(all_rows, page)
    rows = []
    for _row, _filled in run_parallel(_lazy_fill_row_art, raw_rows):
        rows.append(_filled if not isinstance(_filled, Exception) else _row)
    any_series = any(_continue_row_is_episode(r) for r in rows)
    any_movie = any(not _continue_row_is_episode(r) for r in rows)
    if any_series and not any_movie:
        content_type = 'episodes'
    elif any_movie and not any_series:
        content_type = 'movies'
    else:
        content_type = 'movies'

    for row in rows:
        is_episode = _continue_row_is_episode(row)
        title = row.get('title') or ''
        # Never show a raw id as a title (JSGB4701 / 28739 class of rows).
        if _cw_looks_like_code(title):
            title = _cw_show_name(row) if is_episode else ''
        if not title:
            title = 'Untitled' if not is_episode else ''
        _show = _cw_show_name(row) if is_episode else ''
        _ep_name = title if (is_episode and title and title != _show) else ''
        # The title that travels in resume/play URLs must be the CLEAN one:
        # routing the raw canonical_id back through cw_resume re-saved the
        # code into the store on every resume, re-poisoning the row forever.
        _url_title = (_show or title) if is_episode else title
        source_path = _continue_item_source_path(row)
        from_start_source_path = _continue_item_from_start_path(row)
        # v3.9.39: Continue Watching now opens the source picker by
        # default. Previously direct='1' auto-played the first/best
        # stream, skipping the picker entirely — the user wanted the
        # same source-selection experience here as elsewhere in NuvioHub.
        # The "Play from start" context entry below keeps the resume
        # position at zero but also goes through the picker now.
        _native_seed_key = ''
        if row.get('native_server_id') and row.get('native_item_id'):
            try:
                _native_seed_key = cache_store.put('ui_seed', {
                    'native_server_id': str(row.get('native_server_id')),
                    'native_item_id': str(row.get('native_item_id')),
                }, ttl_hours=24)
            except Exception:
                _native_seed_key = ''
        resume_path = build_url(
            action='cw_resume',
            media_type=row.get('media_type') or ('series' if is_episode else 'movie'),
            canonical_id=row.get('canonical_id') or '',
            video_id=row.get('video_id') or '',
            season=row.get('season') or '',
            episode=row.get('episode') or '',
            title=_url_title or '',
            position=row.get('position') or 0,
            resume_percent=row.get('percent') or '',
            provider_name=row.get('provider_name') or '',
            direct='0',
            source_provider_id=_cw_target_key(row),
            ui_poster=row.get('poster') or '',
            ui_fanart=row.get('background') or '',
            ui_clearlogo=row.get('clearlogo') or '',
            studio=row.get('studio') or '',
            ui_seed_key=_native_seed_key,
        )
        play_from_start_path = build_url(
            action='cw_play_from_start',
            media_type=row.get('media_type') or ('series' if is_episode else 'movie'),
            canonical_id=row.get('canonical_id') or '',
            video_id=row.get('video_id') or '',
            season=row.get('season') or '',
            episode=row.get('episode') or '',
            title=_url_title or '',
            provider_name=row.get('provider_name') or '',
            direct='1',
        )
        row_ids = _merge_seed_ids(extract_ids({'id': row.get('canonical_id') or ''}), _get_tmdbh_seed_ids(row.get('canonical_id') or ''))
        # POV-style home/widget behavior: the row itself is a normal playable
        # item that resumes directly. Source picker remains in the context menu.
        # Returning folders here made skins/widgets try to play x-directory/normal.
        path, path_is_folder = resume_path, False
        if is_episode:
            _sxxeyy = 'S%02dE%02d' % (int(row.get('season') or 0), int(row.get('episode') or 0))
            # The SHOW leads the label; the episode name is secondary. Before
            # this, the label was the bare episode title ("Episode 3 — S05E03")
            # with no show name anywhere on the row.
            if _show:
                display_title = '%s — %s' % (_show, _sxxeyy)
            elif _ep_name:
                display_title = '%s — %s' % (_sxxeyy, _ep_name)
            else:
                display_title = _sxxeyy
            mediatype = 'episode'
        else:
            display_title = title
            mediatype = 'movie'

        percent = float(row.get('percent') or 0.0)
        position = float(row.get('position') or 0.0)
        duration = float(row.get('duration') or 0.0)
        info = {
            'title': display_title,
            'plot': '%.1f%% • %s' % (percent, row.get('provider_name') or ''),
            'mediatype': mediatype,
        }
        if is_episode:
            # tvshowtitle must be the SHOW, never the episode title — Arctic
            # Fuse renders it as the big header. Absent beats wrong.
            if _show:
                info['tvshowtitle'] = _show
            if _ep_name:
                info['plot'] = '%s\n%s' % (_ep_name, info['plot'])
            info['season'] = int(row.get('season') or 0)
            info['episode'] = int(row.get('episode') or 0)
        info['playcount'] = 0
        if duration > 0:
            info['duration'] = int(duration)
        # Surface rating + studio on the CW list item so skins that show them
        # (Arctic Fuse info views) can render the rating badge + studio logo.
        try:
            _cw_rating = float(row.get('rating') or 0)
            if _cw_rating > 0:
                info['rating'] = _cw_rating
        except Exception:
            pass
        if row.get('studio'):
            info['studio'] = row.get('studio')
        if duration > 0 and position > 0:
            info['resumetime'] = float(position)
            info['totaltime'] = float(duration)

        _row_poster = row.get('poster') or ''
        if is_episode:
            # Portrait slot gets the SHOW poster when cached; the episode
            # still (a random frame) only ever suits the landscape slot.
            _row_poster = _cw_episode_poster(row) or _row_poster
        _poster_art = _wrap_tokenized_url(_row_poster)
        _bg_art = _wrap_tokenized_url(row.get('background') or '') or addon_fanart()
        _logo_art = _wrap_tokenized_url(row.get('clearlogo') or '')
        art = {
            'thumb': _poster_art,
            'poster': _poster_art,
            'fanart': _bg_art,
            'landscape': _bg_art or _poster_art,
            'clearlogo': _logo_art,
        }
        if _logo_art:
            art['logo'] = _logo_art
            art['tvshow.clearlogo'] = _logo_art
        _apply_continue_art_style(art)

        properties = {}
        if not path_is_folder:
            if duration > 0 and position > 0:
                properties['ResumeTime'] = str(int(position))
                properties['TotalTime'] = str(int(duration))
            properties['IsPlayable'] = 'true'
            if percent:
                properties['WatchedProgress'] = str(int(percent))
                properties['PercentPlayed'] = str(int(percent))

        # row_ids already computed above (line ~4711); reuse it here.
        target_key = _cw_target_key(row)
        target_title = 'Continue Watching • Series/Anime' if target_key.endswith('series') else 'Continue Watching • Movies'
        resume_menu_action     = 'RunPlugin(%s)' % resume_path
        from_start_menu_action = 'RunPlugin(%s)' % play_from_start_path
        context_menu = [
            ('Choose add-on', 'Container.Update(%s)' % source_path),
            ('Resume directly', resume_menu_action),
            ('Play from the beginning', from_start_menu_action),
            ('Open show' if is_episode else 'Open details', 'Container.Update(%s)' % (build_url(action='series_meta', media_type='series', canonical_id=row.get('canonical_id') or '', title=title) if is_episode else build_url(action='item_open', media_type=row.get('media_type') or 'movie', canonical_id=row.get('canonical_id') or '', title=title, tmdb_id=row_ids.get('tmdb_id') or '', imdb_id=row_ids.get('imdb_id') or '', tvdb_id=row_ids.get('tvdb_id') or ''))),
            (tr('Change metadata add-on'), 'RunPlugin(%s)' % build_url(action='meta_pick_target', target_key=target_key, title=target_title)),
        ] + _build_player_chooser_menu(
            media_type='series' if is_episode else (row.get('media_type') or 'movie'),
            canonical_id=row.get('canonical_id') or '',
            title=title,
            tmdb_id=row_ids.get('tmdb_id') or '',
            imdb_id=row_ids.get('imdb_id') or '',
            tvdb_id=row_ids.get('tvdb_id') or '',
            season=row.get('season') or '',
            episode=row.get('episode') or '',
            video_id=row.get('video_id') or '',
        ) + [
            ('Remove from Continue Watching', 'RunPlugin(%s)' % build_url(action='cw_remove', media_type=row.get('media_type'), canonical_id=row.get('canonical_id'), video_id=row.get('video_id'))),
            ('Mark as watched', 'RunPlugin(%s)' % build_url(action='cw_mark_watched', media_type=row.get('media_type'), canonical_id=row.get('canonical_id'), video_id=row.get('video_id'))),
        ]

        add_item(display_title, path, is_folder=path_is_folder, info=info, art=art, properties=properties if not path_is_folder else {}, context_menu=context_menu)
    if has_more:
        add_item(
            'More',
            build_url(action='continue', page=str(page_num + 1)),
            info={'title': 'More', 'plot': 'Load more items from Continue Watching'},
            art=root_art('continue'),
        )
    end_dir(content=content_type, cache=False)


def cw_remove(media_type='', canonical_id='', video_id=''):
    try:
        playback_store.delete_entry(media_type, canonical_id, video_id)
        _invalidate_nextup_cache()
        notify(tr('Removed from Continue Watching'))
    except Exception as exc:
        error(tr('Could not remove: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')


def cw_mark_watched(media_type='', canonical_id='', video_id=''):
    try:
        playback_store.mark_watched(media_type, canonical_id, video_id)
        _invalidate_nextup_cache()
        notify(tr('Marked as watched'))
    except Exception as exc:
        error(tr('Could not mark item: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')


def refresh_provider(provider_id):
    """Re-fetch the manifest for a provider and update its cached snapshot."""
    row = store.get_provider(provider_id)
    if not row:
        error(tr('Add-on not found'))
        return
    manifest_url = row.get('manifest_url') or ''
    if not manifest_url:
        error(tr('Unknown manifest URL'))
        return
    try:
        new_manifest = validate_manifest(manifest_url)
        store.refresh_provider_manifest(provider_id, new_manifest)
        notify(tr('Updated: %s') % (row.get('name') or provider_id))
    except Exception as exc:
        error(tr('Update failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')








def show_last_silent_error_action():
    """v3.9.90: surface the most recently-swallowed exception so users
    can include it in bug reports. Reads the in-memory tracker from
    log.py and shows a dialog with three buttons: Copy to clipboard,
    Clear, Close. Reachable from settings → Performance & Library →
    "Show last silent error"."""
    from . import log as _log_mod
    text = _log_mod.format_last_silent_error()
    if not text:
        notify(tr('No silent error recorded right now'))
        return
    dialog = xbmcgui.Dialog()
    choice = dialog.select(
        tr('Last silent error'),
        [text, tr('Copy to clipboard'), tr('Clear log'), tr('Close')],
    )
    if choice == 1:
        # Copy to clipboard via xbmc API (works on most platforms; on
        # Android it pushes to the system clipboard via JSON-RPC).
        try:
            import json as _json
            xbmc.executebuiltin('SetClipboard("%s")' % text.replace('"', '\\"'))
            notify(tr('Copied to clipboard'))
        except Exception as exc:
            _log_mod.log.silent('LAST_ERROR_COPY', exc, 'clipboard copy')
            notify(tr('Could not copy to clipboard'))
    elif choice == 2:
        _log_mod.clear_last_silent_error()
        notify(tr('Error log cleared'))


def clear_cache():
    removed = 0
    try:
        from .nuviohub import client as _client_mod
        removed += int(_client_mod.clear_http_cache() or 0)
    except Exception:
        pass
    try:
        cache_store.clear_all()
    except Exception:
        pass
    # v3.9.30: also wipe the SQLite meta cache. Previously the user
    # needed TWO buttons (clear_cache + meta_cache_clear) which was
    # confusing — most users hit one and assumed the other was done.
    try:
        from . import meta_cache as _mc
        _mc.clear_all()
    except Exception:
        pass
    try:
        _SEARCH_RESULT_CACHE.clear()
        _SEARCH_RESULT_CACHE_ORDER[:] = []
    except Exception:
        pass
    _invalidate_nextup_cache()
    try:
        path = _source_pref_path()
        if path and os.path.exists(path):
            os.remove(path)
    except Exception:
        pass
    try:
        mon_path = _playback_monitor_path()
        if mon_path and os.path.exists(mon_path):
            os.remove(mon_path)
    except Exception:
        pass
    try:
        win = xbmcgui.Window(WINDOW_ID)
        for key in ('nuviohub.fav_mirror_done', 'nuviohub.fav_mirror_syncing', 'nuviohub.fav_mirror_syncing_started'):
            try:
                win.clearProperty(key)
            except Exception:
                pass
        try:
            for prop_name in list(getattr(win, 'getPropertyKeys', lambda: [])() or []):
                if prop_name.startswith(SERIES_PROP_PREFIX):
                    try:
                        win.clearProperty(prop_name)
                    except Exception:
                        pass
        except Exception:
            pass
    except Exception:
        pass
    notify(tr('Cache cleared (%s HTTP files)') % removed if removed else tr('Cache cleared'))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir()


