def play(stream_key, resume_seconds='', resume_percent='', fallback_keys=None, switch_subtitle_path='', switch_subtitle_enabled='', switch_subtitle_name=''):
    if _dispatch_in_flight('play|%s' % (stream_key or ''), window_seconds=4):
        xbmc.log('[NuvioHub] play: duplicate dispatch suppressed (%s)' % stream_key, xbmc.LOGINFO)
        return
    ctx = cache_store.get('stream', stream_key)
    if not ctx:
        error(tr('Playback data expired. Choose the source again.'))
        return end_dir()
    # Backward-compatible parameter only.  v5.3 never follows it: the selected
    # source is authoritative and a failure returns control to the user.
    fallback = []
    try:
        rs = float(resume_seconds or 0.0)
    except Exception:
        rs = 0.0
    if rs > 1.0:
        ctx = dict(ctx or {})
        ctx['resume_seconds'] = rs
    try:
        rp = float(resume_percent or 0.0)
    except Exception:
        rp = 0.0
    if rp > 1.0 and rp < 95.0:
        ctx = dict(ctx or {})
        ctx['resume_percent'] = rp
    if switch_subtitle_path:
        ctx = dict(ctx or {})
        ctx['switch_subtitle_path'] = str(switch_subtitle_path)
        ctx['switch_subtitle_enabled'] = str(switch_subtitle_enabled or '1').strip().lower() not in ('0', 'false', 'no', 'off')
        ctx['switch_subtitle_name'] = str(switch_subtitle_name or '')
        # A source switch is the same viewing session, not a new subtitle
        # search.  Suppress Nuvio Hub's broker/auto-pick for the replacement;
        # CompanionPlayer restores the exact external file after any modal
        # subtitle dialog has closed.
        ctx['source_switch_reuse_subtitle'] = True
        ctx['play_with_subtitles'] = False
        ctx['selected_subtitle'] = ''
    _play_with_context(ctx, stream_key, fallback_keys=fallback)


# ═════════════ Collection Sets (Fusion-Starter-Kit style) ═════════════

def _make_addon_manifest_resolver(host_hint=''):
    """Return a callback (addon_id, share_url) -> manifest_url for use by
    collection imports. Prompts the user once per unique unresolved addonId."""

    def _resolver(addon_id, share_url):
        try:
            sibling_manifest = _collections_mod.manifest_url_from_collections_url(share_url)
            if sibling_manifest and (_collections_mod.addon_requires_configuration(addon_id) or 'plex' in str(addon_id or '').lower()):
                return sibling_manifest
        except Exception:
            pass
        try:
            known_manifest = _collections_mod.known_manifest_for_addon_id(addon_id)
            if known_manifest:
                return known_manifest
        except Exception:
            pass
        msg_lines = [
            tr('This collection depends on an addon that is not installed yet:'),
            '[COLOR yellow]%s[/COLOR]' % addon_id,
            '',
        ]
        if host_hint:
            msg_lines.extend([
                tr('It appears to be hosted on:'),
                '[COLOR yellow]%s[/COLOR]' % host_hint,
                '',
            ])
        try:
            if _collections_mod.addon_requires_configuration(addon_id):
                msg_lines.append(tr('This addon needs a Manifest URL configured for your account/library, not the public manifest.'))
                msg_lines.append('')
        except Exception:
            pass
        msg_lines.append(tr('Do you have its manifest.json URL?'))
        want = xbmcgui.Dialog().yesno(
            tr('Missing addon'),
            '\n'.join(msg_lines),
            nolabel=tr('Skip'), yeslabel=tr('Paste a URL'),
        )
        if not want:
            return ''
        kb = xbmc.Keyboard('', tr('Paste a manifest.json or collections.json URL for %s') % addon_id)
        kb.doModal()
        if not kb.isConfirmed():
            return ''
        typed = kb.getText().strip()
        try:
            return _collections_mod.manifest_url_from_collections_url(typed) or typed
        except Exception:
            return typed

    return _resolver


def collection_set_add():
    """Prompt for a JSON URL (or paste), then a custom display name."""
    keyboard = xbmc.Keyboard('', tr('Paste the JSON URL or the full text'))
    keyboard.doModal()
    if not keyboard.isConfirmed():
        return end_dir()
    raw = keyboard.getText().strip()
    if not raw:
        return end_dir()

    # v3.9.60: comprehensive diagnostic logging at every step. If
    # anything fails, the dialog now shows step-by-step what
    # succeeded and what failed, plus the full traceback, so the
    # user can immediately tell us exactly what went wrong rather
    # than seeing a one-line "فشل قراءة الملف".
    import traceback as _tb
    diag = []
    is_url = raw.startswith('http://') or raw.startswith('https://')
    diag.append('input: %s' % ('URL' if is_url else 'pasted text'))
    if is_url:
        diag.append('url: %s' % raw[:120])

    try:
        if is_url:
            try:
                text = _collections_mod.fetch_raw_text(raw)
                diag.append('fetch: OK (%d bytes)' % len(text or ''))
            except Exception as fetch_exc:
                diag.append('fetch: FAILED — %s' % fetch_exc)
                raise
        else:
            text = raw
            diag.append('fetch: skipped (text input)')

        try:
            parsed_entries = _collections_mod.parse_collection_json(text)
            diag.append('parse: OK (%d entries)' % len(parsed_entries or []))
        except Exception as parse_exc:
            diag.append('parse: FAILED — %s' % parse_exc)
            # Show a snippet of the first 200 chars so user can see
            # if they pasted/fetched something that isn't JSON.
            snippet = (text or '')[:200].replace('\n', ' ').replace('\r', ' ')
            diag.append('content snippet: %s' % snippet)
            raise
    except Exception as exc:
        # Full diagnostic dialog + log
        try:
            xbmc.log('[NuvioHub] collection_set_add FAILED:\n%s\n%s' % (
                '\n'.join(diag), _tb.format_exc()), xbmc.LOGERROR)
        except Exception:
            pass
        try:
            xbmcgui.Dialog().textviewer(tr('Nuvio Hub — file read failed'),
                'Steps:\n' + '\n'.join(diag) + '\n\nFull error:\n' + str(exc) + '\n\n' + _tb.format_exc())
        except Exception:
            error(tr('Could not read file: %s') % exc)
        return home()

    default_name = _collections_mod._derive_set_name(raw if is_url else '', parsed_entries)
    # Optional: ask user for a name.
    kb2 = xbmc.Keyboard(default_name, tr('Collection name (leave it as-is if you like it)'))
    kb2.doModal()
    custom_name = kb2.getText().strip() if kb2.isConfirmed() else default_name

    # Duplicate detection by URL — offer to refresh instead of re-importing.
    if is_url:
        for existing in _collections_mod.list_sets():
            if existing.get('source_url') == raw:
                if xbmcgui.Dialog().yesno('Nuvio Hub', tr('This collection already exists. Update it?')):
                    try:
                        updated = _collections_mod.refresh_set(existing.get('id'), manifest_resolver=_make_addon_manifest_resolver(''))
                        if custom_name and custom_name != updated.get('name'):
                            _collections_mod.rename_set(existing.get('id'), custom_name)
                        notify(tr('Collection updated'))
                    except Exception as exc:
                        error(tr('Could not update: %s') % exc)
                return collection_sets()

    try:
        # Build a resolver that prompts the user for any missing addonId.
        # The user only sees this for addons that aren't already installed,
        # and we deduplicate so each unique addonId is asked once.
        host_hint = _collections_mod.derive_addon_manifest_url(raw if is_url else '', '') or ''
        resolver = _make_addon_manifest_resolver(host_hint)
        if is_url:
            set_row = _collections_mod.add_set_from_url(raw, name=custom_name, manifest_resolver=resolver)
        else:
            set_row = _collections_mod.add_set_from_text(raw, source_label=custom_name, manifest_resolver=resolver)
        diag.append('save: OK (%d entries persisted)' % len(set_row.get('entries') or []))
    except Exception as exc:
        try:
            xbmc.log('[NuvioHub] collection_set_add SAVE FAILED:\n%s\n%s' % (
                '\n'.join(diag), _tb.format_exc()), xbmc.LOGERROR)
        except Exception:
            pass
        try:
            xbmcgui.Dialog().textviewer(tr('Nuvio Hub — import failed'),
                'Steps:\n' + '\n'.join(diag) + '\n\nFull error:\n' + str(exc) + '\n\n' + _tb.format_exc())
        except Exception:
            error(tr('Import failed: %s') % exc)
        return home()
    notify(tr('Imported %d shortcuts') % len(set_row.get('entries') or []))
    return collection_sets()



def collection_set_export(set_id=''):
    row = _collections_mod.get_set(set_id) if set_id else None
    rows = [row] if row else _collections_mod.list_sets()
    rows = [r for r in rows if isinstance(r, dict)]
    if not rows:
        notify(tr('No collections to export'))
        return collection_sets()
    default_name = 'nuvio-hub-collections-backup.json' if not row else 'nuvio-hub-%s.json' % re.sub(r'[^A-Za-z0-9_-]+', '-', row.get('name') or row.get('id') or 'collection').strip('-')
    try:
        folder = xbmcgui.Dialog().browse(0, tr('Choose a backup folder'), 'files')
    except Exception:
        folder = ''
    if not folder:
        return collection_sets()
    path = os.path.join(xbmcvfs.translatePath(folder), default_name)
    payload = {'format': 'nuviohub.collection.backup', 'version': 1, 'exported_at': int(time.time()), 'collections': rows}
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
    except Exception:
        pass
    try:
        fh = xbmcvfs.File(path, 'w')
        fh.write(json.dumps(payload, ensure_ascii=False, indent=2))
        fh.close()
        notify(tr('Collection backup saved'))
        xbmcgui.Dialog().ok('Nuvio Hub', tr('Backup saved:\n%s') % path)
    except Exception as exc:
        error(tr('Export failed: %s') % exc)
    return collection_sets()


def collection_set_import_backup():
    try:
        path = xbmcgui.Dialog().browse(1, tr('Choose a collection backup file'), 'files', '.json')
    except Exception:
        path = ''
    if not path:
        return collection_sets()
    try:
        fh = xbmcvfs.File(path)
        raw = fh.read()
        fh.close()
        if isinstance(raw, bytes):
            raw = raw.decode('utf-8', 'ignore')
        data = json.loads(raw or '{}')
        if isinstance(data, dict) and isinstance(data.get('collections'), list):
            imported = _collections_mod.import_sets(data.get('collections') or [])
        elif isinstance(data, list):
            # A Nuvio Hub backup list has rows with `entries`. Nuvio/Fusion
            # profile backups are also top-level lists, but they use
            # `folders[]`/`catalogSources[]`; importing those as a configuration backup
            # silently produced 0 groups. Detect that shape and parse it as a
            # normal collection JSON instead.
            looks_like_entry_backup = any(isinstance(r, dict) and isinstance(r.get('entries'), list) for r in data)
            if looks_like_entry_backup:
                imported = _collections_mod.import_sets(data)
            else:
                name = os.path.splitext(os.path.basename(path))[0]
                imported_row = _collections_mod.add_set_from_text(raw, source_label=name, manifest_resolver=_make_addon_manifest_resolver(''))
                imported = 1 if imported_row else 0
        else:
            # Also allow importing a plain Nuvio/Fusion JSON as a new set.
            name = os.path.splitext(os.path.basename(path))[0]
            imported_row = _collections_mod.add_set_from_text(raw, source_label=name, manifest_resolver=_make_addon_manifest_resolver(''))
            imported = 1 if imported_row else 0
        notify(tr('Imported %d collections') % int(imported or 0))
    except Exception as exc:
        error(tr('Import failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')
    return collection_sets()

def collection_set_rename(set_id):
    row = _collections_mod.get_set(set_id)
    if not row:
        error(tr('Collection not found'))
        return
    kb = xbmc.Keyboard(row.get('name') or '', tr('New collection name'))
    kb.doModal()
    if not kb.isConfirmed():
        return
    new_name = kb.getText().strip()
    if not new_name:
        return
    try:
        _collections_mod.rename_set(set_id, new_name)
        notify(tr('Renamed'))
    except Exception as exc:
        error(tr('Edit failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')


def collection_sets():
    """List saved collection sets as clean folders.

    v3.9.139: clean view is the default.  Import/export/create rows used to
    appear as visible cards at the top of Collection, which made the page look
    like a settings/backup screen instead of a media hub.  Keep those actions
    available from the Options/context menu on each collection row; show the
    add actions inline only when the user has no collections yet.
    """
    rows = sorted(_collections_mod.list_sets(), key=lambda r: (r.get('name') or '').lower())
    clean = _clean_collection_view_enabled()

    global_ctx = [
        (tr('Import collection from JSON'), 'RunPlugin(%s)' % build_url(action='collection_set_add')),
        (tr('Import collection backup'), 'RunPlugin(%s)' % build_url(action='collection_set_import_backup')),
        (tr('Export backup for all collections'), 'RunPlugin(%s)' % build_url(action='collection_set_export')),
        (tr('Create empty collection manually'), 'RunPlugin(%s)' % build_url(action='collection_set_create_empty')),
        ('Accounts and collection import', 'ActivateWindow(Videos,%s,return)' % build_url(action='nuvio_sync_menu')),
    ]

    if not clean:
        add_item(tr('[COLOR yellow]+ Import a collection from JSON[/COLOR]'), build_url(action='collection_set_add'), is_folder=False, art=root_art('add'))
        add_item(tr('[COLOR yellow]+ Import collection backup[/COLOR]'), build_url(action='collection_set_import_backup'), is_folder=False, art=root_art('add'))
        add_item(tr('[COLOR yellow]Export collections backup[/COLOR]'), build_url(action='collection_set_export'), is_folder=False, art=root_art('catalogs'))
        add_item(tr('[COLOR yellow]+ Create an empty collection (manual)[/COLOR]'), build_url(action='collection_set_create_empty'), is_folder=False, art=root_art('add'))
    elif not rows:
        # Empty state still needs a visible way to start, but no backup/export
        # poster cards are shown in the normal populated view.
        add_item(tr('[COLOR yellow]+ Import a collection from JSON[/COLOR]'), build_url(action='collection_set_add'), is_folder=False, art=root_art('add'))
        add_item(tr('[COLOR yellow]+ Create an empty collection (manual)[/COLOR]'), build_url(action='collection_set_create_empty'), is_folder=False, art=root_art('add'))

    for row in rows:
        label = row.get('name') or 'Collection Set'
        entries = row.get('entries') or []
        kinds = {}
        for e in entries:
            k = e.get('kind') or 'other'
            kinds[k] = kinds.get(k, 0) + 1
        kind_line = ' / '.join('%s: %d' % (k, v) for k, v in kinds.items())
        plot_lines = ['[B]%s[/B]' % label, tr('%d shortcuts') % len(entries)]
        if kind_line:
            plot_lines.append(kind_line)
        if row.get('source_url'):
            plot_lines.append(tr('Add-on: %s') % row.get('source_url'))
        info = {'title': label, 'plot': '\n'.join(plot_lines)}
        ctx_menu = [
            (tr('Add new item from Stremio add-ons'), 'RunPlugin(%s)' % build_url(action='collection_entry_add_stremio', set_id=row.get('id'))),
            (tr('Add new Trakt list'), 'RunPlugin(%s)' % build_url(action='collection_entry_add_trakt_list', set_id=row.get('id'))),
            (tr('Add new MDBList'), 'RunPlugin(%s)' % build_url(action='collection_entry_add_mdblist_list', set_id=row.get('id'))),
            (tr('Add TMDb Helper Native shortcut'), 'RunPlugin(%s)' % build_url(action='collection_entry_add_tmdbhelper_native', set_id=row.get('id'))),
            (tr('Add new path from widget/skin picker'), 'RunPlugin(%s)' % build_url(action='collection_entry_add_widget', set_id=row.get('id'))),
            (tr('Add new item manually'), 'RunPlugin(%s)' % build_url(action='collection_entry_add', set_id=row.get('id'))),
            (tr('Rename'), 'RunPlugin(%s)' % build_url(action='collection_set_rename', set_id=row.get('id'))),
            (tr('Manage metadata add-ons'), 'RunPlugin(%s)' % build_url(action='meta_sources_dialog')),
            (tr('Update collection'), 'RunPlugin(%s)' % build_url(action='collection_set_refresh', set_id=row.get('id'))),
            (tr('Export Backup'), 'RunPlugin(%s)' % build_url(action='collection_set_export', set_id=row.get('id'))),
            (tr('Remove collection'), 'RunPlugin(%s)' % build_url(action='collection_set_remove', set_id=row.get('id'))),
        ]
        if clean:
            ctx_menu.extend(global_ctx)
        add_item(label, build_url(action='collection_set_browse', set_id=row.get('id')), info=info, art=root_art('catalogs'), context_menu=ctx_menu)
    if not rows:
        add_item(tr('[COLOR grey]No collections yet[/COLOR]'), build_url(action='collection_sets'), is_folder=False, info={'title': tr('Empty')})
    end_dir(content='files')


def _trakt_local_poster(meta):
    meta = meta or {}
    poster = str(meta.get('poster') or meta.get('thumbnail') or meta.get('thumb') or '').strip()
    images = meta.get('images') or {}
    if isinstance(images, dict):
        for key in ('poster', 'thumb', 'thumbnail'):
            node = images.get(key) or {}
            if isinstance(node, dict):
                poster = poster or str(node.get('full') or node.get('medium') or node.get('thumb') or '').strip()
            elif node:
                poster = poster or str(node).strip()
    return poster


def _trakt_art_bundle(ids, media_type, title='', year='', meta=None, force_remote=False, allow_direct=True):
    ids = ids or {}
    tmdb_id = str(ids.get('tmdb') or ids.get('tmdb_id') or '').strip()
    imdb_id = str(ids.get('imdb') or ids.get('imdb_id') or '').strip()
    local_mode = posters_prefer_local() and not force_remote
    local_poster = _trakt_local_poster(meta) if local_mode else ''
    db_bundle = {}
    try:
        db_bundle = _tmdb_art_db.get_art_bundle_from_db(
            tmdb_id=tmdb_id,
            imdb_id=imdb_id,
            media_type='tv' if media_type in ('series', 'anime', 'show', 'tv') else 'movie',
            title=title or '',
            year=year or '',
        ) or {}
    except Exception:
        db_bundle = {}
    need_direct = allow_direct and not (db_bundle.get('fanart') and db_bundle.get('clearlogo') and (local_mode or db_bundle.get('poster')))
    if need_direct:
        try:
            direct_bundle = _tmdb_direct.art_for(
                tmdb_id=tmdb_id,
                imdb_id=imdb_id,
                media_type='tv' if media_type in ('series', 'anime', 'show', 'tv') else 'movie',
                title=title or '',
                year=year or '',
            ) or {}
        except Exception:
            direct_bundle = {}
    else:
        direct_bundle = {}
    poster = local_poster if local_mode else (db_bundle.get('poster') or direct_bundle.get('poster') or local_poster or '')
    return {
        'poster': poster,
        'fanart': db_bundle.get('fanart') or db_bundle.get('landscape') or direct_bundle.get('fanart') or direct_bundle.get('landscape') or '',
        'landscape': db_bundle.get('landscape') or db_bundle.get('fanart') or direct_bundle.get('landscape') or direct_bundle.get('fanart') or '',
        'clearlogo': db_bundle.get('clearlogo') or direct_bundle.get('clearlogo') or '',
    }

def _trakt_info(meta, media_type):
    is_series = media_type in ('series', 'anime', 'show', 'tv')
    info = {
        'title': meta.get('title') or '',
        'sorttitle': meta.get('title') or '',
        'plot': meta.get('overview') or meta.get('summary') or '',
        'mediatype': 'tvshow' if is_series else 'movie',
    }
    year = meta.get('year')
    if year:
        try:
            info['year'] = int(year)
        except Exception:
            pass
    if meta.get('rating') not in (None, ''):
        try:
            info['rating'] = float(meta.get('rating') or 0.0)
        except Exception:
            pass
    if meta.get('votes') not in (None, ''):
        try:
            info['votes'] = int(meta.get('votes') or 0)
        except Exception:
            pass
    if meta.get('runtime'):
        try:
            info['duration'] = int(float(meta.get('runtime') or 0) * 60)
        except Exception:
            pass
    genres = meta.get('genres') or []
    if genres:
        info['genre'] = ' / '.join(genres)
    studio = meta.get('network') or meta.get('studio') or ''
    if studio:
        info['studio'] = studio
    if meta.get('certification'):
        info['mpaa'] = meta.get('certification')
    premiered = meta.get('released') or meta.get('first_aired') or ''
    if premiered:
        info['premiered'] = str(premiered)[:10]
        info['date'] = str(premiered)[:10]
    tagline = meta.get('tagline') or ''
    if tagline:
        info['tagline'] = tagline
    status = meta.get('status') or ''
    country = meta.get('country') or ''
    if status and country:
        info['status'] = '%s • %s' % (status, country)
    elif status:
        info['status'] = status
    elif country:
        info['status'] = country
    return info


def _provider_for_manifest_url(manifest_url):
    manifest_url = (manifest_url or '').strip()
    if not manifest_url:
        return None
    for row in store.list_providers():
        if (row.get('manifest_url') or '').strip() == manifest_url:
            return row
    return None


def _provider_for_addon_ref(addon_ref):
    addon_ref = (addon_ref or '').strip()
    if not addon_ref:
        return None
    provider = _provider_for_manifest_url(addon_ref)
    if provider:
        return provider
    try:
        return _collections_mod.find_provider_by_addon_id(addon_ref)
    except Exception:
        return None


