def _collection_source_label(src, idx=0):
    """Compact user-facing label for one multiCatalog source."""
    src = src or {}
    addon_id = str(src.get('addonId') or src.get('addon_id') or '').strip()
    catalog_id = str(src.get('catalogId') or src.get('catalog_id') or '').strip()
    catalog_type = str(src.get('catalogType') or src.get('type') or 'movie').strip()
    genre = str(src.get('genre') or '').strip()
    extra = src.get('extra') if isinstance(src.get('extra'), dict) else {}
    base = '[%s] %s' % (catalog_type or 'movie', catalog_id or 'catalog')
    if genre:
        base += ' / genre=%s' % genre
    if extra:
        try:
            base += ' / ' + ', '.join('%s=%s' % (k, v) for k, v in list(extra.items())[:2])
        except Exception:
            pass
    if addon_id:
        provider = _provider_for_addon_ref(addon_id)
        base += ' — %s' % ((provider or {}).get('name') or addon_id)
    return '%02d. %s' % (idx + 1, base)


def _select_dialog(title, labels, preselect=0):
    try:
        return xbmcgui.Dialog().select(tr(title), [tr(x) for x in labels], preselect=preselect)
    except TypeError:
        return xbmcgui.Dialog().select(tr(title), [tr(x) for x in labels])


def _catalog_source_extra_options(catalog_def):
    """Return catalog extras that can behave like folders/categories."""
    out = []
    try:
        for extra in (catalog_def.get('extra') or []):
            if not isinstance(extra, dict):
                continue
            name = str(extra.get('name') or '').strip()
            if not name or name in ('skip', 'search', 'limit'):
                continue
            opts = [str(o) for o in (extra.get('options') or []) if o not in (None, '')]
            if not opts:
                continue
            # Keep the chooser useful and close to Stremio folder/category UX.
            if _extra_mode(name, catalog_def) == 'folder' or name.lower() in ('genre', 'category', 'year', 'language', 'country', 'network', 'studio', 'collection', 'type'):
                out.append((name, opts))
    except Exception:
        pass
    return out


def _pick_catalog_source_extra(catalog_def, current=None):
    """Optional Stremio extra/category picker for one selected catalog.

    Returns ({name: value}, genre_value) or None when the user cancels.
    Empty dict means no preset filter.
    """
    current = current or {}
    extra_defs = _catalog_source_extra_options(catalog_def or {})
    if not extra_defs:
        return {}, ''
    labels = ['No filter / open the full catalog'] + ['%s (%d)' % (_filter_label(name), len(opts)) for name, opts in extra_defs]
    idx = _select_dialog('Choose a folder / filter from the catalog', labels, preselect=0)
    if idx < 0:
        return None
    if idx == 0:
        return {}, ''
    name, opts = extra_defs[idx - 1]
    current_value = ''
    if isinstance(current.get('extra'), dict):
        current_value = str(current.get('extra', {}).get(name) or '')
    if not current_value and name == 'genre':
        current_value = str(current.get('genre') or '')
    pre = opts.index(current_value) if current_value in opts else 0
    opt_idx = _select_dialog(tr('Choose %s') % _filter_label(name), opts, preselect=pre)
    if opt_idx < 0:
        return None
    value = opts[opt_idx]
    if name == 'genre':
        return {'genre': value}, value
    return {name: value}, ''


def _collection_provider_catalog_rows():
    rows = []
    for provider in store.list_providers() or []:
        manifest = provider.get('manifest') or {}
        for catalog in manifest.get('catalogs') or []:
            if not isinstance(catalog, dict):
                continue
            cid = str(catalog.get('id') or '').strip()
            ctype = str(catalog.get('type') or '').strip() or 'movie'
            if not cid:
                continue
            pname = provider.get('name') or manifest.get('name') or provider.get('id') or 'Stremio'
            cname = catalog.get('name') or cid
            label = '%s  •  [%s] %s' % (pname, ctype, cname)
            if cid != cname:
                label += '  (%s)' % cid
            rows.append({'provider': provider, 'catalog': catalog, 'label': label})
    rows.sort(key=lambda r: (str((r.get('provider') or {}).get('name') or '').lower(), str((r.get('catalog') or {}).get('name') or '').lower()))
    return rows


def _pick_stremio_catalog_source(src=None):
    """Pick a Stremio catalog from the registered manifests, like Stremio UI."""
    src = src or {}
    rows = _collection_provider_catalog_rows()
    if not rows:
        error(tr('No Stremio addons are registered. Add a manifest first from Add-ons.'))
        return None
    default_idx = 0
    current_addon = str(src.get('addonId') or src.get('addon_id') or '').strip()
    current_catalog = str(src.get('catalogId') or src.get('catalog_id') or '').strip()
    current_type = str(src.get('catalogType') or src.get('type') or '').strip()
    for i, row in enumerate(rows):
        provider = row.get('provider') or {}
        catalog = row.get('catalog') or {}
        refs = [str(provider.get('manifest_url') or '').strip(), str(provider.get('id') or '').strip(), str((provider.get('manifest') or {}).get('id') or '').strip()]
        if current_addon and current_addon in refs and current_catalog == str(catalog.get('id') or '') and (not current_type or current_type == str(catalog.get('type') or '')):
            default_idx = i
            break
    labels = [r.get('label') or 'Catalog' for r in rows]
    idx = _select_dialog(tr('Choose a Stremio catalog'), labels, preselect=default_idx)
    if idx < 0:
        return None
    row = rows[idx]
    provider = row.get('provider') or {}
    catalog = row.get('catalog') or {}
    extra_pick = _pick_catalog_source_extra(catalog, current=src)
    if extra_pick is None:
        return None
    extra_dict, genre_value = extra_pick
    out = {
        # Use manifest_url so configured/private manifests keep their token exactly like Stremio.
        'addonId': str(provider.get('manifest_url') or (provider.get('manifest') or {}).get('id') or provider.get('id') or '').strip(),
        'catalogId': str(catalog.get('id') or '').strip(),
        'catalogType': str(catalog.get('type') or 'movie').strip() or 'movie',
        'genre': genre_value or '',
    }
    if extra_dict:
        out['extra'] = dict(extra_dict)
    return out


def _manual_collection_catalog_source(src=None):
    src = src or {}
    addon_id = _prompt_text(str(src.get('addonId') or src.get('addon_id') or ''), 'Manifest URL or Addon ID')
    if addon_id is None:
        return None
    addon_id = str(addon_id or '').strip()
    if not addon_id:
        error(tr('Addon ID / manifest is empty'))
        return None

    catalog_id = _prompt_text(str(src.get('catalogId') or src.get('catalog_id') or ''), 'Catalog ID')
    if catalog_id is None:
        return None
    catalog_id = str(catalog_id or '').strip()
    if not catalog_id:
        error(tr('Catalog ID is empty'))
        return None

    current_type = str(src.get('catalogType') or src.get('type') or 'movie').strip().lower() or 'movie'
    choices = ['movie', 'series', 'anime']
    default_idx = choices.index(current_type) if current_type in choices else 0
    idx = _select_dialog('Catalog type', choices, preselect=default_idx)
    if idx < 0:
        return None
    catalog_type = choices[idx]

    genre = _prompt_text(str(src.get('genre') or ''), 'Genre / Extra (optional)')
    if genre is None:
        return None

    out = {
        'addonId': addon_id,
        'catalogId': catalog_id,
        'catalogType': catalog_type,
        'genre': str(genre or '').strip(),
    }
    extra = src.get('extra')
    if isinstance(extra, dict) and extra:
        out['extra'] = extra
    return out


def _collection_prompt_catalog_source(src=None):
    """Pick or type a Stremio catalog source for collection folders."""
    src = src or {}
    modes = [tr('Pick from registered Stremio addons'), tr('Advanced manual entry')]
    default_idx = 0 if store.list_providers() else 1
    mode = _select_dialog('Add-on selection method', modes, preselect=default_idx)
    if mode < 0:
        return None
    if mode == 0:
        return _pick_stremio_catalog_source(src)
    return _manual_collection_catalog_source(src)


def _collection_edit_multi_sources(payload):
    """Edit/add/remove a source inside a multiCatalog payload.

    Returns a new sources list, or None when the user cancels.
    """
    sources = []
    for src in (payload.get('sources') or []):
        if isinstance(src, dict):
            sources.append(dict(src))
    labels = [_collection_source_label(src, i) for i, src in enumerate(sources)]
    labels.append('+ Add new add-on')
    choice = xbmcgui.Dialog().select(tr('Folder add-ons'), labels)
    if choice < 0:
        return None

    if choice >= len(sources):
        new_src = _collection_prompt_catalog_source({})
        if not new_src:
            return None
        sources.append(new_src)
        return sources

    action = xbmcgui.Dialog().select(tr('Edit add-on'), [tr('Edit this add-on'), tr('Remove this add-on'), tr('Add new add-on')])
    if action < 0:
        return None
    if action == 1:
        if not xbmcgui.Dialog().yesno('Nuvio Hub', tr('Remove this add-on?')):
            return None
        del sources[choice]
        return sources
    if action == 2:
        new_src = _collection_prompt_catalog_source({})
        if not new_src:
            return None
        sources.append(new_src)
        return sources

    edited = _collection_prompt_catalog_source(sources[choice])
    if not edited:
        return None
    sources[choice] = edited
    return sources

def collection_entry_edit_source(set_id, entry_id):
    row = _collections_mod.get_set(set_id)
    if not row:
        return
    entry = next((e for e in (row.get('entries') or []) if e.get('id') == entry_id), None)
    if not entry:
        return
    kind = (entry.get('kind') or '').strip()
    payload = entry.get('payload') or {}
    updates = {}
    if kind == 'addonCatalog':
        edit_modes = ['Pick a catalog from Stremio addons', 'Browse a Kodi addon', 'Choose from widget/skin picker', 'Advanced manual entry']
        mode = _select_dialog(tr('Edit link/source'), [tr(x) for x in edit_modes], preselect=0)
        if mode < 0:
            return
        if mode == 0:
            src = _pick_stremio_catalog_source(payload)
            if not src:
                return
            media_filter = _pick_collection_media_filter(src.get('catalogType') or payload.get('mediaFilter') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'addonCatalog', 'payload.addonId': src.get('addonId') or '', 'payload.catalogId': src.get('catalogId') or '', 'payload.catalogType': src.get('catalogType') or 'movie', 'payload.genre': src.get('genre') or '', 'payload.extra': src.get('extra') or {}, 'payload.mediaFilter': media_filter})
            try:
                _collections_mod.ensure_addon_registered(src.get('addonId') or '')
            except Exception as exc:
                xbmc.log('[NuvioHub] auto-register failed after source edit: %s' % exc, xbmc.LOGWARNING)
        elif mode == 1:
            addon_row = _pick_installed_video_addon()
            if not addon_row:
                return
            route_url, route_label = _pick_kodi_plugin_route(addon_row)
            if not route_url:
                return
            media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'kodiPluginRoute', 'payload.addonId': addon_row.get('id') or '', 'payload.addonName': addon_row.get('name') or addon_row.get('id') or '', 'payload.route': route_url, 'payload.mediaFilter': media_filter, 'payload.thumbnail': addon_row.get('thumbnail') or '', 'payload.fanart': addon_row.get('fanart') or ''})
            if route_label:
                updates['name'] = route_label
        elif mode == 2:
            route_url, route_label, _addon_meta = _pick_skin_widget_route(default_label=entry.get('name') or '')
            if not route_url:
                return
            media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'kodiPluginRoute'})
            updates.update({'payload.%s' % k: v for k, v in _kodi_route_payload(route_url, label=route_label, media_filter=media_filter).items()})
            if route_label:
                updates['name'] = route_label
        else:
            src = _manual_collection_catalog_source(payload)
            if not src:
                return
            media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or src.get('catalogType') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'addonCatalog', 'payload.addonId': src.get('addonId') or '', 'payload.catalogId': src.get('catalogId') or '', 'payload.catalogType': src.get('catalogType') or 'movie', 'payload.genre': src.get('genre') or '', 'payload.extra': src.get('extra') or {}, 'payload.mediaFilter': media_filter})
            try:
                _collections_mod.ensure_addon_registered(src.get('addonId') or '')
            except Exception as exc:
                xbmc.log('[NuvioHub] auto-register failed after source edit: %s' % exc, xbmc.LOGWARNING)
    elif kind == 'multiCatalog':
        edit_modes = ['Manage Stremio add-ons in this folder', 'Convert this item to a Kodi path', 'Convert to path from widget/skin picker']
        mode = _select_dialog(tr('Edit link/source'), [tr(x) for x in edit_modes], preselect=0)
        if mode < 0:
            return
        if mode == 1:
            addon_row = _pick_installed_video_addon()
            if not addon_row:
                return
            route_url, route_label = _pick_kodi_plugin_route(addon_row)
            if not route_url:
                return
            media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'kodiPluginRoute', 'payload.addonId': addon_row.get('id') or '', 'payload.addonName': addon_row.get('name') or addon_row.get('id') or '', 'payload.route': route_url, 'payload.mediaFilter': media_filter, 'payload.thumbnail': addon_row.get('thumbnail') or '', 'payload.fanart': addon_row.get('fanart') or ''})
            if route_label:
                updates['name'] = route_label
        elif mode == 2:
            route_url, route_label, _addon_meta = _pick_skin_widget_route(default_label=entry.get('name') or '')
            if not route_url:
                return
            media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'kodiPluginRoute'})
            updates.update({'payload.%s' % k: v for k, v in _kodi_route_payload(route_url, label=route_label, media_filter=media_filter).items()})
            if route_label:
                updates['name'] = route_label
        else:
            new_sources = _collection_edit_multi_sources(payload)
            if new_sources is None:
                return
            if not new_sources:
                error(tr('Folder cannot be left with no add-ons'))
                return
            updates['kind'] = 'multiCatalog'
            updates['payload.sources'] = new_sources
            for src in new_sources:
                addon_ref = str((src or {}).get('addonId') or '').strip()
                if addon_ref.startswith(('http://', 'https://')):
                    try:
                        _collections_mod.ensure_addon_registered(addon_ref)
                    except Exception as exc:
                        xbmc.log('[NuvioHub] auto-register failed after multi source edit: %s' % exc, xbmc.LOGWARNING)
    elif kind == 'traktList':
        default_url = payload.get('url') or ('https://trakt.tv/users/%s/lists/%s' % (payload.get('username') or '', payload.get('listSlug') or payload.get('slug') or ''))
        raw_url = _prompt_text(str(default_url or ''), tr('Trakt list URL'))
        if raw_url is None:
            return
        parsed = _parse_trakt_list_url(raw_url)
        if not parsed:
            error(tr('Invalid Trakt URL'))
            return
        media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
        if media_filter is None:
            return
        updates.update({'payload.username': parsed['username'], 'payload.listSlug': parsed['slug'], 'payload.slug': parsed['slug'], 'payload.listName': payload.get('listName') or parsed.get('name') or '', 'payload.url': parsed['url'], 'payload.mediaFilter': media_filter})
    elif kind == 'mdblistList':
        default_url = payload.get('url') or ('https://mdblist.com/lists/%s/%s' % (payload.get('username') or '', payload.get('listSlug') or payload.get('slug') or ''))
        raw_url = _prompt_text(str(default_url or ''), tr('MDBList list URL'))
        if raw_url is None:
            return
        parsed = _parse_mdblist_list_url(raw_url)
        if not parsed:
            error(tr('Invalid MDBList URL'))
            return
        media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
        if media_filter is None:
            return
        updates.update({'payload.username': parsed['username'], 'payload.listSlug': parsed['slug'], 'payload.slug': parsed['slug'], 'payload.listName': payload.get('listName') or parsed.get('name') or '', 'payload.url': parsed['url'], 'payload.mediaFilter': media_filter})
    elif kind == 'kodiPluginRoute':
        edit_modes = ['Choose from Stremio add-ons', 'Choose from widget/skin picker', 'Browse a Kodi addon', 'Manual path entry']
        mode = _select_dialog(tr('Edit link/source'), [tr(x) for x in edit_modes], preselect=1)
        if mode < 0:
            return
        if mode == 0:
            src = _collection_prompt_catalog_source({})
            if not src:
                return
            media_filter = _pick_collection_media_filter(src.get('catalogType') or 'auto')
            if media_filter is None:
                return
            updates.update({
                'kind': 'addonCatalog',
                'payload.addonId': src.get('addonId') or '',
                'payload.catalogId': src.get('catalogId') or '',
                'payload.catalogType': src.get('catalogType') or 'movie',
                'payload.genre': src.get('genre') or '',
                'payload.extra': src.get('extra') or {},
                'payload.mediaFilter': media_filter,
                'payload.addonName': '',
                'payload.route': '',
                'payload.thumbnail': '',
                'payload.fanart': '',
            })
            default_label = _derive_name_from_slug(src.get('catalogId') or '') or entry.get('name') or 'Stremio'
            if default_label:
                updates['name'] = default_label
            try:
                _collections_mod.ensure_addon_registered(src.get('addonId') or '')
            except Exception as exc:
                xbmc.log('[NuvioHub] auto-register failed after source edit: %s' % exc, xbmc.LOGWARNING)
        else:
            if mode == 1:
                route_url, route_label, _addon_meta = _pick_skin_widget_route(default_route=str(payload.get('route') or ''), default_label=entry.get('name') or '')
            elif mode == 2:
                addon_row = _pick_installed_video_addon()
                if not addon_row:
                    return
                route_url, route_label = _pick_kodi_plugin_route(addon_row, default_route=str(payload.get('route') or 'plugin://%s/' % addon_row.get('id')))
            else:
                typed = _prompt_text(str(payload.get('route') or ''), tr('Paste the full path: plugin://, videodb://, or library://'))
                if typed is None:
                    return
                route_url = _extract_kodi_path_from_widget_value(typed)
                route_label = entry.get('name') or payload.get('addonName') or 'Kodi'
            if not route_url:
                return
            media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
            if media_filter is None:
                return
            updates.update({'kind': 'kodiPluginRoute'})
            updates.update({'payload.%s' % k: v for k, v in _kodi_route_payload(route_url, label=route_label, media_filter=media_filter).items()})
            if route_label:
                updates['name'] = route_label
    elif kind == 'localJsonCatalog':
        file_path = _prompt_local_json_file()
        if file_path is None or not str(file_path).strip():
            return
        try:
            raw_text = _read_text_from_path(file_path)
            _rows, _meta = _parse_local_json_catalog(raw_text)
        except Exception as exc:
            error(tr('Failed to read JSON file: %s') % exc)
            return
        media_filter = _pick_collection_media_filter(payload.get('mediaFilter') or 'auto')
        if media_filter is None:
            return
        limit_text = _prompt_text(str(payload.get('limit') or '60'), 'Item limit (0 = no limit)')
        if limit_text is None:
            return
        try:
            limit = max(0, int(limit_text or '0'))
        except Exception:
            limit = int(payload.get('limit') or 60)
        updates.update({'payload.filePath': str(file_path).strip(), 'payload.mediaFilter': media_filter, 'payload.limit': limit})
    else:
        error(tr('Unsupported shortcut type for editing'))
        return
    try:
        _collections_mod.update_entry(set_id, entry_id, updates)
        notify(tr('Add-on updated'))
    except Exception as exc:
        error(tr('Update failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')

def collection_entry_remove(set_id, entry_id):
    if not xbmcgui.Dialog().yesno('Nuvio Hub', tr('Do you want to remove this item?')):
        return
    try:
        _collections_mod.remove_entry(set_id, entry_id)
        notify(tr('Removed'))
    except Exception as exc:
        error(tr('Failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')




def collection_entry_edit_widget(set_id, entry_id):
    """Replace the current collection item with a Skin Shortcuts/widget path.

    This is deliberately separate from collection_entry_add_widget(): from the
    context menu the user can now choose either edit-current or add-new, instead
    of one ambiguous option that always created another item.
    """
    row = _collections_mod.get_set(set_id)
    if not row:
        error(tr('Collection not found'))
        return
    entry = next((e for e in (row.get('entries') or []) if e.get('id') == entry_id), None)
    if not entry:
        error(tr('Item not found'))
        return
    payload = entry.get('payload') or {}
    route_url, route_label, addon_meta = _pick_skin_widget_route(
        default_route=str(payload.get('route') or ''),
        default_label=entry.get('name') or payload.get('addonName') or ''
    )
    if not route_url:
        return
    media_filter = payload.get('mediaFilter') or 'auto'
    updates = {'kind': 'kodiPluginRoute'}
    updates.update({'payload.%s' % k: v for k, v in _kodi_route_payload(route_url, label=route_label, media_filter=media_filter).items()})
    # Clear Stremio/list-specific leftovers when converting an existing item.
    for k in ('catalogId', 'catalogType', 'genre', 'extra', 'username', 'listSlug', 'slug', 'listName', 'url', 'filePath', 'limit'):
        updates['payload.%s' % k] = {} if k == 'extra' else ''
    if route_label:
        updates['name'] = route_label
    elif not entry.get('name'):
        updates['name'] = (addon_meta or {}).get('name') or _addon_id_from_kodi_path(route_url) or 'Kodi'
    try:
        _collections_mod.update_entry(set_id, entry_id, updates)
        notify(tr('Path updated'))
    except Exception as exc:
        error(tr('Edit failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')


def collection_entry_edit_stremio(set_id, entry_id):
    """Replace the current collection item with a Stremio catalog source."""
    row = _collections_mod.get_set(set_id)
    if not row:
        error(tr('Collection not found'))
        return
    entry = next((e for e in (row.get('entries') or []) if e.get('id') == entry_id), None)
    if not entry:
        error(tr('Item not found'))
        return
    payload = entry.get('payload') or {}
    src = _collection_prompt_catalog_source(payload if entry.get('kind') == 'addonCatalog' else {})
    if not src:
        return
    media_filter = _pick_collection_media_filter(src.get('catalogType') or payload.get('mediaFilter') or 'auto')
    if media_filter is None:
        return
    updates = {
        'kind': 'addonCatalog',
        'payload.addonId': src.get('addonId') or '',
        'payload.catalogId': src.get('catalogId') or '',
        'payload.catalogType': src.get('catalogType') or 'movie',
        'payload.genre': src.get('genre') or '',
        'payload.extra': src.get('extra') or {},
        'payload.mediaFilter': media_filter,
        # Clear Kodi-route/list-specific leftovers when converting.
        'payload.addonName': '',
        'payload.route': '',
        'payload.thumbnail': '',
        'payload.fanart': '',
        'payload.username': '',
        'payload.listSlug': '',
        'payload.slug': '',
        'payload.listName': '',
        'payload.url': '',
        'payload.filePath': '',
        'payload.limit': '',
    }
    default_label = _derive_name_from_slug(src.get('catalogId') or '') or 'Stremio'
    if default_label:
        updates['name'] = default_label
    try:
        _collections_mod.ensure_addon_registered(src.get('addonId') or '')
    except Exception as exc:
        xbmc.log('[NuvioHub] auto-register failed after direct Stremio edit: %s' % exc, xbmc.LOGWARNING)
    try:
        _collections_mod.update_entry(set_id, entry_id, updates)
        notify(tr('Stremio add-on updated'))
    except Exception as exc:
        error(tr('Edit failed: %s') % exc)
    xbmc.executebuiltin('Container.Refresh')


def _clear_collection_source_payload_updates():
    updates = {}
    for k in ('catalogId', 'catalogType', 'genre', 'username', 'listSlug', 'slug', 'listName', 'url', 'filePath', 'limit'):
        updates['payload.%s' % k] = ''
    updates['payload.extra'] = {}
    return updates


def _collection_list_clear_updates():
    updates = {
        'payload.addonId': '',
        'payload.addonName': '',
        'payload.catalogId': '',
        'payload.catalogType': '',
        'payload.genre': '',
        'payload.extra': {},
        'payload.route': '',
        'payload.thumbnail': '',
        'payload.fanart': '',
        'payload.filePath': '',
        'payload.limit': '',
    }
    return updates


def _collection_prompt_trakt_payload(current_payload=None):
    current_payload = current_payload or {}
    default_url = current_payload.get('url') or ''
    if not default_url and current_payload.get('username') and (current_payload.get('listSlug') or current_payload.get('slug')):
        default_url = 'https://trakt.tv/users/%s/lists/%s' % (current_payload.get('username') or '', current_payload.get('listSlug') or current_payload.get('slug') or '')
    raw_url = _prompt_text(str(default_url or ''), tr('Trakt list URL'))
    if raw_url is None:
        return None
    parsed = _parse_trakt_list_url(raw_url)
    if not parsed:
        error(tr('Invalid Trakt URL'))
        return None
    media_filter = _pick_collection_media_filter(current_payload.get('mediaFilter') or 'auto')
    if media_filter is None:
        return None
    return {
        'username': parsed['username'],
        'listSlug': parsed['slug'],
        'slug': parsed['slug'],
        'listName': parsed.get('name') or '',
        'url': parsed['url'],
        'mediaFilter': media_filter,
    }


def _collection_prompt_mdblist_payload(current_payload=None):
    current_payload = current_payload or {}
    default_url = current_payload.get('url') or ''
    if not default_url and current_payload.get('username') and (current_payload.get('listSlug') or current_payload.get('slug')):
        default_url = 'https://mdblist.com/lists/%s/%s' % (current_payload.get('username') or '', current_payload.get('listSlug') or current_payload.get('slug') or '')
    raw_url = _prompt_text(str(default_url or ''), tr('MDBList list URL'))
    if raw_url is None:
        return None
    parsed = _parse_mdblist_list_url(raw_url)
    if not parsed:
        error(tr('Invalid MDBList URL'))
        return None
    media_filter = _pick_collection_media_filter(current_payload.get('mediaFilter') or 'auto')
    if media_filter is None:
        return None
    return {
        'username': parsed['username'],
        'listSlug': parsed['slug'],
        'slug': parsed['slug'],
        'listName': parsed.get('name') or '',
        'url': parsed.get('url') or raw_url,
        'mediaFilter': media_filter,
    }


