def _content_type_from_plugin_rows(rows):
    # Match the helper/source content type when it is obvious.  Mixed Kodi
    # folders still use movies because it gives poster-wall rendering instead
    # of the square generic file view.
    kinds = set()
    for row in rows or []:
        mt = _plugin_row_media_type(row)
        if mt:
            kinds.add(mt)
    if kinds and kinds.issubset(set(['episode'])):
        return 'episodes'
    if kinds and kinds.issubset(set(['tvshow', 'season'])):
        return 'tvshows'
    return 'movies'


def kodi_route_browse(route='', title='', background='', page='0'):
    route_url = str(route or '').strip()
    if not route_url.startswith('plugin://'):
        error(tr('Invalid plugin route'))
        return end_dir(content='files')
    rows = _list_plugin_directory_items(route_url)
    if not rows:
        # Last-resort fallback: some plugins refuse JSON-RPC directory reads but
        # work with a native Container.Update. Use replace to avoid a deep back
        # stack and duplicate helper windows.
        try:
            xbmc.executebuiltin('Container.Update(%s,replace)' % _kodi_builtin_arg(route_url))
            return
        except Exception:
            error(tr('Path is empty or unreadable'))
            return end_dir(content='files')

    page_num, _ps, visible, has_more = _page_slice(rows, page)
    win = xbmcgui.Window(WINDOW_ID)
    if background:
        win.setProperty('fanart', background)
    root_label = title or route_url
    for row in visible:
        item_url = str(row.get('file') or '').strip()
        label = row.get('label') or row.get('title') or item_url or 'Item'
        art = _plugin_row_art(row, background=background)
        fanart = art.get('fanart') or background or addon_fanart()
        info = _plugin_row_info(row, label=label)
        ids = _plugin_row_ids(row)
        cast = info.pop('cast', None) if isinstance(info.get('cast'), list) else None
        if row.get('is_folder'):
            path = build_url(action='kodi_route_browse', route=item_url, title=label, background=fanart or background, page='0')
            ctx_menu = [(tr('Open with original path'), 'Container.Update(%s)' % _kodi_builtin_arg(item_url))]
            add_item(label, path, is_folder=True, info=info, art=art, ids=ids, cast=cast, context_menu=ctx_menu)
        else:
            # Keep playable plugin items in Nuvio Hub's list. Kodi will hand them
            # back to their own addon on click, but now with the same rich art
            # and InfoTag fields that the source/TMDb Helper exposed.
            add_item(label, item_url, is_folder=False, info=info, art=art, ids=ids, cast=cast, properties={'IsPlayable': 'true'}, context_menu=[(tr('Open with original path'), 'RunPlugin(%s)' % _kodi_builtin_arg(item_url))])
    if has_more:
        if not globals().get('_pagination_hidden', lambda: False)():
            add_item(tr('More'), build_url(action='kodi_route_browse', route=route_url, title=root_label, background=background, page=str(page_num + 1)), info={'title': tr('More'), 'plot': tr('Load more items from this path')}, art=root_art('catalogs'))
    end_dir(content=_content_type_from_plugin_rows(rows), cache=False)


def _open_kodi_plugin_route_entry(entry, payload):
    # Keep the exact route that was saved in the collection.  Do not normalize
    # TMDb Helper paths here; v3.9.119 did not rewrite them and that is the
    # known-good behaviour for avoiding Kodi "playback failed" on shortcuts.
    route_url = str((payload or {}).get('route') or (payload or {}).get('url') or '').strip()
    if not route_url:
        error(tr('Shortcut is incomplete'))
        return end_dir()

    # This handler is only used as a fallback when the card itself was not a
    # raw plugin:// folder.  Builtins and non-plugin containers can be launched
    # natively, while plugin:// folders fall back to Nuvio Hub's safe browser.
    try:
        extracted = _extract_kodi_path_from_widget_value(route_url)
    except Exception:
        extracted = route_url
    launch_route = extracted or route_url
    if _is_kodi_builtin(launch_route) or (_is_kodi_native_uri(launch_route) and not str(launch_route).lower().startswith('plugin://')):
        if _open_plugin_route_native(launch_route):
            try:
                xbmcplugin.endOfDirectory(HANDLE, succeeded=False)
            except Exception:
                pass
            return

    return kodi_route_browse(route=route_url, title=entry.get('name') or payload.get('addonName') or route_url, background=entry.get('background') or payload.get('fanart') or '')


def trakt_list_browse(username, slug, title='', background='', media_filter='auto', page='0', force_remote=''):
    """Render a public Trakt user list as a folder of movies/shows.

    Uses Trakt extended metadata and enriches artwork from TMDb Helper cache,
    with direct TMDb fallback when available.
    """
    force_remote = _force_remote_posters_enabled(force_remote)
    try:
        rows = trakt.fetch_user_list(username, slug) or []
    except Exception as exc:
        error(tr('Failed to read Trakt list: %s') % exc)
        return end_dir()
    if not rows:
        error(tr('The list is empty or unavailable'))
        return end_dir()

    media_filter = str(media_filter or 'auto').strip().lower()
    if media_filter in ('movie', 'movies'):
        rows = [r for r in rows if (str((r.get('type') or '')).lower() == 'movie' or r.get('movie'))]
    elif media_filter in ('series', 'show', 'shows', 'tv', 'anime'):
        rows = [r for r in rows if (str((r.get('type') or '')).lower() == 'show' or r.get('show'))]
    page_num, _page_size, visible_rows, has_more = _page_slice(rows, page)

    win = xbmcgui.Window(WINDOW_ID)
    if background:
        win.setProperty('fanart', background)

    any_series = False
    any_movie = False
    first_fanart = background or ''
    for row in visible_rows:
        item_type = (row.get('type') or '').lower()
        meta = row.get(item_type) if item_type in ('movie', 'show') else (row.get('movie') or row.get('show'))
        if not isinstance(meta, dict):
            continue
        ids = meta.get('ids') or {}
        name = meta.get('title') or ''
        year = meta.get('year') or ''
        imdb = str(ids.get('imdb') or '').strip()
        tmdb = str(ids.get('tmdb') or '').strip()
        tvdb = str(ids.get('tvdb') or '').strip()

        if imdb:
            canonical = imdb if imdb.startswith('tt') else 'tt%s' % imdb
        elif tmdb:
            canonical = 'tmdb:%s' % tmdb
        elif tvdb:
            canonical = 'tvdb:%s' % tvdb
        else:
            continue

        is_series = item_type == 'show' or bool(row.get('show'))
        media_type = 'series' if is_series else 'movie'
        if is_series:
            any_series = True
            action = 'series_meta'
        else:
            any_movie = True
            action = 'streams'

        explicit_virtual_source = _target_meta_source_is_explicit('virtual.collection.trakt')
        explicit_virtual_source_id = _target_meta_source_id('virtual.collection.trakt')
        # Explicit TMDb Helper should still prefill from the helper/local TMDb
        # resolver. The old logic blanked art_bundle for every explicit source,
        # so TMDb Helper folders could render with generic video icons unless
        # the helper DB already had a perfect match.
        skip_seed_art = explicit_virtual_source and explicit_virtual_source_id not in ('tmdb_helper',)
        art_bundle = {} if skip_seed_art else _trakt_art_bundle(ids, media_type, title=name, year=year, meta=meta, force_remote=force_remote, allow_direct=bool(force_remote))
        virtual_meta = _virtual_meta_override('virtual.collection.trakt', media_type, {
            'id': canonical,
            'name': name,
            'title': name,
            'year': year,
            'poster': art_bundle.get('poster') or '',
            'background': art_bundle.get('fanart') or art_bundle.get('landscape') or '',
            'fanart': art_bundle.get('fanart') or art_bundle.get('landscape') or '',
            'landscape': art_bundle.get('landscape') or art_bundle.get('fanart') or '',
            'clearlogo': art_bundle.get('clearlogo') or '',
            'logo': art_bundle.get('clearlogo') or '',
        })
        if explicit_virtual_source:
            fanart = virtual_meta.get('background') or virtual_meta.get('fanart') or virtual_meta.get('landscape') or background or addon_fanart()
        else:
            fanart = virtual_meta.get('background') or virtual_meta.get('fanart') or virtual_meta.get('landscape') or art_bundle.get('fanart') or art_bundle.get('landscape') or background or addon_fanart()
        if fanart and not first_fanart:
            first_fanart = fanart
        if explicit_virtual_source:
            art = {
                'thumb': virtual_meta.get('poster') or '',
                'poster': virtual_meta.get('poster') or '',
                'fanart': fanart,
                'landscape': virtual_meta.get('landscape') or virtual_meta.get('fanart') or '',
                'clearlogo': virtual_meta.get('clearlogo') or '',
            }
        else:
            art = {
                'thumb': virtual_meta.get('poster') or art_bundle.get('poster') or root_art('trakt').get('poster') or '',
                'poster': virtual_meta.get('poster') or art_bundle.get('poster') or root_art('trakt').get('poster') or '',
                'fanart': fanart,
                'landscape': virtual_meta.get('landscape') or art_bundle.get('landscape') or art_bundle.get('fanart') or '',
                'clearlogo': virtual_meta.get('clearlogo') or art_bundle.get('clearlogo') or '',
            }
        if art.get('clearlogo'):
            art['logo'] = art.get('clearlogo')
            art['tvshow.clearlogo'] = art.get('clearlogo')
        display_name = str(virtual_meta.get('name') or virtual_meta.get('title') or name).strip() or name
        info = _trakt_info(meta, media_type)
        # If the user picked a virtual metadata source (especially TMDb Helper),
        # the listing InfoTag must come from that source too — not only the art.
        # Otherwise skins still show Trakt/MDBList text while posters/logos come
        # from TMDb Helper, which feels unlike opening TMDb Helper directly.
        try:
            rich_info = _meta_info(virtual_meta) or {}
            if rich_info:
                info.update(rich_info)
        except Exception:
            pass
        info['title'] = display_name
        info['sorttitle'] = display_name
        info['mediatype'] = 'tvshow' if is_series else 'movie'
        ids_out = {'imdb_id': imdb if imdb.startswith('tt') else ('tt%s' % imdb if imdb else ''), 'tmdb_id': tmdb, 'tvdb_id': tvdb}
        try:
            _meta_mem_put(media_type, canonical, virtual_meta, source_provider_id='virtual.collection.trakt')
        except Exception:
            pass
        path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=canonical, title=display_name, tmdb_id=tmdb, imdb_id=ids_out.get('imdb_id') or '', tvdb_id=tvdb, source_provider_id='virtual.collection.trakt', ui_seed=art)
        ctx_menu = [(tr('Change metadata add-on'), 'RunPlugin(%s)' % build_url(action='meta_pick_target', target_key='virtual.collection.trakt', title=tr('Collection • Trakt items')))] + _build_source_picker_menu(media_type=media_type, canonical_id=canonical, title=display_name, source_provider_id='virtual.collection.trakt') + _build_player_chooser_menu(
            media_type=media_type,
            canonical_id=canonical,
            title=display_name,
            tmdb_id=tmdb,
            imdb_id=ids_out.get('imdb_id') or '',
            tvdb_id=tvdb,
            source_provider_id='virtual.collection.trakt',
        )
        tmdbh_url = _tmdbh_url_from_ids(media_type=media_type, tmdb_id=tmdb, imdb_id=ids_out.get('imdb_id') or '', tvdb_id=tvdb, title=display_name)
        # TMDb Helper already available via "اختيار المشغّل…"; skip duplicate direct entry.
        add_item(display_name, path, is_folder=path_is_folder, info=info, art=art, ids=ids_out, context_menu=ctx_menu)

    if has_more:
        add_item(
            'More',
            build_url(action='trakt_list_browse', username=username, slug=slug, title=title, background=background, media_filter=media_filter, page=str(page_num + 1), **_force_remote_query(force_remote)),
            info={'title': 'More', 'plot': 'Load more Trakt list items'},
            art=root_art('trakt'),
        )
    if first_fanart:
        win.setProperty('fanart', first_fanart)
    content = ('tvshows' if any_series and not any_movie else
               ('movies' if any_movie and not any_series else 'videos'))
    end_dir(content=content)

def _render_idlist_rows(rows, more_url='', title='', background='', media_filter='auto', force_remote=False):
    """Shared renderer for id-shaped catalog rows (v4.1.0).

    Consumes rows shaped {'_type','title','year'/'release_year','overview',
    'ids':{'imdb','tmdb','tvdb'}, ...} — produced today by MDBList lists,
    the MDBList account watchlist, and Simkl status lists. Extracted verbatim
    from mdblist_list_browse so all four entry points share one body;
    `more_url` (prebuilt by the caller) replaces the old inline cursor logic.
    """
    if not rows:
        error(tr('The list is empty or unavailable'))
        return end_dir()

    win = xbmcgui.Window(WINDOW_ID)
    if background:
        win.setProperty('fanart', background)

    any_series = False
    any_movie = False
    first_fanart = background or ''
    for meta in rows:
        item_type = str(meta.get('_type') or meta.get('mediatype') or '').lower()
        is_series = item_type in ('show', 'series', 'tv', 'anime')
        media_type = 'series' if is_series else 'movie'
        raw_ids = meta.get('ids')
        ids = dict(raw_ids) if isinstance(raw_ids, dict) else {}
        imdb = str(ids.get('imdb') or meta.get('imdb_id') or '').strip()
        tmdb = str(ids.get('tmdb') or meta.get('id') or '').strip()
        tvdb = str(ids.get('tvdb') or meta.get('tvdb_id') or '').strip()
        ids.update({'imdb': imdb, 'tmdb': tmdb, 'tvdb': tvdb})
        name = meta.get('title') or ''
        year = meta.get('release_year') or meta.get('year') or ''

        if imdb:
            canonical = imdb if imdb.startswith('tt') else 'tt%s' % imdb
        elif tmdb:
            canonical = 'tmdb:%s' % tmdb
        elif tvdb:
            canonical = 'tvdb:%s' % tvdb
        else:
            continue

        action = 'series_meta' if is_series else 'streams'
        if is_series:
            any_series = True
        else:
            any_movie = True

        explicit_virtual_source = _target_meta_source_is_explicit('virtual.collection.trakt')
        explicit_virtual_source_id = _target_meta_source_id('virtual.collection.trakt')
        # Explicit TMDb Helper should still prefill from the helper/local TMDb
        # resolver. The old logic blanked art_bundle for every explicit source,
        # so TMDb Helper folders could render with generic video icons unless
        # the helper DB already had a perfect match.
        skip_seed_art = explicit_virtual_source and explicit_virtual_source_id not in ('tmdb_helper',)
        art_bundle = {} if skip_seed_art else _trakt_art_bundle(ids, media_type, title=name, year=year, meta=meta, force_remote=force_remote, allow_direct=bool(force_remote))
        # v4.2.0: rows can carry their own poster (Simkl serves one directly).
        # Seed it under the TMDb pipeline result, and fall back to MetaHub by
        # imdb id as the last resort — a list row must never render as a bare
        # file icon just because the art pipeline came up empty.
        row_poster = str(meta.get('poster') or '').strip()
        if row_poster and not art_bundle.get('poster'):
            art_bundle = dict(art_bundle)
            art_bundle['poster'] = row_poster
        if not art_bundle.get('poster') and imdb:
            art_bundle = dict(art_bundle)
            art_bundle['poster'] = _METAHUB_POSTER % (imdb if imdb.startswith('tt') else 'tt%s' % imdb)
        virtual_meta = _virtual_meta_override('virtual.collection.trakt', media_type, {
            'id': canonical, 'name': name, 'title': name, 'year': year,
            'poster': art_bundle.get('poster') or '',
            'background': art_bundle.get('fanart') or art_bundle.get('landscape') or '',
            'fanart': art_bundle.get('fanart') or art_bundle.get('landscape') or '',
            'landscape': art_bundle.get('landscape') or art_bundle.get('fanart') or '',
            'clearlogo': art_bundle.get('clearlogo') or '',
            'logo': art_bundle.get('clearlogo') or '',
        })
        if explicit_virtual_source:
            fanart = virtual_meta.get('background') or virtual_meta.get('fanart') or virtual_meta.get('landscape') or background or addon_fanart()
        else:
            fanart = virtual_meta.get('background') or virtual_meta.get('fanart') or virtual_meta.get('landscape') or art_bundle.get('fanart') or art_bundle.get('landscape') or background or addon_fanart()
        if fanart and not first_fanart:
            first_fanart = fanart
        if explicit_virtual_source:
            art = {
                'thumb': virtual_meta.get('poster') or '',
                'poster': virtual_meta.get('poster') or '',
                'fanart': fanart,
                'landscape': virtual_meta.get('landscape') or virtual_meta.get('fanart') or '',
                'clearlogo': virtual_meta.get('clearlogo') or '',
            }
        else:
            art = {
                'thumb': virtual_meta.get('poster') or art_bundle.get('poster') or root_art('catalogs').get('poster') or '',
                'poster': virtual_meta.get('poster') or art_bundle.get('poster') or root_art('catalogs').get('poster') or '',
                'fanart': fanart,
                'landscape': virtual_meta.get('landscape') or art_bundle.get('landscape') or art_bundle.get('fanart') or '',
                'clearlogo': virtual_meta.get('clearlogo') or art_bundle.get('clearlogo') or '',
            }
        if art.get('clearlogo'):
            art['logo'] = art.get('clearlogo')
            art['tvshow.clearlogo'] = art.get('clearlogo')
        display_name = str(virtual_meta.get('name') or virtual_meta.get('title') or name).strip() or name
        info = {'title': display_name, 'sorttitle': display_name, 'plot': meta.get('overview') or meta.get('description') or '', 'mediatype': 'tvshow' if is_series else 'movie'}
        if year:
            try:
                info['year'] = int(year)
            except Exception:
                pass
        try:
            rich_info = _meta_info(virtual_meta) or {}
            if rich_info:
                info.update(rich_info)
        except Exception:
            pass
        info['title'] = display_name
        info['sorttitle'] = display_name
        info['mediatype'] = 'tvshow' if is_series else 'movie'
        ids_out = {'imdb_id': imdb if imdb.startswith('tt') else ('tt%s' % imdb if imdb else ''), 'tmdb_id': tmdb, 'tvdb_id': tvdb}
        try:
            _meta_mem_put(media_type, canonical, virtual_meta, source_provider_id='virtual.collection.trakt')
        except Exception:
            pass
        path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=canonical, title=display_name, tmdb_id=tmdb, imdb_id=ids_out.get('imdb_id') or '', tvdb_id=tvdb, source_provider_id='virtual.collection.trakt', ui_seed=art)
        ctx_menu = [(tr('Change metadata add-on'), 'RunPlugin(%s)' % build_url(action='meta_pick_target', target_key='virtual.collection.trakt', title=tr('Collection • Trakt items')))] + _build_source_picker_menu(media_type=media_type, canonical_id=canonical, title=display_name, source_provider_id='virtual.collection.trakt') + _build_player_chooser_menu(media_type=media_type, canonical_id=canonical, title=display_name, tmdb_id=tmdb, imdb_id=ids_out.get('imdb_id') or '', tvdb_id=tvdb, source_provider_id='virtual.collection.trakt')
        add_item(display_name, path, is_folder=path_is_folder, info=info, art=art, ids=ids_out, context_menu=ctx_menu)

    if more_url:
        if not globals().get('_pagination_hidden', lambda: False)():
            add_item(tr('More'), more_url, info={'title': tr('More'), 'plot': tr('Load more items from the list')}, art=root_art('catalogs'))
    if first_fanart:
        win.setProperty('fanart', first_fanart)
    content = ('tvshows' if any_series and not any_movie else
               ('movies' if any_movie and not any_series else 'videos'))
    end_dir(content=content)



def mdblist_list_browse(username, slug, title='', background='', media_filter='auto', cursor='', force_remote=''):
    force_remote = _force_remote_posters_enabled(force_remote)
    try:
        rows, next_cursor = mdblist.fetch_items(username, slug, media_filter=media_filter, cursor=cursor, limit=_listing_page_size())
    except Exception as exc:
        error(tr('Failed to read MDBList list: %s') % exc)
        return end_dir()
    more_url = ''
    if next_cursor:
        more_url = build_url(action='mdblist_list_browse', username=username, slug=slug, title=title, background=background, media_filter=media_filter, cursor=next_cursor, **_force_remote_query(force_remote))
    return _render_idlist_rows(rows, more_url=more_url, title=title, background=background, media_filter=media_filter, force_remote=force_remote)


